/* 平成27年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h27.committeeSessions.push(...[{"id":"h27-20151130-9","meetingId":"h27-cm11","date":"2015年11月30日","dateIso":"2015-11-30","committee":"文教委員会","time":"午前１０時００分～午後 ５時５７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を136件抜き出しています。","topics":[{"id":"topic-01","title":"本日の議案審査の進め方","agenda":"本日の議案審査の進め方","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"条例の第３０条の第２項中というところからの説明、これは勤勉手当なのですけれども、この１００分の８０が１００分の９０にという改定がどういう意味をしているのか、勤勉手当の中身で、数字で申しわけないのですけれども、教えていただきたい。条例の付則のところに書いてある切替日とはどういう中身なのか、意味を教えてください。","respondent":"渋谷指導課長","answer":"確認なのですけれども、１点目の１００分の何とかというのは、どこに書いてあるのですか。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"切替日とはどういう意味。条例文の付則のところに書いてあるのです。文言がわからないので教えてください。","respondent":"渋谷指導課長","answer":"切替日については、施行日の前日までの間における異動者の号給ということで、条例の施行される日にちが平成２７年４月１日からになるという日程です。それから、１００分の９０というのは、給与月額に１００分の９０を掛けた額が限度額になっているというものを定めた比率です。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"こういう書き方をして、この範囲ですよというものがもともと決まっているのが、１００分の８０が９０になったということなのですね。総務委員会で聞くのかもしれないのですが、Ａ４の説明の裏側の期末手当ではなくて、今回は勤勉手当で０.１月を支給するということで、その時々によって、きっと話し合いで決まると思うのですが、期末手当ではなくて勤勉手当になることの影響はあるのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"浅野委員","kind":"質問","question":"今回の職員の給与改定についてということですが、細かいところはなかなか難しいものがありまして、理解できているとは、私も到底自分では言えないと思うのですけれども、総額の幼稚園教育職員の給与、また学校教育職員の給与が全体でそれぞれどのくらい上がるのか。全体でそれぞれを教えていただければと思います。","respondent":"渋谷指導課長","answer":"これは、１人当たりということでよろしいでしょうか。全体。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"２８０万円強、全体で年間に上がるということです。これは、毎年のように改正されていると思うのですけれども、大体２００万円から３００万円近く毎年上がっていくというイメージなのでしょうか。これは教員の数にもよると思うのですけれども、総じてどのような流れに毎年なっているのかということの概略を教えてください。","respondent":"渋谷指導課長","answer":"今回の人事委員会勧告の補正によって、今２８０万円余のお金が必要になってくるのですが、実際のところ、幼稚園の教諭で２名、育児休業になっていたり、固有教員でも２名が育児休業になっていて、その分、給料が支払われなかったりするので。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"概略的なところをお伺いしたのですけれども、さまざま要因があって、変化はしていると思います。民間に対してどうなのかとか、そういう流れの中で、やはり適正な賃金にされていくという流れだと思いますので、その点については了解いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"第８８号議案、品川区立保育所条例の一部を改正する条例","agenda":"第８８号議案、品川区立保育所条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今回は５年間の暫定ということなのですけれども、設置の条例については、５年間とか書くところはないのですね。その点が１点です。今回、公設民営ということなのですけれども、指定管理者と委託の違いを教えてください。","respondent":"今井待機児童対策担当課長","answer":"１点目に、こちらは施設の名称と所在地を記載するものですので、期間の記載は必要ございません。それから、公設民営につきまして、指定管理と委託の違いです。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"公設民営で委託は多分初めてかと捉えているのですけれども、今、指定管理との違いもお聞きしました。なぜ直営でしないのか。どうして民営なのか。この点に関して、非常に残念な思いをしているのですけれども、なぜ委託の手法をとるのかというところをお答えいただきたいと思います。","respondent":"今井待機児童対策担当課長","answer":"委員ご案内のとおり、品川区で平成２２年から保育園の株式会社立等の開設を進めてまいりましたけれども、それに先立って、国では多様な設置主体によりまして、待機児童対策を進めていこうという中では、これだけ社会福祉法人だけではなく。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"質問の本旨は、なぜ品川区の直営で、品川区が運営する保育園にならなかったのかというところなので、そこのところをもう一回お答えいただきたいのと、あと、開所時間のところなのです。１９時３０分というところで、ここがどういう経過でこの時間になったのかという判断をお聞かせください。","respondent":"今井待機児童対策担当課長","answer":"初めに、なぜ区立ではないのかということですけれども、品川区は今、新規開設については、民間事業者等の活力を得ながら進めていくという方針ですので、まずは民間事業者の活力を得る方法から検討して進めたところです。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"なぜ区立でないのかというところは、明日、「区立保育園の今後の運営について」という報告があるので、そこでじっくりとご意見を伺いたいなと思っています。開所時間は、次への移行というのももちろんそうなのですが、駅から近いこともあるし、大体この辺で大丈夫だろうといった判断があったのかなと思うのですけれども、もう一回、その点はいかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"私ども、これを検討するにあたりましては、やはり今後の移行のスムーズなところも第一点でございましたけれども、委員ご案内のとおり、午後７時半というのは、お迎えが大体午後７時ぐらいまでのところでピークを迎えますので、適切な時間だと考えています。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"今回の保育所条例の一部改正で、本格始動ということで、いよいよ建設も進められて、４月スタートということで、動かれているのかと思います。大した質問ではないのですけれども、１つだけお伺いしたいことがあります。後学のために。","respondent":"今井待機児童対策担当課長","answer":"委員ご案内のとおり、こちらの条例の設置以降は、どんどん設置順番に付番しているわけですけれども、今、こういう形で区立の条例で規定する区立保育園が４４カ所あるという形で、もし１つ途中で廃園ということに至れば、番号が繰り上がるといいますか。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問・要望","question":"多分、番号にも意味があるのだろうと私は思っているのです。やはり開園していて、その園が閉園した場合にはどうなるのかというのは、今、事例がないというお話なのでしょうか。そういう事例も、今後、もしかすると出てくる可能性もあるので、そこら辺のルールは区の中で統一のとれた考え方で進めていっていただいたほうがいいかと。これは要望ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"意見","question":"品川区立ひろまち保育園ということで、広町の字を平仮名にしたのは何でかなと、ただそれだけなのです。大体地域の名前がつく区立保育園はそういうところが多いと思うのですけれども、大体漢字なのですけれども、何で平仮名になったのか。誰が考えたのか、その点が疑問です。","respondent":"今井待機児童対策担当課長","answer":"委員ご案内のとおり、基本的には町丁目の名前、五反田ですとか、そういうものがあるのですけれども、例えば、豊町にありますゆたか保育園は豊町保育園と言いませんで、平仮名で「ゆたか」となっております。わかりやすさという形も含めて、今回検討したものです。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、３００人規模ということで、大変大きな保育園になっていると。父母の皆様からも大丈夫なのかという声がまだまだ聞こえてくるところなのですけれども、保育士、また働いている方々の確保状況は、保育士も集まりづらいという状況のもとで、何か聞いているでしょうか。伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"私どもも保育士の確保については、いろいろな情報共有をしておりますけれども、現在のところスムーズに行われていると聞いております。","id":"exchange-014"},{"speaker":"伊藤副委員長","kind":"確認","question":"３つお伺いしたいのですけれども、１つは、前にお話をしていたのですが、通園の安全性の確保について。それから、ほかの地域であったことですけれども、地域に説明がほしいと。例えば、この場所で、こういう規模の保育園を開くにあたって、地域の町会長や商店街の会長なり、そういう話をしてほしいという話があったのですけれども、それを夢工房はなさったのでしょうかということの確認をお願いいたします。","respondent":"今井待機児童対策担当課長","answer":"いろいろご指摘もいただきましたので、登園・降園ルートにつきましては、これから入園される方、保護者への保育の説明会の中でも細かく説明していきますし、自転車の駐輪などに関しましても、丁寧に説明をして。","id":"exchange-015"},{"speaker":"伊藤副委員長","kind":"質問","question":"交通安全のことは、そんなに難しいことではありませんけれども、ただ、子どもがゼロ歳から５歳までだから、ぜひ対応をお願いします。その場合に私たちが思うのは、開設はするのですけれども、既に保育園を開設していたとするなら、逆に交渉に有利な条件として、その施設をＪＲの施設の中に入れてもらうなり、そういうアイデアを持って交渉していくべきだと思うのだけれども、いかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"保育課としましては、ひろまち保育園があるということで、在園児の皆様への周知などを含めて、時期などについては十分配慮しながら進めていただくように所管と協議を進めたいと思います。","id":"exchange-016"},{"speaker":"伊藤副委員長","kind":"質問","question":"せっかくあるわけですから、それは今のところ５年というのはわかるのだけれども、そのときの再開発の状況の中で、例えば、広域で建設できるとするならば、それは品川区全体として考えていくべきであるし、またそういう場合には、５年先、さらに延長していくことも考えられるだろうし、お願いしたいのは、広町の再開発の中にこの保育園を有意義に活用していただくことをお願いしたいと思うのですが。","respondent":"金子子ども未来部長","answer":"そういう意味では、そういうことも踏まえた上で、再開発というのは区として判断していかなければならないだろうと考えていますので、今から確定的なことは申し上げにくいのですけれども、さまざまな状況を踏まえて対応していくことが必要かと考えております。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"確認","question":"もう一つは、私が以前に議会でお話しし、確認を忘れたのかもしれませんが、５年より延長する可能性や、そういうことに関してはどういう表現で夢工房とお話をなさっているのでしょうか。例えば、現在、そういう条件が入っているのか、それともそういうことがあったときは、何年前かにどうこうという、５年が区切りだとすると、どういった表現になっているのか、２つお願いします。","respondent":"今井待機児童対策担当課長","answer":"こちらの近隣の自転車駐輪場につきましては、既に交通安全担当課長とも情報共有しながら、近隣の状況を見ている中です。定期利用が大分利用されている中ですので、早めに内定の方が４月以降に向けての定期利用の更新ができるように、情報提供は早めにしていきたいと考えています。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"意見","question":"先ほどの自転車のほうは、定期利用はおそらく入っていないと思うので、一時利用を利用してくださいみたいな感じになると思うのですが、そのあたりは今お話あったように、ご利用される保護者の方にできるだけ早く自転車置き場はここだということをお伝えしないと、またそれはそれで交通安全のほうで自転車置き場がという話になってくるので、ぜひ連携をとっていただくようお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"もう一回だけ。園庭のことで伺いたかったのですけれども、屋外遊戯場で、近くの公園ということになってしまうのでしょうか。この間、ずっと園庭をと求めてきたのですけれども、ひろまち保育園ができる隣に駐車場だった場所があるので、そこを園庭に使えるだろうなと思いながら、私たちはずっと見ているのです。そういった考えはないでしょうか。","respondent":"今井待機児童対策担当課長","answer":"園庭につきましては、以前から申し上げているとおり、中庭が約２００m2、６０坪以上の面積を持っておりますので、こちらで泥遊び等をしていただくという形で考えております。","id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問","question":"すると、近くのＪＲの土地だということで、なかなか難しいというお話も伺っていたのですけれども、土地はたくさんあるわけですけれども、ＪＲとの交渉などは、この間、園庭という形ではされてはいないということですか。そこを伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"ＪＲ東日本、劇団四季とは運営事業者を交えて、また品川区独自でいろいろ打ち合わせをしてきたところですけれども、この園庭につきましては、特に議題としては上っておりません。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり園庭がある保育園にということで、父母の皆様からの要望が本当に多く届いているところですので、ぜひ今後も努力をしていただけたらと思うのですけれども、いかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"私どもとしましては、ＪＲの考え方がありますので、そちらを園庭という形で要望する考えはございません。","id":"exchange-022"},{"speaker":"大倉委員","kind":"質問・要望","question":"確認で、こちらの夢工房はいろいろ認可保育園等も実績があってやられている中で、以前３００人規模の大きな園はまだやったことがないというお話だったと思うのですが、その後、３００人を受け入れるのはすごく大変だと思うので、その辺の運営がしっかりできるように区としてどういう話をしていったのかというところと、３００人の子どもが災害で何かあったときに。","respondent":"今井待機児童対策担当課長","answer":"ですので、避難といいますと、いろいろな災害が考えられるわけですけれども、その施設にきちんと備蓄品を持ちまして、そこで滞留といいますか、まずはそこで待機できるように努めますとともに、万が一、今議員ご心配の延焼ですとかといった場合には、避難について。","id":"exchange-023"}]},{"id":"topic-03","title":"第９０号議案、品川区立学校設置条例の一部を改正する条例","agenda":"第９０号議案、品川区立学校設置条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今、説明をしていただいたのですけれども、品川区としては、何がどう変わっていくのか。何か国のほうで法改正ということだというご説明があったのですけれども、品川区では具体的にどんなふうに、何がどう変わるのか伺いたいと思います。","respondent":"野呂瀬学務課長","answer":"何がどう変わるということなのですけれども、基本的には校名が変更になるというのは大きな変更点なのですけれども、今までやってきた児童・生徒に対しての負担や影響は、基本的にはないものと考えております。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"校名の変更が一番大きな変更だということです。私も城南中学校に通っていたのですけれども、一貫校になっても校名は残るのだよということは、小中一貫校の説明のときに説明はされていたのですけれども、それが結局なくなってしまう。そういったところへの説明なり、そして声というのはどのように把握されているでしょうか。","respondent":"品川庶務課長","answer":"各小中一貫校につきましては、地域に関連のある方、外部評価委員等に関しましても、校長から説明をしています。１０月の上旬ぐらいに学校説明会を行ってあります。小中一貫校６校につきましては、学校説明会の中で、義務教育学校の説明もしているという状況です。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういった説明の中で、何か校名が変わってしまうということに関しての声が出ていたのかどうかというのをお答えいただきたいのと、これが法制化されて、義務教育学校になるということで、何で校名が変わっていかなければいけなくなるのかというのを教えていただきたいのです。","respondent":"品川庶務課長","answer":"この義務教育学校として名称を今回は「○○学園」という形で、小中一貫校に対しては６校設定をしていますので、旧来は「小中一貫校○○学園」と言っておりましたが、学校教育法の中では、正式には小学校と中学校が２校あったという状況ですが。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"確認","question":"施設分離型の学校も義務教育学校になっていくということですけれども、ここは当然そのままの名称が残る。これは変わらないということで確認します。","respondent":"品川庶務課長","answer":"施設分離型の義務教育学校ですが、今回につきましては、品川区の中で施設分離型の義務教育学校というのは設定をする予定はございません。あくまでも施設一体型の義務教育学校を６校やっていくです。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。この小中一貫校が義務教育学校という新たな学校種になっていくというところでの変化は、学校名だと。学校の名前というのは、区の判断で残していくというふうにはできないということなのですか。","respondent":"品川庶務課長","answer":"「○○学園」という名前も、かれこれ１０年間は区民の皆様にも非常になじんでもらっているということもありますので、前の学校名を残すというのは、２校を１校にするという中で、難しいことだと考えております。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"年を超えても、年齢差があっても、そういったところですごく親しみを持って話される共通したものだと思うので、それがなくなってしまうということについて、もう少し地域の声等を聞いていただきたいと思います。何が成果だったのか。それで、そのまま法制化されて義務教育学校になりましたと言われても、一貫校と一般の小・中学校を比較しての成果というものがどうあるのか伺いたいと思うのです。","respondent":"品川庶務課長、渋谷指導課長","answer":"そういう中で、校名がなくなるということについても、説明はしていることですので、これに対して、現在のところ大きい声はございませんので、十分説明は果たしていると考えております。小中一貫校の成果というお話でございましたが、基本的に品川区は全区で小中一貫教育を進めておりまして、品川区の子どもたちは品川区小中一貫教育要領という一貫教育の例に基づいた教育をしているということで。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですが、国がこれを法制化していくところでの議論を見ていても、一貫校を進めてきた地域が取り上げられて、声も聞かれて、成果があるということで進められてきたものなのではないかと思いますので、教育的な効果やデメリットも本当に十分検証されて進められたものなのかというのを伺いたいのです。法制化についてです。","respondent":"渋谷指導課長","answer":"法制化に向けて、あえてその部分で十分検討したかというと、それはもう既に小中一貫教育、施設一体型一貫校を１０年間やってきたという実績の中で、国の法制化が整ったので、そこに品川区も改めて正式に乗っかっていったという流れです。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、義務教育学校にしていく意味は何なのかと思うのです。だったら、今までのままでもいいではないですか。小中一貫校を進めてきた品川区ですから、それを法制化されたという上では、進めてきた先頭だとなってくるのだろうと思うのです。それで進んでいくものだと感じるのですけれども、その辺、品川区としてはいかがでしょうか。","respondent":"品川庶務課長","answer":"今、まさに委員がおっしゃったことで、法改正が今回なされたということで、今まで小中一貫教育を長年進めてきた品川区が、新たにこういう義務教育学校という形で学校を設定していくです。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"小中一貫校が進められていく中で、期待するものとして、学力の向上や学習意欲の向上ということがパンフレットなんかでもうたわれているのですけれども、前回の所管事務調査での資料を見せていただく中でも、１０年間やられていても、そこまで期待するものが表れていない。そういったところの検証がしっかりされてきたのかということを伺っているのです。お願いします。","respondent":"渋谷指導課長","answer":"そういった地域の環境要件ですとか、その土地の問題だとか、そういった状況の中から学校選択制をしている品川区として、さまざまな学校の形態のものを用意して、保護者、地域の皆様の選択に耐え得るような条件を整えることの１つと考えられるのではないかと考えています。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"意見","question":"施設一体型の小中一貫校が今回義務教育学校になっていくということなので、それをどんどん進めてきた品川区として、私は検証が十分にされていないと思うのです。そういう中で、法制化までして進めていくというメリットが私にはわからないのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"品川区が法制化するよりも前段階で進めてきた。何度も言いますけれども、この間いただいた成果では全然わからなかったので、そういったところで、問題点と成果というものをもっと明らかにしていただきたいのですけれども、いかがでしょうか。","respondent":"渋谷指導課長","answer":"これは、義務教育学校の法制化にかかわらず、教育の営みというのは、常にどの小学校段階でも、中学校段階でも、ましてや小中一貫教育でも、日々問題点、改善を図っていくという営みを我々はしているところでありますし、これからもきちんとそういったものについては。","id":"exchange-034"},{"speaker":"鈴木（博）委員","kind":"質問","question":"教育委員会と品川区が、品川区の教育に意欲的にいろいろ想像と多様性と試みをして、子どものために新しくチャレンジするという姿勢は、非常によいことであり、それに関しては強く支持したいと思うのです。この法案の中ではどこが、文部科学省が義務教育学校をつくるという積極的な意味づけを読み取ったらよろしいのでしょうか。","respondent":"渋谷指導課長","answer":"積極的な意味づけというよりも、義務教育学校の法制化については、自治体、現場レベルでの実践が先行して、既に１０年たってきたということで、各地方自治体が主体的な意思を持ってやりたいことについて、法案としてお墨つきを与えたという解釈だと考えています。","id":"exchange-035"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、現場でやっているから、国としてそれに認可を与えるというスタンスでこの法律が出たのでしょうか。そうすると、あまり積極的な意味はないと思うのだけれども。","respondent":"渋谷指導課長","answer":"積極的な意味合いというよりも、やはり実践をしている現場にとって、よりやりやすくなるようにという意味合いで法制化したと考えています。","id":"exchange-036"},{"speaker":"鈴木（博）委員","kind":"意見","question":"非常によくわかりました。そうすると、２枚目の「４－３－２」や「５－４」などの柔軟な学年段階の区切りを設定することも可能である。ただし、これは課程の変更を意味するものではなくて、カリキュラム編集上の工夫や指導上の重点を設けるための便宜的な区切りを設定することを想定しなさいと書いてあるのだけれども、これはどういうふうに読み取ったらいいのか。","respondent":"渋谷指導課長","answer":"ただ、勉強の中身を考えるときに、例えば品川区でやっているように、１年生から４年生までは基本的に学級担任制でやりながら、５年生から教科担任制を取り入れたりということは、各自治体の工夫の中で自由にやっていいですという意味合いのものです。","id":"exchange-037"},{"speaker":"鈴木（博）委員","kind":"意見","question":"わかりました。それと、日野学園なんかはもう１０年たっているのですけれども、うちの患者さんに聞いても、「僕は日野学園だ」と言う人がいても、「私は第二日野小学校だ」と言う人は１人もいませんから、その名前がかなり浸透していると現場では理解している人間もいるということを一言だけつけ加えておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"浅野委員","kind":"質問","question":"今回の義務教育学校については、品川区の取組みが、間違いなく大きく取り入れられていると感じるところであります。場所が離れているとか、そういうこともありますし、交流するにしても、離れているとやりづらいというのもあるかと思うのですけれども、そこら辺をどのようにお考えになられているか教えてください。","respondent":"渋谷指導課長","answer":"この辺は大変難しい問題になるのですけれども、例えば一番大きなネックになるのは、義務教育学校になったときに、校長先生を１人にするというところが一番大きなポイントになるのだろうと。","id":"exchange-039"},{"speaker":"浅野委員","kind":"質問","question":"そこら辺を継続しながら、こちらに入ったほうがよかったのではないかとか、こちらのほうがどうなのかという声が上がらない形で、ある意味では平均的というのでしょうか、品川区としての教育の考え方をしっかりと平等に伝わるような形をとっていっていただければと思います。そこら辺、何か取組みなどをお持ちであれば教えてください。","respondent":"渋谷指導課長","answer":"東京都に対しては、今後になりますが、義務教育学校設置の暁には、小・中両方の免許を持った人間が取れるような、例えば義務教育学校に対する公募制度の設立等々をぜひ強く求めていきたいと考えているところです。","id":"exchange-040"},{"speaker":"浅野委員","kind":"質問","question":"品川区の学校の設置条例というところを見ているのですけれども、小学校と中学校と書かれているのですが、この中で特に左側の小学校のほうで、空欄みたいな形になっているのですけれども、この空欄はそのまま空欄で条例という形になるのですか。ここら辺はただ単に見ばえをよくするだけでもいいのかとも思うのですけれども、実際に条例となる場合にはどのような形を考えられているか教えてください。","respondent":"野呂瀬学務課長","answer":"今日お示しした新旧対照表では、対比させる意味で空欄にしておりますけれども、実際に条例になったときには詰めるように考えております。","id":"exchange-041"},{"speaker":"大倉委員","kind":"質問・要望","question":"今後、こうやって法律で書かれたということは、進めていかなければいけないというところで、どの程度を目標にして増やしていこうというのを、都のほうにも要望していくというところなのですが、どういう考え方で要望していくのかというところを教えていただきたいと思います。","respondent":"渋谷指導課長","answer":"最後３点目の縛りについてですが、これは先ほどの説明とも重なりますが、文部科学省が今回の法整備をするにあたって、既に全国の各自治体で取り組んでいる小中一貫教育を制限したり、やりにくくしたりするものではないのだという方針で法制化されていますので、今現在。","id":"exchange-042"},{"speaker":"大倉委員","kind":"質問","question":"わかりました。今後のこうした学校教育法の中で義務教育学校というのが認められるようになって、今後、品川区として、当分のところ小中一貫校は６校でというお話が前からある中で、こういうものが設置されて、今後は同じ考えなのかどうか。今後の義務教育学校についての進め方、学校のあり方、進め方に変わりがないかどうか教えていただければ。","respondent":"品川庶務課長","answer":"義務教育学校６校につきましては、当初小中一貫校６校体制というお話がありましたが、今回、法改正ということもありまして、６校でとめるという考えではなく、やはり今後、少し義務教育学校についてはどのようにやっていくかということで、広げていく考えは。","id":"exchange-043"},{"speaker":"大倉委員","kind":"質問","question":"今後、分離型なのか、一体型なのかわかりませんが、義務教育学校というものができたことで、品川区の学校のあり方としても、もう少し動きが出てくるような考え方が今出てきたという認識でいいのでしょうか。","respondent":"品川庶務課長","answer":"直近で何かどうこうするということではありませんが、やはり将来に向けては６校体制でいくということではなく、少し考え方が変わってくるものではないかです。","id":"exchange-044"},{"speaker":"大倉委員","kind":"質問","question":"いろいろ目指して、学校自体が地域と一緒になってということで進めている中なので、そういった中で考え方が時代の中で少しずつ変わっていく中において、今後そういった検討がされるときは、しっかりと地域の方や、子どもたちが主体ですから、子どもたちのためになるような学校づくりというか、設置についても取り組んでいっていただければと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"意見","question":"そういうところだと、現状において、義務教育学校とそうでない小学校、中学校が存在するという２種類の種類というか、どう言うのかわかりませんが、できてしまうというところにおいて、小・中義務教育段階から、複数の学校制度が明らかになっていく。これからどうなるのか微妙だったのですけれども、違う種類を置くことの意味をどこに置いているのか。今後もわかる範囲で明解に言っていただけますか。","respondent":"渋谷指導課長","answer":"学校選択制をひいている品川区として、品川区の保護者、またお子様にさまざまな選択肢を用意するという１つの方向性としては、区民のニーズに合致したものではないかと考えているところであります。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"選択肢と言えるのですか。私立と公立を選ぶというのはありますけれども、選択肢というと、違った学校、中身が違う、どういう捉え方をこの２種類に置いているのかというところ。選択してもらう選択肢が多いほうがいいと考えているわけですか。もう一回、そこをお伺いしたいと思います。","respondent":"野呂瀬学務課長","answer":"当初、私が説明したときに戻りますけれども、今現在小学校が３１校あって、中学校が９校ある。小中一貫校も、日野学園が一番最初にできて１０年たちますけれども、施設一体型の小中一貫校は６校ありました。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"確認","question":"何かわかりにくい議論になってしまったと思うのですけれども、法律が変わっただけであるとおっしゃるのだったら、何で今までと違って、耳慣れない義務教育学校というものにするのかという話になってしまうのではないでしょうか。これは置いておいて、これは自治体で選べるのですよね。法律ができたから変えなくてはいけないというものではないですね。そこを確認させてください。","respondent":"品川庶務課長","answer":"それは委員おっしゃるとおりで、法律が変わったということに対して、当然小中一貫教育を進めている品川区として、先行して義務教育学校をやっていこうというスタンスです。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこのところに意義があるので、幾つか質問を続けします。今日の資料で出ていましたけれども、学校教育制度の多様化、弾力化の推進とは一体どういう意味なのかお伺いしたいのが１つです。これは大問題という捉え方をしていただきたいのが１点です。小中一貫校をつくっていく段階で、たくさんの声が上がったのです。特に校名について、どのような説明をしていたのか、改めてお伺いしたいと思います。","respondent":"品川庶務課長","answer":"小学校、中学校の旧学校名についてはなくなるというお話も説明しております。それから、ＰＴＡのほうにも小学校ＰＴＡ連合会、中学校ＰＴＡ連合会にも集まっていただきまして、この点についても説明しています。周知についても、十分説明をしているです。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"検証と関係ないというか、新しい試みをして、検証すると言いながら、委員会の設置をしているわけですよね。検証をしていますよね。検証結果を一緒に示すから、今やっている区教育委員会のやり方を理解してもらうのだと思います。検証は別です。今のやりとりはおかしいです。全然答えになっていない。口頭なのか、文書があるのだったら、文書を示していただきたいと思いますが、いかがでしょうか。","respondent":"品川庶務課長","answer":"再度説明申し上げますが、法改正による義務教育学校の設置です。先ほども指導課長から答弁がありましたように、検証についてはさまざまな課題がまだ残っているということで、答弁があったと思います。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問","question":"何度も聞くのは、きちんと答えてくれないからです。９月の下旬から１０月の上旬まで周知、相手は先ほど述べたとおりです。私は何人ぐらいの人にお伝えしたのですか、文書なのですか、口頭なのですかと聞いていますので、きちんと答えてください。","respondent":"品川庶務課長","answer":"人数につきましては、学校説明会に来られている方の人数になりますので、６校で大体２日間ぐらい学校説明会が行われています。確かに１人１人、人数を数えているという状況ではございませんので、ある程度の説明で人数の規模はご理解していただけるかと思います。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"同じ質問ばかり繰り返すつもりはないのですが、もう一回、学校説明会というのは、対象はどういう方なのでしょうか。１校目の日野学園、日野中学校のＰＴＡから日野中学校を移転しないでくださいと教育委員会に３,５００筆の署名が提出され、議会にも小中一貫教育計画の中止を求める請願が出されていました。２校目、伊藤学園も原小学校のＰＴＡが父母のアンケートを行って要望書を提出しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"思いも言わないと、思いのほうが大事ですので。なので、当時何と言っていたのかという質問を先ほどしましたけれども、このやり方、「十分しています」と、本当に区民の方の理解を得られていると思うのですか。私はとてもではないけれども、理解できないのです。私だけではないと思いますが、いかがでしょうか。","respondent":"品川庶務課長","answer":"いろいろお話をいただきまして、再度繰り返しのところになって大変申しわけないのですが、法改正による義務教育学校設置ということで、周知につきましても先ほど答弁したとおり、９月下旬から１０月上旬まで説明会等を行っております。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺の義務教育学校の施設設備の基準、先ほど校長先生が１人になるという話は聞いたのですが、教職員の配置基準など、明確に出ているのでしょうか。今の基準をしっかり守るというのと、私としては、大規模化の中で手厚くしていただきたいと思うのですが、その辺の基準がどうなっているのかと、区が進めている上でどういう中身でいくのかというところを教えてください。","respondent":"品川庶務課長","answer":"先ほど委員がおっしゃったとおり、説明の中でもありましたとおり、校長先生１人、副校長先生３人という体制。これについては具体的に出ておりますが、それ以外についてはまだまだ基準というのは、現在のところ特段出されている状況ではございません。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"提案","question":"今までは、従来のところで特例的にやっていたけれども、いよいよ一体化のところで義務教育学校というのであれば、やってきた問題点をしっかり出して、改善していく中身でどんどん提案していくべきだと思うのです。６校中４校が１,０００名を超えていたり、若干少ないくらい、九百何十人といったところでは、大規模な学校である。この大規模化に対して、特に配慮を考えているところがあるのでしょうか。","respondent":"品川庶務課長","answer":"これは、当然用地の問題になってまいりますので、なかなか広い土地にすぐ学校をつくるという状況は品川区の中では非常に難しいところではないかと思います。そういう中でも、学校の設置基準にのっとった形でしっかりと学校建設はしておりますので、よろしくお願いいたします。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問","question":"しっかりやっていますということなのですけれども、実際的に学校によってすごく格差があります。１つには校庭のところなのですけれども、子どもが体を動かして、体力的にも伸び伸びと育ってほしいというところで、校庭の格差と言ってしまっていいくらい広さにすごく違いがあると思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問","question":"何ですか。条例審査だからこそ、中身を言っているのではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはりよりよい規模を、教育委員会としてはぜひ考えていっていただきたいという思いがあるので、今日ここで述べさせていただきましたけれども、教職員の配置基準、施設と設備、学校の規模、学級数をどう捉えているのですか。標準というか、普通の学校の規模と義務教育学校の学級の規模をどう考えているのですか。こういう中身をわからないで賛成するのですか。おかしいではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"意見","question":"最後になります。学級数の規模は、国の段階で多分これから出てくると思うのです。今議論されているところであると思います。そういった意味で、ぜひ地方から声をどんどん上げていって、子どもたちのための基準が守られるような状況に力を尽くしていただかなければ困ると思いますので、よろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"高橋（し）委員","kind":"質問","question":"幾つかお尋ねするのですが、まずこれは質問というよりも、副校長先生が３人になったということで、これはおそらく品川区で現状１０年やってきて、これだけの先生がいらっしゃらないとなかなか厳しいというのを文部科学省に主張していただいて、通ったのではないかと思っています。それから、特別支援学級は、学級数や先生の配置など、そのまま現状と同じようにいくのでしょうか。その３点。","respondent":"渋谷指導課長","answer":"ただ、「４－３－２」については、保護者アンケート等をやっても、なかなかご理解が進んでいない現状がありますので、この部分については小中一貫教育推進委員会の中でも話題になっておりまして、今後、学習指導要領の改訂にあわせて品川区の小中一貫教育要領を見直す際には。","id":"exchange-060"},{"speaker":"高橋（し）委員","kind":"提案","question":"それで、お話があったように、品川区の教育課程を新たに決めていくというところなのですが、そこまでにあと何年かあるのですが、その中で平成３１年からの体制のことを考えていかれると思うのです。その辺に向けて、先ほどいろいろ議論がありましたけれども、大きな枠の中でといいますか、考え方というか、平成３１年からについての現状をどういうお考えで進めようとしているのかというところをお尋ねしたい。","respondent":"渋谷指導課長","answer":"９年間、しっかり子どもたちが力をつけ、また人間性をしっかりと育成できるような仕組みを１つ考えていくために、義務教育学校の制度、あるいはまたこの後導入していく品川版のコミュニティ・スクール等々の仕組みを十二分に活用しながら。","id":"exchange-061"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、平成３１年からの体制づくりにとって重要な検討、この推進委員会もそうだと思いますので、議会も含めて議論をする機会をつくっていただければと思います。事実上、分離型も存在しますけれども、そこのところで分離型小中一貫校の位置づけというのを、先ほどの平成３１年からのところにつながるのかもしれませんけれども、どのようにお考えでしょうか。","respondent":"渋谷指導課長","answer":"１つのキーワードは、やはり地域とともにある学校ということで、中学校区という大きなまとまりで義務教育というものの９年間を考えていくような仕組みができるといいのかなと考えて、さまざま今検討しています。","id":"exchange-062"},{"speaker":"高橋（し）委員","kind":"質問","question":"まとめます。どうもありがとうあります。最後、これは質問というよりも、一般質問でもお話ししたのですが、１０月下旬あたりにいろいろ地域にも説明され、在校生や新入生にも説明されたわけですね。本会議の質問ですので、繰り返しになってはいけませんので、そこのところを感想というか、お話しして、そこまで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"伊藤副委員長","kind":"確認","question":"義務教育学校の確認ですけれども、これは品川区をはじめとした小中一貫教育の全国での実践が、いろいろなところから文部科学省に届いて評価をいただいた。それから、改めて義務教育学校になった後、では品川区がどういう教育を展開して、子どもたちのためにすばらしい素質のあるものを展開していくのかということのほうがより重要だと思うのだけれども、その２つをまずお答えください。","respondent":"渋谷指導課長","answer":"今、委員ご指摘のとおり、義務教育学校の創設につきましては、地域の実情や児童・生徒の実態、さまざまな要素を総合的に勘案して設置者が主体的に判断できるように、従来の小学校・中学校に加えて、義務教育を行う学校の設置の制度上の選択肢を増やしてくださったということで。","id":"exchange-064"},{"speaker":"伊藤副委員長","kind":"確認","question":"でも、法的な位置づけがなかなかないということがあって、文部科学省としてはおそらくさまざまな議論を経た上で、法律ですから、そういうことを当然文部科学省としては調査してきたと思うので、ほかの意見にあったように、一方的に一貫がだめだということではなくて、さらに前に進めていく意味の教育の価値は相当あったと思うのだけれども、その解釈を確認でもう一度だけ教えてください。","respondent":"渋谷指導課長","answer":"私どもも、ぜひまた品川区全体の教育、９年間の義務教育というものをしっかりと見据えて取り組んでいきたいと考えています。","id":"exchange-065"},{"speaker":"伊藤副委員長","kind":"質問","question":"だけど、さまざまなことをお伺いする中で、品川区の姿勢や品川区の教育への取組み、それから実際の教育現場をたくさん見てきた中で、これは非常に功績があるということで、方向性を変えてきました。それに伴って、ほかの会派もさまざまな議論を経た上なのだけれども、議会としても、それはある程度、してきたことは事実です。教育次長でいいですかね。答弁いただければと思います。","respondent":"本城教育次長","answer":"そういう意味で、さらに先ほども一部答弁させていただきましたが、これを１つの契機として、日々、教育の改善、向上に努めていきたいと考えているところです。","id":"exchange-066"},{"speaker":"伊藤副委員長","kind":"質問","question":"まとめますけれども、要は議会はさまざまな議論をする場であるから、賛成、反対で当然なのだけれども、私たちとしては、特に小中一貫教育については、今まで何十回も委員会等で議論してきました。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"意見を添えて反対いたします。小中一貫校ですが、１０年を経過しましたが、はっきりしているのは統廃合が進んだこと、この間、専門家や教職員の方々、保護者、地域からも教育的効果に疑問が出されています。検証を求めていますが、いまだ示されないままでありますので、一方的に義務教育学校への移行は認められないということで反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"}]},{"id":"topic-04","title":"ただいま、第９０号議案、品川区立学校設置条例の一部を改正する条例が可決されましたので、次に、(4)第９１号議案","agenda":"ただいま、第９０号議案、品川区立学校設置条例の一部を改正する条例が可決されましたので、次に、(4)第９１号議案","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"第９３号議案の新旧対照表のところで、２／５ページのところの第６条なのですけれども、保育料の減免の項目です。どういうふうにこれを読んだらいいのか教えてほしいのと、「委員会が特に必要と認めたときは」というのは、どういう例があるのか、具体的に教えていただきたいと思います。","respondent":"竹田保育課長","answer":"委員会が特に必要と認めたときというご質問ですが、今後、発生するものとしましては、みなし寡婦の減免等を考えているところです。","id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問","question":"今のところなのですが、みなし寡婦以外はないのですか。今まで減免制度にあたった例がどのような例があるのか教えてください。","respondent":"竹田保育課長","answer":"ほかにも保育料を減免する例としましては、災害等で損失を受けたとき、あるいは多額の医療費を支払ったとき、大きく世帯の収入が変動したとき等があります。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問","question":"件数的にどのくらいあるのですか。例えば、年間でどのような。めったにないことですか。","respondent":"竹田保育課長","answer":"今、正確な数字は持ち合わせていないのですが、項目によって多い、少ないがあります。","id":"exchange-071"},{"speaker":"飯沼委員","kind":"意見","question":"すみません。第８９号のところは、多子減免制度や入園料の削除、この辺は評価をしますけれども、先ほどと同様で義務教育学校のところの反対を理由として反対します。第９３号のほうも、多子減免制度、この辺は評価をしますけれども、同様の理由で義務教育学校の設置ということで反対いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"}]},{"id":"topic-05","title":"第９７号議案、指定管理者の指定","agenda":"第９７号議案、指定管理者の指定","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺の職員の確保のことについて、問題はないかどうか、継続、定着ができているのか、離職率など、わかったら教えていただきたいと思います。正規と非正規の職員のところでわかったら教えてください。","respondent":"廣田子ども家庭支援課長","answer":"ひまわり荘、母子生活支援施設につきましては、ここは第一優先に福栄会で人員配置をしておりまして、過去５年間で福栄会の各施設の人事異動と定年による退職、非常勤につきましては契約期間が切れたという場合を除きまして、人員の変更等はございませんでした。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"意見","question":"ひまわり荘のところは、定着して安定してやってくださっているということで、短期の子育て支援のところの課題というのは、どういうふうに解決されていくのか。","respondent":"伊崎子ども育成課長","answer":"今、説明がございましたが、子育て支援センターは東京都の子ども家庭支援センターとして位置づけられておりまして、子どもと家庭に対する専門的な相談、その中には虐待への対応も含まれております。短期の子育て支援事業などを実施しております。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問・要望","question":"子育て支援のところで、結構虐待の予防といった、対応的になかなか難しい、あと連携が必要だというところにおいては、ぜひ根づいてやっていただきたい、蓄積していただきたいところなのですが、この職員は正規でしたか、非正規でしたか、どちらでしたか。","respondent":"伊崎子ども育成課長","answer":"子育て支援センターの虐待の対応の職員が常勤、正規です。","id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大事な部署であるし、これからもますます求められていくし、経験を持って、どんどん周りにも発信しながら連携強化をしていただきたいので、ぜひ続いてお仕事をしていただけるようによろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"浅野委員","kind":"質問","question":"指定管理者の指定ということで伺いました。そういうところはあるのかということと、そして、複数あれば比較をしながらということもできると思うのですけれども、そういう意味では、そういうところがほとんど見つからない状況なので、今回はこちらに指定をされたのかということについて１点お伺いしたいです。あったときには、どのような事故なのか。","respondent":"廣田子ども家庭支援課長","answer":"職員の対応に対して丁寧で満足しているというところが母子ともに１００％を確保されていまして、安心して生活できるように支援がされているというところで、９割近くの回答が得られているところから、もちろんほかにもいい事業者はあろうかとも思いますけれども。","id":"exchange-077"},{"speaker":"浅野委員","kind":"意見","question":"確かに長きにわたってやられているということもありますので、取組みも大きな意義があったのかと思うので、よろしくお願いします。やはり事故については、万全の体制で捉えていると思いますが、引き続き、そこに住まわれている方や対応される方が安全であるような仕組みで、これからも継続して頑張ってもらいたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、長い間と伺ったのですが、何年からずっとやられているのかということと、前回の指定管理の予算といいますか、今回は幾らになっているのかがわかればお伺いします。","respondent":"廣田子ども家庭支援課長","answer":"いつからというご質問ですが、指定管理の制度が入りました指定管理者としては平成１８年から福栄会が指定管理者となっておりまして、１期、２期で、今回は２期が終了しての選定になっております。","id":"exchange-079"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"平成１４年からやっているので、今お話の中では評価は高いということなのですが、やはり長く同じところがやれば、改善に対する面も甘くなっていくと思いますので、そのあたりは区がきちんと見ていっていただかないと、先ほども虐待云々もありましたけれども、ちょっとしたことが命にかかわることが多いので、ぜひそこは続けてとっているから大丈夫だというのではなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"伊藤副委員長","kind":"意見","question":"今ご説明があったように、家庭あんしんセンターは事業の継続性は十分わかるのです。だけど、ずっと福栄会なのです。だから、それはなかなか切れないところもあるのだけれども、今聞いていると平成１４年でしたか。その年度からやっているとすれば、入居者も変わっているでしょうし、さまざまな社会情勢も変わっていく中で、なぜ福栄会なのかという疑問がつくのだけれども、改めて答弁をお願いいたします。","respondent":"廣田子ども家庭支援課長","answer":"場合によっては早く出られる場合もあれば、３年を超すということはあるのですけれども、成果として平成１８年からずっと見ていくと、ここ二、三年で目標を達成できるように積極的な支援が行われているというところで、継続していくことが効果があるのではないかというところです。","id":"exchange-081"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"例えばほかの委員会で出た議案の中で、あるところでは、指定管理者の中で東京都の監査が入った等あるではないですか。本来、そういうものは品川区の委員会の中で引き継ぐべきではないですか。だから、私が思うのは、候補者選定委員会の中で、そういう実務的な面まで見ているのですかということが、いつも疑問に思っていたのだけれども、いかがでしょう。","respondent":"金子子ども未来部長","answer":"もう一つ、所管が２つに分かれているのですけれども、子育て支援センターの虐待、あるいは見守りについての対応というのも、変えていくのがなかなか難しいところです。","id":"exchange-082"},{"speaker":"伊藤副委員長","kind":"確認","question":"私としては、それは品川区が指定管理をしたわけだから、品川区のさまざまな部署で実務を確認して、評価してとおっしゃるのだけれども、東京都の監査を受けて初めてわかったということからすると、やはり品川区としてもっと頑張ってほしい。もっと言うと、はっきり調査してほしいという思いもあるのです。その体制を強化していただくようにお願いしたいのだけれども、いかがでしょうか。","respondent":"金子子ども未来部長","answer":"そういう意味では、私どもとしましても、福栄会はこれ以外にもいろいろ仕事の関係がありますので、さまざまなところでいろいろなチャンネルを使って情報を得ながら、そういう意味では万が一、外側から指摘をされるということはないように、内側からの。","id":"exchange-083"}]},{"id":"topic-06","title":"第８４号議案、平成２７年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第８４号議案、平成２７年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"それで、この中身的には、認証保育所と区内私立保育園、小規模保育事業となっていますけれども、これは事業をやっていれば、ある程度平等に１人幾らぐらいといって分けられるものなのか、これを具体的にやらないと配分されないとか、何か制約があるかどうか教えてほしいです。保育力強化事業助成というのが、さまざまな取組みに充てられるということなので、さまざまの中身を教えていただきたいと思います。","respondent":"竹田保育課長","answer":"さまざまな取組みということで具体例ですが、例えば一時預かり事業を実施している、外国人児童の受け入れを行っている、アレルギー児童の対応を行っている、地域子育て支援の事業を行っているなどの項目について加算するものです。","id":"exchange-084"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これは、保育課長に前も何回か質問してお答えいただいたと思うのですけれども、今保育士というのは非常に足りないのです。それで、各地方自治体でも奪い合いになっている。お金を上げれば、ほかのところも上げるし、今の保育士はドライですから、お金が高いほうにどんどん流れていってしまうから定着しないと思うのです。その辺はどういうお考えでいますか。","respondent":"竹田保育課長","answer":"ですから、賃金改善を行うとともに、高い質の保育を実施することによって、子どもたちも育てる、保育士も育てるという環境のもとで実施することによって、品川区の保育を目指していただける保育士がいると思います。","id":"exchange-085"},{"speaker":"鈴木（博）委員","kind":"確認","question":"すばらしいお話を聞いたのだけれども、品川区の保育がそんなにすばらしいとは、確認して、それほど詳しくは知らなかったのです。品川区の保育が周りに冠たるいいところというか、売りどころ、セールスポイントはどんな点がすばらしいのですか。","respondent":"竹田保育課長","answer":"少し手前みそになりますけれども、具体的に大学の先生に監修いただきまして、『のびのび育つしながわっこ』という冊子を継続的に発行しております。","id":"exchange-086"},{"speaker":"高橋（し）委員","kind":"質問","question":"キャリアアップということは、保育士の賃金をアップすることに使うわけですけれども、それが各私立保育園や認証保育所のところで、個人個人がこれだけお給料が上がったというのは、何らかの形で区はチェックができるのでしょうか。","respondent":"竹田保育課長","answer":"このスキームにつきましては、各保育所ごとに賃金体系が違いますので、算出根拠に基づきまして、一括して保育所にお渡ししまして、その金額がどんなふうに配分されたのかということを実績報告を上げていただくことによって確認しております。","id":"exchange-087"},{"speaker":"高橋（し）委員","kind":"質問","question":"その実績報告というのは、そのお金は、今まで人件費でこれだけだったけれども、それをこれだけ増やしたという形で報告されるのですか。","respondent":"竹田保育課長","answer":"今回、補助金としてお渡しした金額の詳細についての明細をいただくものです。","id":"exchange-088"},{"speaker":"高橋（し）委員","kind":"質問","question":"それが人件費に回らないで、全体の別のところにいくということが、今のお話だとあり得ないということで認識してよろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"伊藤副委員長","kind":"質問","question":"今の話を聞いていて、非常にすばらしいことだと思うのですけれども、継続はできないのですか。つまりキャリアアップや上乗せのところについて、東京都の補助金は単年度だけなのですか。わかりますか。","respondent":"竹田保育課長","answer":"今回、国で公定価格というものが示されまして、保育士の賃金が大きく改善されました。認証保育所などは、東京都の独自事業ですので、公定価格を受けない部分もあります。公定価格に限定する形で、東京都も賃金改善という形で、今回補助金が創設されたと考えております。","id":"exchange-090"},{"speaker":"伊藤副委員長","kind":"質問","question":"確かに東京都のことですから、課長ではなかなか答えにくいと思うのだけれども、現場としては、大変な中で当然喜んでいらっしゃるわけでしょう。全ての市区町村にかかる話であるだろうから、それはさまざまな部課長会議等の中で、これはできれば財調算定に入れていただいて、自動的にお金が入ってくる仕組みを構築していってほしいと思うのだけれども、品川区のお考えを聞かせてください。","respondent":"竹田保育課長","answer":"この実態を東京都にも機会を捉えてお伝えしながら、保育士不足というのは続いており、今後も継続して続くと思いますので、この補助金を維持していけるように東京都にも訴えていきたいと考えております。","id":"exchange-091"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"要は補助金だと、単年度で終わってしまうと嫌なのです。さまざまな保育現場の環境を改善していくためには、ある程度安定したものをやっていっていただきたいということでお話をさせていただいています。もちろん課長が決めるとは思っていないけれども、さまざまな部署、課長会、部長会等々で指摘をよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"}]},{"id":"topic-07","title":"平成２７年請願第２８号、品川区私立幼稚園児保護者負担教育費軽減の為の請願","agenda":"平成２７年請願第２８号、品川区私立幼稚園児保護者負担教育費軽減の為の請願","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"基本的なところで申しわけないのですけれども、入園料補助金と園児保護者補助金、そして幼稚園等就園奨励費補助金で、区が出しているものと国や都が出しているものもあると思うのですけれども、この３つの補助金の出処を教えていただきたいのと、どれだけ、どういった率で出されているのか、わかれば教えていただきたいと思います。","respondent":"竹田保育課長","answer":"こちらはそれぞれ所得に応じて、あるいは第何子かということによりまして、補助金額が決まっているものです。入園料補助金につきましては、お一人につき１０万円を上限に補助しているものです。","id":"exchange-093"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"入園料補助金がどこからで、もう一回分けて説明していただきたいのです。入園料補助金と保護者補助金、そして就園奨励費補助金を、わかりづらかったので、もう一回、ごめんなさい。","respondent":"竹田保育課長","answer":"園児保護者補助金というのが、東京都の補助金に、さらに区が上乗せしている補助金です。それから、入園料補助金は、区が単独で行っている補助金です。","id":"exchange-094"},{"speaker":"石田（ち）委員","kind":"質問","question":"幼稚園等就園奨励費補助金は、国だけで出されているということでいいですね。そうすると、請願の文章の中に、平成１６年度には就園奨励費補助金について増額してもらえたというところは、国が増額したということになるということでいいのでしょうか。","respondent":"竹田保育課長","answer":"すみません。どこの部分ですか。","id":"exchange-095"},{"speaker":"石田（ち）委員","kind":"質問","question":"ごめんなさい。請願文の２段落目というのでしょうか。一番上が大震災からということで、次の段落の子どもたちがお世話になっておりますというものの次、３番目だ。幸いにしてというところから始まる文章の中ほどに、平成１６年度には就園奨励費補助金について、もろもろあって、増額していただきとあるのですけれども、これは国が増額した。入園料補助金のところは区が増額したということでいいのでしょうか。","respondent":"竹田保育課長","answer":"就園奨励費補助金につきましては、原則、国の補助金ですが、区も一定程度補助を出しているものです。それから、先ほどから申し上げているとおり、園児保護者補助金については、こちらにつきましても、東京都の基準にさらに区が一定程度上乗せしている補助金です。","id":"exchange-096"},{"speaker":"石田（ち）委員","kind":"質問","question":"幼稚園等就園奨励費補助金の件は、品川区と国の補助金から交付されていますと思っていいのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ご説明を聞いて、この本文からすると、この間、所得制限はあるものの、対象の拡大が行われてきているというところは、一定受けとめるのですけれども、昨今のいろいろな経済的事情もあって、さらなる助成という意味では、所得制限の撤廃をということが第１点目に書かれているのです。先ほど少しおっしゃったのですが、もう一度、なぜ所得制限がここにかかっているのか教えていただきたいと思います。","respondent":"竹田保育課長","answer":"平成２６年度に拡大しまして、園児保護者の約７０％を目標に拡大したところですので、今後も適切な支援をしていきたいと考えております。","id":"exchange-098"},{"speaker":"飯沼委員","kind":"質問","question":"今の言葉をいただいた部分では、これからも拡大していくという姿勢で受けとめて、今７０％を目標と言っていますけれども、現在、所得制限で助成が受けられていない方はどのくらいいらっしゃるのか。その方に助成をするとなると、どのくらい金額がかかるのでしょうか。わかったら教えてください。","respondent":"竹田保育課長","answer":"園児保護者補助金をご説明しますと、平成２６年度は区内の園児総数が３,４４０人です。平成２６年度に補助金を受けられた方が２,２７４人ですから、その差が１,１６６人の方が対象ではなかったです。","id":"exchange-099"},{"speaker":"飯沼委員","kind":"質問","question":"もう一点、ここに所得制限導入以来、公私立幼稚園における教育費負担の格差が拡大しておりますと書かれているのですけれども、公私立の教育費の負担の格差というのは、現状においてどう捉えていらっしゃるのか伺います。","respondent":"竹田保育課長","answer":"今回、第２回定例会でご議決いただきまして、所得に応じた７段階のご負担をいただくという内容に変更いたしましたので、来年４月以降については、公立幼稚園に通われる方につきましても一定のご負担をいただく形になりましたので。","id":"exchange-100"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私たちは公立の幼稚園の保育料の値上げのときに、公私立の格差があって、高い負担があるほうに合わせるのではなくて、低いほうに合わせてほしいという要望を出させていただいたのです。特に年少扶養控除がなくなって、増税になった後、児童手当のお金も減っていますし、児童手当も所得制限がついているのです。先ほど、予算を伺ったのは、現状、これに負担がかかっているのは幾らなのですか。どうでしょうか。","respondent":"竹田保育課長","answer":"予算の今までの経緯ですが、先ほどの就園奨励費補助金と園児保護者補助金を足した金額の推移ですが、平成２４年度は５億４,９３５万４,５００円、平成２５年度が５億２,２６０万９,９００円、平成２６年度におきましては、６億４,４４９万４,６００円ということで。","id":"exchange-101"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なかなか区のところも少しずつ増えている部分もあるので、努力をしてくださっているという面では評価がされると思いますけれども、やはり子育て支援のところ、少子化の問題もいろいろ言われていますし、切実な請願なので、どうしたらこの支援ができるのかというあたりを考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"浅野委員","kind":"意見","question":"賛成します。採択。保護者の方、大変な中で子どもを育て、また保育料もかかっているということもありますが、補助金を出すことによって、教育関係もいろいろな事業もできるようになるし、またいろいろな取組みもできるようになると思いますので、またよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-103"},{"speaker":"大倉委員","kind":"質問・要望","question":"採択でお願いします。本旨の格差是正と保護者の経済的負担の軽減というのは、ぜひ図っていただきたいのと、教育内容の充実や、私立保育園の振興というのも、支援をしていくことが大切だと考えますので、採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"高橋（し）委員","kind":"意見","question":"私立の幼稚園には、就学前の保育の多くの部分を担っていただいていて、また保護者の方々は、この中にあるように、今さまざまな事情でご苦労されていると思います。多様な教育ということで、私立幼稚園の位置づけも重要なものだと思いますので、採択といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-105"}]},{"id":"topic-08","title":"平成２７年請願第３２号、認可保育園・区立幼稚園保育料値上げとすまいるスクール有料化の中止を求める請願","agenda":"平成２７年請願第３２号、認可保育園・区立幼稚園保育料値上げとすまいるスクール有料化の中止を求める請願","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"認可保育園の保育料のことですけれども、前までの説明で住民税に算定方式を変えていくことと、多子減額で区の収入が１１％減。それを１０％の保育料の改定でマイナス１％になるから、値上げではないということをこの間もずっと答弁いただいているのですけれども、そうすると、保護者負担が上がる人はいないということなのですか。そこを伺いたいと思います。","respondent":"竹田保育課長","answer":"さまざまなご家庭の形態、あるいは所得があると思いますので、上がる方、下がる方は当然いるものです。ただ、全体としまして、先ほども申し上げたとおり、マイナス１％と試算しておりますので、全体として利用者負担が増加するものではないと考えております。","id":"exchange-106"},{"speaker":"石田（ち）委員","kind":"質問","question":"自分が値上がる保護者であれば、もう値上がりだという受けとめですし、値上げを中止してほしいという思いは当然だと思うのです。その中でも、希望する子どもの数が２人以上ほしいという方が８割を超えている。さらに、希望する２人以上の子どもを産める状況ですかと聞くと、厳しいと。負担軽減が必要だと区も述べていることに対して、この保育料値上げとの関係をどう考えるか、伺いたいと思います。","respondent":"竹田保育課長","answer":"今回の改定におきましても、第二子以降の対象者を拡大すべく、５歳児から小学３年生までに拡大し、第二子は半額、第三子については免除という形で課税しておりますので、少子化社会に対応した保育料になっていると考えております。","id":"exchange-107"},{"speaker":"石田（ち）委員","kind":"質問","question":"多子減額を拡大しているというところですけれども、延ばしたのは３年間です。歓迎はしますけれども、それで２人、３人産めることに対応していると私は感じないです。思わないです。それで、私たちもこの間言っているのですけれども、多子減額しているのですが、それに９％の区のマイナスがある。その辺の見解を改めて伺いたいと思います。","respondent":"竹田保育課長","answer":"一方で、少子化社会に対応することも必要と考えておりまして、一方で多子減額の拡大も行ったものです。図らずも同時ということでございまして、埋め合わせというご指摘は当たらないと考えております。","id":"exchange-108"},{"speaker":"石田（ち）委員","kind":"質問","question":"保育料の値上げを値上げでないと言う品川区に対して、父母の皆様は、今でも高い保育料をさらに上げるのかということで怒りの声を寄せているわけです。ですので、値上げではなく値下げこそ必要だと私は思います。そこをもう一回、何で有料になるのかというのを伺いたいのと、有料にされた分のお金というのは、何に使われるのですかという疑問もすごく多いのですけれども、そこも伺いたいと思います。","respondent":"伊崎子ども育成課長","answer":"今回は、利用料の値上げだけを行ったということではなく、利用者の方のご要望にお応えして、朝の開園時間、長期休業日、土曜日等、学校が休みの日の朝の開園時間を９時から８時１５分に引き上げたこと、それから、帰りのおしまいの時間も就労家庭については。","id":"exchange-109"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、登録料と保険料のところの１,２００円というのは、年間に１,２００円かかっていたというのは、私たちも承知しているのです。でも、利用料はかかっていなかったわけです。それを、有料化するわけです。値上げではなく、有料化にするのです。これだけの値上げが負担になるとは感じないのでしょうか。","respondent":"伊崎子ども育成課長","answer":"ただ、この中でも、その金額が負担となってすまいるスクールに参加できないということがないように、今減額・免除の対象を検討していますので、そこは考慮しております。","id":"exchange-110"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この間、値上げの根拠なども、学童保育クラブに合わせて３,０００円にしたり、ほかの地域と比べて、ほかの自治体と比べてもというお話なども出されているのですけれども、やはり学童保育との比較には私はならないと思います。そして、それによって参加できなくなるかもしれない子がいるやもしれない状況で値上げをしていく。改めて、私も中止を求めますけれども、いかがでしょうか。","respondent":"伊崎子ども育成課長","answer":"先ほど申し上げましたように、すまいるスクール全体の経費に対するご負担と考えていただければと思います。今回の見直し等々につきましては、既に条例でご可決いただいているところですので、来年度４月の実施に向けて準備をしています。","id":"exchange-111"},{"speaker":"飯沼委員","kind":"質問・要望","question":"でも、その子がどういう状況を抱えて、何を求めてそこにやってくるのかというのを、毎日同じ指導員の方が確実にいて、いつもその子を見つめていてくれたらわかるかもしれないけれども、決してそういう状況ではないと職員の方がおっしゃっているのです。私は、これは特殊な例ではなくて、多分職員の方に伺ったら、皆様そう答える。一人ひとりが問い合わせをすれば、どういうふうに変化するのかわかるのですか。","respondent":"竹田保育課長","answer":"在園児の方については、それぞれの施設を通じてご説明しています。施設長会等を通じまして、施設の長には私どももご説明させていただいているところです。なおかつ、ご質問のある方については、保育課のほうにお問い合わせをいただいているところです。","id":"exchange-112"},{"speaker":"飯沼委員","kind":"質問","question":"在園児の方に対しては、施設というと、園長先生が説明をする。説明会みたいにして行っているのですか。文書を配る。どういう形なのか。保育課のほうにはどのくらいお問い合わせが具体的にあるのか教えてください。","respondent":"竹田保育課長","answer":"広報紙にも詳細を載せておりまして、そういったものを通しまして、保護者の方には園からご説明いただいているところです。お問い合わせの数はカウントしてございませんので、正確な数は把握しておりません。","id":"exchange-113"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひカウントしていただきたいし、どういう状況なのかも、ぜひ実態を教えていただきたいと思います。なぜなのだろうと、なぜがいっぱい飛び出している。そして、必要に応じて税金というものは使うものなので、税金は本当に必要なところに使ってほしい。この税金をぜひ子どもたちに使ってほしい。私は、これは当然な当たり前の声だと思うのですけれども、どうしてこうならないのでしょうか。教えてください。","respondent":"竹田保育課長","answer":"保育料です。運営費全体に占める利用者の負担割合は、平成２６年度現在、１５.４％となっておりまして、前回の全保護者を対象とする保育料の改定から１０年以上経過していることから、今回の保育料の改定は必要不可欠なものだと認識しております。","id":"exchange-114"},{"speaker":"飯沼委員","kind":"質問・要望","question":"運営費負担割合が１５.４％、私はすごく高いと思います。これは本当になぜと、何回言っても納得できないことであると思うのです。なので、社会全体で子育てを応援しようという社会にしていこうという合意ができれば、十分品川区はできると思うので、私は行政のほうへはたびたび求めていますが、ここにいらっしゃる同僚の委員にもぜひ応援してくれる社会になってほしいと思うのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"したがって、ある程度の負担はやむを得ないと考えて、それをどうやって過不足なく合理的に組み立て、持続可能にしていくかが問題だと思います。だから、私たちはこの請願そのものは不採択でお願いしたいと思うのですが、それと同時に、区にも十分な説明を各利用者の方にしていただいて、誤解や情報不足のために理解が十分されていないようなところに関しては、十分な説明をするように要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"浅野委員","kind":"質問・要望","question":"不採択です。値上げというところで中止、中止ですけれども、応能負担という部分を考えていくならば、今後の負担増と言われる部分もありますけれども、適正な使用料というものが必ずあると思いますし、保育料でもありますので、それはぜひともある程度確保しながら、子育て支援を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"飯沼委員","kind":"意見","question":"一言言って、採択を主張したいと思います。子育てへの経済的負担軽減、これはなくてはならないものであると思っています。安心して子どもを産み育てられる品川区にしていくためにも、応援していくという意味で採択を主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-118"},{"speaker":"大倉委員","kind":"質問","question":"不採択でお願いします。適切な認可保育園の運営という部分においても、区からお話を伺ったところにおいては、納得できるところであります。今までもさまざま議論がされて決定されたことでありますので、今回の請願については不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"不採択でお願いします。先ほども出ていましたけれども、全体的な区の政策の中での整合性というところ、それは合理的な理由、あるいは応能負担といったところが理由だと思います。そして、改定の際に保育料のほうではさまざまな減免について、そしてすまいるスクールのほうは今後検討するということですので、そのあたりは確実に政策、制度として実行していただくことを要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"}]},{"id":"topic-09","title":"平成２７年請願第３３号、一人ひとりの子どもが大切にされる品川区を求める請願","agenda":"平成２７年請願第３３号、一人ひとりの子どもが大切にされる品川区を求める請願","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"一人ひとりが大切にされることを求める請願なので、共産党は多く紹介議員になってしっかり受けとめていますので、ぜひ皆様にもしっかり受けとめていただいて、ご発言をお願いしたいと思っています。命を守るというために、お母さんたちは認可保育園を求めている。ぜひ認可保育園をしっかりと柱に据えていくということを自治体は肝に銘じるべきだと思うのですけれども、この１点でいかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"認可外保育施設ということなのですけれども、まず確認しますが、明日の総合的な待機児童対策の資料にもあるところで、これまでもご説明していますけれども、東京都の認証保育所というのは、東京都の基準に従って設置、指導されているものですので。","id":"exchange-121"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は誤解しておりません。余分な言葉をつけないでいただきたいと思います。私はどの施設も見学していますし、身近なところは重々知っています。違いもわかっています。そこのところをどう捉えて、都が認証しているから、区が認可をしているから、それで認可保育園と同等であるというのは間違いだと思いますけれども、そこの認識はどうなのでしょうか。","respondent":"今井待機児童対策担当課長","answer":"認証保育所ですけれども、今、品川区内にＡ型、Ｂ型等ありますけれども、Ａ型の保育施設という形で開設補助金を入れているところは保育士が１０割、それから、現在、小規模保育事業につきましても、いろいろ去年の審議の中でご議論ありましたけれども。","id":"exchange-122"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今の答弁があるから、認可保育園と同じかという質問には全く答えていないのと、私はすごく施設をよく知っています。これは事実なのです。資格がある人が、認証は１００％、１０割保育士だといっても、どこもこれで確保されているかと思ったら、実態は違うのです。私は認可を柱にしていくことが、まず大前提であると思うのですが、さまざまなところではなく、本当に認可で増設を考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-123"},{"speaker":"石田（ち）委員","kind":"質問","question":"私は園庭のところで少しだけ。都市公園に認可保育園を設置することができるためのアンケートだということだったのですけれども、保育園の公園利用の実態というのは、とってきているわけですので、どういった保育園がどれだけの公園を使っているというのがわかったのではないかと思うのですけれども、その辺、今どんなところまで進んでいるかを伺いたいのです。","respondent":"今井待機児童対策担当課長","answer":"今回のアンケートにつきましては、委員ご案内のとおり、品川区内の保育園だけではなく、幼稚園、そして認可外保育施設にもアンケートをとったところです。主要な目的は、実際に公園をどのように利用されているかを踏まえて、公園の中に保育園の設置を検討していくものです。","id":"exchange-124"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この間、教育のところでも子どもたちの体力が落ちてきている。そういったところで特別なプログラムを組んでいくといったことも始まるわけですので、それはさらに進んでいくという状況にもつながりかねません。ですので、今後つくっていく認可保育園には園庭をつくっていくということを、区の姿勢として持っていただきたいと思うのですけれども、いかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"屋外遊戯場のかわりとなる公園またはそれぞれの保育の室内、または屋内のホール等で体を動かすなどの取組みについて、また保育園とその辺は検討していきたいと考えています。","id":"exchange-125"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、ぜひここに区の努力で応えていただけるようにしていただきたいと思います。そうすると、保育料の値上げをしたことで、待機児対策がぐんと進むということとして受け取っていいのかどうか確認したいのです。","respondent":"今井待機児童対策担当課長","answer":"保育料の決定につきましては、保育園運営経費、待機児童に伴う新規開設が当然保育料に反映していっているものだと考えております。","id":"exchange-126"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうですね。そうすると、保育料から増設に回るお金というのは、大体何割ぐらいになっていくのでしょうか。つくっていく数で違うとは思うのですけれども、大体１園増設するのに、保育料からかかるのはどれぐらいになるのか、わかれば教えてください。","respondent":"今井待機児童対策担当課長","answer":"先ほど、保育課長が答弁申しましたとおり、運営費の１５％が保護者負担です。ここに開設の経費が全て保育料の負担に入っているということではないです。全体の経費の中で今後検討していくものだと考えておりますので、何園つくったから幾ら上がるという単純計算ではないです。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問","question":"それで、補助金も納めているということなのですけれども、それは本当かと思ったのですが、そういう事実があるとして、詰められているのでしょうか。新年度の認証も含めてそういうことになると思いましたが、その点はいかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"先ほどの委員のお話の中で、明確にどこの認証保育所というご提示はございませんでしたけれども、そのような認証保育所がございましたら、私どもは速やかに立ち入りの検査等をしていきたいと考えています。","id":"exchange-128"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"先ほどの質疑の中で、認可保育園でなければ命を守れないという話があったのです。これは非常に失礼な話です。認証やその他のさまざまな保育園の方々が、一生懸命品川区のことを考えてやっているにもかかわらず、そういうふうに捉えられるような表現をしたということについては、やはり議会として品川区の見解を確認していただきたいと思うのですが、ご答弁をお願いいたします。","respondent":"今井待機児童対策担当課長","answer":"先ほども申しましたとおり、認可保育園、小規模保育事業、認証保育所、それぞれ大もとは保育所保育指針ですけれども、それぞれの基準、通知、要綱に基づいて、適切に子どもと安全、そして健やかな発達を保障するための保育を実践しています。","id":"exchange-129"},{"speaker":"伊藤副委員長","kind":"質問","question":"品川区のゼロから５歳の子どもが平成２７年時点で１万８,７３３人いるわけで、保育園に入ったのが６,９２１人。もちろん区立にかかる子どもたちを守っていく。さまざまな方法を展開していって、税の有効活用をすると同時に、保育園や幼稚園に通っていない子どもたちに対しても、品川区としてはさまざまな保育の環境を準備していくべきと考えますが、いかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"一方がゼロから２歳児に関しましては、在宅で子育てしていらっしゃる方も多いところですので、品川区としましては、明日ご説明します、私立幼稚園、区立幼稚園の預かり保育ですとか、また在宅子育てのための預かり、生活支援型の事業ですとか。","id":"exchange-130"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"２番目に、屋外遊戯場は非常に大切で、この請願書にも書いてあるように、幼児期は体力を培う上で非常に大切な時期であり、運動や遊びの中で十分に体を動かす必要があるということに全く異議はないのです。それと、最後に保育園をたくさんつくってほしいという３番目なのですが、これは当然のことでありまして、これに関しては品川区も今後努力されればいいのではないかということで要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"浅野委員","kind":"質問","question":"待機児童の解消、認可保育園の増設を行ってくださいとありますけれども、やはり今まで区が進めてきました認可保育園も当然増やしていく中で、認証保育所や小規模保育事業など、さまざまな選択肢と言ったらおかしいですけれども、事業者の選択肢が増えてきているということもありますし、このような手を活用してというのでしょうか、利用して待機児童対策をこれからも進めていっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"飯沼委員","kind":"質問・要望","question":"意見を添えて採択を主張します。先ほどの他の委員の発言なのですが、人の発言を曲げて表現するような手法はやめていただきたいということを１つ言っておきます。待機児対策、命を守るために国基準、国が責任を持つ認可保育園を柱に据えてほしい。心身ともに元気に成長するのに、園庭、公園はなくてはならないものであるということをしっかりと受けとめていただきたいと思います。採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-133"},{"speaker":"大倉委員","kind":"質問・要望","question":"請願については不採択でお願いいたします。品川区でも、多くの取組みをする中で、対応してくださっていると考えています。園庭についても、皆様おっしゃっていますが、あるに越したことはないですが、なかなか品川区の現状から考えると難しいという部分でありますので、そういったもろもろを含め、不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"不採択でお願いします。園庭については議論がありましたけれども、そういった事情でなかなかつくれない場合は、本当に安全を確保して、広場や地域の公園に連れていって、伸び伸びとそこで遊んでもらえるように保育士の配慮を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-135"}]},{"id":"topic-10","title":"その他の(2)その他を行います。 まず、今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、文教委員会にかかる項目","agenda":"その他の(2)その他を行います。 まず、今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、文教委員会にかかる項目","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"共産党の南議員の定時制高校のところで、マイスクール八潮の質問で、受け皿になっているのではないかという質問の答弁で、マイスクール八潮だけに限らず、全ての生徒の選択肢に定時制はなっているという答弁だったのです。区としては、定時制高校は存続していくべきだという立場なのかどうかを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/111718?Template=document&Id=4870#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":88300,"voices":417}},{"id":"h27-20151130-5","meetingId":"h27-cm11","date":"2015年11月30日","dateIso":"2015-11-30","committee":"総務委員会","time":"午前１０時００分～午後 ５時０８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を91件抜き出しています。","topics":[{"id":"topic-01","title":"では、(1)の第８５号議案からの審査でありますが、会議の運営上、審査の順番を入れ替えます。 まず","agenda":"では、(1)の第８５号議案からの審査でありますが、会議の運営上、審査の順番を入れ替えます。 まず","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それと、この間、給与が下がってきて、ちょっと上がってきている傾向ですけれども、今回の改正に対する区の評価といいますか、もとに戻ったというふうに評価しているのか、まだ以前のところと比べればどうなのか、それぞれ中身によって違うかもしれませんけれども、区の評価も２点目に伺いたいと思います。","respondent":"米田人事課長","answer":"２４年ぶりということで、２年連続の引上げ改定ということについては、労働側のほうも一定の評価をしているものではありますが、なかなか、もう少し上がるべきだろうというような議論ですとか、あるいは引上げの改定については、可及的速やかに実施するようにというようなところ。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"今回、特別区人事委員会から、このような給与改正の案が出されたということでわかるのですが、これも民間従業員の給与水準と均衡させる民間準拠の方法を採用しているとあります。ここでちょっとお聞きしたいのですが、品川区内の中小零細企業の給与、また、品川区ですから、小さな商店、工場、そういうところで働いている勤労者の給与水準は、実際上がっているのでしょうか。わかる範囲で結構です。","respondent":"米田人事課長","answer":"そちらが今回、民間と比べて公務員のほうが幾らか少ないということで、平均０.３５％の引上げを図ったというようなことで、一定程度、私どものほうで比較対象としている企業の方々の給与水準は、大きくはないですが。","id":"exchange-002"},{"speaker":"須貝委員","kind":"提案","question":"そうすると、今、品川区は、特別区人事委員会と組んで条例改正するわけですが、区内の実態、経済、実際に区内を支えている商店、まちの工場、そういうところの給与水準と、今回こういうふうに上がるという提案なのですが、大分かけ離れているようにすごく思うのです。その点、今、課長は全体像ということで答弁してくださいましたが、実際は、区内は私が今聞いたところとは違うのですか。","respondent":"米田人事課長","answer":"区内の状況につきましては、詳細に私のほうで把握をしているものではございませんが、品川区の給与の水準を決めるに当たっては、その区域内にあります特別区の類似の企業等から資料をいただきまして、それをもとに給与水準を算出しているものですので。","id":"exchange-003"},{"speaker":"須貝委員","kind":"意見","question":"そうすると、我々は区民のために、いろいろ区政を司って様々な事業を展開している中で、そういうギャップがあっていいのかということはすごく感じます。そういうことを鑑みると、今回の職員の給与に関する条例改正案に対しては、我々の会派としては賛成いたしかねます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"本多委員","kind":"質問","question":"人事委員会では勧告する前に民間企業のいろいろサンプリングをすると思うのですけれども、情報収集をすると思うのですけれども、民間企業の対象にするものは、人事委員会がこういう作業を長年やってきていて、サンプルをとる対象は変わりつつあるのか、その辺の推移みたいなところを概要を教えてください。細かいことではなくて、変化があるとかないとか、その辺のことで。","respondent":"米田人事課長","answer":"これは、５０人程度の人数であれば、ある程度、公務員の組織に準じた組織構成なりがあるので給与比較ができるだろうという判断に基づいて、国および東京都、各人事委員会もそういうような水準に置き替えているところです。","id":"exchange-005"},{"speaker":"本多委員","kind":"意見","question":"企業にもいろいろあると思うのですけれども、大企業から中小企業までありますけれども、やはりその辺の的確なところを見ながら人事委員会が結論を出しているものだと考えていますので、適正だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"給与そのものから少し外れてしまうかもしれないのですけれども、人件費トータルで考えたときに、例えばこの引上げということは、少し人件費に余裕が出てきたという面もあるかと思います。新規の採用については労使交渉の中ではテーマになったのか、あるいは、もしテーマに入れたとしたら、どういう方向で交渉されたのか教えてください。","respondent":"米田人事課長","answer":"あくまでも給与条件の確定の交渉ですので、そちらについては出ていないというふうに記憶しています。","id":"exchange-007"},{"speaker":"あくつ副委員長","kind":"質問","question":"労使交渉の妥結も経ているということで、もちろんそれは尊重するという上で、１つだけ質問です。以前と比べて職責が高くなっているというところを何かご説明ができる、例えば判断をたくさんしなければいけなくなったとか、人数が減ったとか、あとは訴訟のリスクの矢面に立たなければいけないとか、何かそういう高まりというものがあるのであれば、そこのところをご説明いただければと思います。","respondent":"米田人事課長","answer":"そういった中で、いわゆる管理監督層の職員ですけれども、ある程度人数を絞り込んで任用をしております関係上、どうしても係長級以上の職責は高まっているだろうということが、品川区のみならず、特別区全体について言えているものであるというふうに考えてあります。","id":"exchange-008"}]},{"id":"topic-02","title":"に戻りまして、(1)第８５号議案 品川区行政手続における特定の個人を識別するための番号の利用等に関する法律に基づく個人番号の利用および特定個人情報の提供に関する","agenda":"に戻りまして、(1)第８５号議案 品川区行政手続における特定の個人を識別するための番号の利用等に関する法律に基づく個人番号の利用および特定個人情報の提供に関する","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"区はどういう対策をとっているのか。品川区のミス等についてはどういう状況なのか、伺いたいと思います。１つ１つの事業に細かく入るつもりは全くないのですけれども、住民にとってマイナンバー制度は一体何がどう便利になるのか、いよいよ手続に入る条例がここから始まるというわけですから、ここもしっかりとご説明いただきたいと思います。","respondent":"仁平情報推進課長","answer":"２点目の区民の方にとって何が便利になるかというお話ですけれども、こちらは、このマイナンバーを使って事務の効率化を図っていきますけれども、制度で予定しておりますように、今後、電子的に自治体間のネットワークを組むことによって、今まで住民の方が窓口手続きで。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば、子どもの年齢とかいろいろ書く欄も当然あるわけですけれども、そういうところのマイナンバーも記載するようになるのか、そうした場合、そのお子さんの本人確認は一体どうやってやるのか、逆に窓口に家族全員分を持ってくる、人に渡して、それをよしとするのか、どう管理するのか、その辺がわからないのですけれども、ご説明いただきたいと思います。","respondent":"仁平情報推進課長","answer":"誤配ですが、１１月に２件発生しております。郵便局から区のほうへの報告は速やかにあったと思うのですが、日付は覚えておりません。申し訳ございません。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"大体初めてこれだけの量を一気にお願いするというこの制度そのものが、前回指摘したように無理のある仕組みだと思いますけれども、そういう意味では、２件の誤配については改めて委員会に、経過とその後の対応も含めてご報告をしていただきたいという要望をしておきたいと思います。そうではない、例えば保育園の関係だったら、２人の所得に関係すると、配偶者分も書くことになるのか。","respondent":"中山企画部長、仁平情報推進課長","answer":"事務の説明は後ほど課長のほうから。冒頭の誤配に関する対応です。申請時におけるマイナンバーの使い方ですけれども、先ほどご説明しましたように、必要な方ということで、所得情報を把握しなければいけない方の個人番号を申請書に記載していただくというような形になります。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"子どものマイナンバーの記載に、今、予防接種という話でしたけれども、もうちょっと伺いたいのが、予防接種だけなのですか、ほかにもあり得るのでしょうか。窓口で家族、目の前にいる人の本人確認は顔とかでやったにしても、その家族の方の番号が、また子どもの番号が本人かというのはどうやって確認をするのか。なので、大事なところになりますので、改めてこの点を伺いたいと思います。","respondent":"仁平情報推進課長","answer":"例えば障害者関係の手当の給付ということになりますと、その給付自体を受けている方がお子さんということであれば、そちらの方の個人番号の記載というのは考えられる話です。","id":"exchange-012"},{"speaker":"中塚委員","kind":"確認","question":"窓口に来ている本人以外の配偶者や家族のマイナンバーが本人だということをどう確認するのか、その点改めて伺いたいと思います。特定の人に限った、例えば課長のようにそういう課の人間というわけではなくて、あらゆる事業に広がるわけですから、区の職員、非常勤、委託も含めて、全員がその研修の対象なのか、そこを確認したいと思います。","respondent":"仁平情報推進課長","answer":"それと同時に、今後ですけれども、特定個人情報を処理できる職員も、課であっても中で切り分けていくような仕組みをシステム的に行っていく、そういう予定になっております。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここは大事だと思うので改めてご説明いただきたいのと、やはり書類の煩雑さ、また実際に区の職員の方の仕事量も随分増えるわけですから、改めて必要な対策や体制、しっかり検討していくべきだと思うし、もともと私は進めるべきではないという立場ではあるのですけれども、そこの課題はあるのではないかと思いますけれども、同じことですみませんが、改めて伺いたいと思います。","respondent":"仁平情報推進課長","answer":"申請に家族全員で来て、個人番号カードと本人確認を全部行うという、その辺の手順は、必要な部分は個人番号の確認と、その方の本人確認自体は行わせていただきますけれども、家族全員で申請に来なければいけないというような、そういう手順ではなくて。","id":"exchange-014"},{"speaker":"大沢委員","kind":"質問・要望","question":"この番号の利用等に関する、税に関するものと社会保障に関するものと、あと防災に関する事務ということで、以前の自分の中では認識をしております。この６ページ以降、法定あるいは独自利用、連携ということであるのですけれども、最後の防災に関する事務のところは、どうも探しても見当たらないのですけれども、そこのところはどのような位置づけになっているのか教えていただきたいと思います。","respondent":"仁平情報推進課長","answer":"防災関係につきましては法で対応する部分がございまして、それ以外で、例えば区も検討したのですが、要支援者名簿の作成にはどうかという検討があったのですが、個人番号をその時点で管理しては提供等に影響があるだろうということで、今のところ見送りになっております。","id":"exchange-015"},{"speaker":"大沢委員","kind":"質問・要望","question":"災害時というのは、今、国のほうで一元管理ということで聞かせていただきましたけれども、災害のときほど地方自治体が窓口になっていろいろな情報を共有し管理することが大事だと思うのですけれども、そこらのことも承知の上でそのような結論を出されたと思うのですけれども、もう一度すみませんけれども、そこのところの経緯と行政で判断をした考え方を教えていただきたいと思います。","respondent":"仁平情報推進課長","answer":"法の方では、緊急時には利用できるということになっておりますので、起こらないほうがいいのですけれども、非常時の場合には、行政としては対応していくという、これは法律に基づいて対応していくということになります。","id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"先ほどのご答弁の中で、例えば要支援者名簿については当面は見送るというような表現があったわけですけれども、この内容は、特に法定の部分は法に基づいて増えるものは増えるということだと思うのですが、これの独自利用は、今後も流れとしては検討の進捗に従って増やしていくという方向にあるのでしょうか。その場合はどのような手続き、条例改正を伴いながらということになるのでしょうか。","respondent":"仁平情報推進課長","answer":"条例に定めるものは、今現在で必要と判断したものでございまして、今後、国のほうで、例えば新しい法律ができて、新しい福祉サービスが始まる、そこで個人番号の利用が始まるということで。","id":"exchange-017"},{"speaker":"あべ委員","kind":"確認","question":"重ねての確認になりますけれども、法の関係ないし条例の改正といったものを伴わないうちに内容が増えていくということはないという理解でよろしいでしょうか、これが１点です。","respondent":"仁平情報推進課長","answer":"それと予防接種関係ですけれども、現在も未接種の方には勧奨のお知らせはされているかと思いますけれども、１つに、マイナンバーの中に個人番号カード利用者のマイナポータルという仕組みが今後つくられていきますけれども。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問","question":"これはどんなことなのでしょうか。それができて、さらに区がそれを導入するかどうかということを決めていくのか、個人がそれを希望すれば、そのサービスが始まったら、それを希望する個人がそのサービスを選択できるのか、その辺の状況を教えてください。逆に言えば、選択しなければ、そのお知らせは行かないということになるのか、その辺も教えていただければと思います。","respondent":"仁平情報推進課長","answer":"その中の１つのサービスとして、プッシュ型のサービスも行うような仕組みを導入していく、そういうお話です。","id":"exchange-019"},{"speaker":"大沢委員","kind":"質問","question":"先ほどの続きなのですけれども、４ページの防災に関する云々で条例は、災害時のとき、防災に関する事務は法で対応するということですけれども、ここで「条例で定めるものの処理に関して」と、すなわち、条例で定めていないものはだめという話というように私は読み取れるのですけれども、ここの条例を見てみると、そういう文言は私には読み取れないのですけれども、これで大丈夫なのですか。","respondent":"仁平情報推進課長","answer":"これに基づいて、緊急時には区は対応できると判断しているものです。","id":"exchange-020"},{"speaker":"大沢委員","kind":"質問","question":"緊急時は条例で定めるものでなくても対応ができるという、そういう法律の読み込み方でいいということですね。そうすると、今、課長がおっしゃった部分のここのところには説明がないので、説明が欲しかったのですけれども、仮にそこの部分で書く必要がなかったのか、表示する必要がなかったのか、私は表示をしていただきたかったと思うのですけれども、いかがでしょうか。","respondent":"仁平情報推進課長","answer":"申し訳ございません。資料は主に関係するところでという抜粋で載せさせていただきましたので、防災につきまして説明不足だったことは申し訳ございません。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"こういう手続き等で、マイナンバー制度は大変だと思いますが、全文きちんとできて、また報告していただきたいと思います。１点だけ簡単なことをお聞きしたいのですが、今回、マイナンバーカードで郵送されてきました。そして、その場合に法的罰則等はどのようになっているのか、すみません、それだけ教えてください。","respondent":"仁平情報推進課長","answer":"それと、受け取らなかったからということでの罰則等は特にございませんで、ただ、番号自体は決定しておりますので、こちらが消えるということはございませんし、実際に本人を確認する時点では。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"それぞれその後の対応が違うと思うのです、もっと厳格にと言われても。もし何かが省略みたいなことがあるのであれば、そういうことは決してしないようにというようなこともありますけれども、そうでなかった場合は対策も難しくなると思うのですが、具体的にどういうミスが起きて、そのミスにどう厳しく今後の対策をとってほしいというふうに申し入れたのか伺いたいと思います。","respondent":"仁平情報推進課長","answer":"次に８軒目の方にお伺いしたときに、ここもご不在でしたので、その対応をしようかと思ったところに、７番目の方が戻ってきたのです。「これが入っていました」ということで、「わかりました、では、こちらになります」と渡したときに、８番目の方のものを渡してしまったという。","id":"exchange-023"},{"speaker":"吉田委員","kind":"確認","question":"ということは、その場で本人確認を忘れてしまったという、忘れたというか、省略してしまったということで理解してよろしいでしょうか。","respondent":"仁平情報推進課長","answer":"その７番目の方からは郵便局にすぐに連絡がありまして、隣の方のものですということで、郵便局のほうですぐに回収しに伺ったということでございまして、開けられていなかったということです。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"もう１つ伺いたいのは、この間もそれぞれの個人にとってどう使ったらいいのかというものが何も提示されていないので、例えば、すまいるの手続きをするときに、具体的にはその手続きのときに個人番号を記入するという、そういうことが求められるということなのでしょうか。","respondent":"仁平情報推進課長","answer":"ただ、カード自体、小さいものですので、その辺につきましては、今後とも区としまして番号の利用上の注意点など、啓発を引き続き続けていくと同時に、窓口でどういう申請書が変わるかというところも、例えば広報紙は紙面の関係がありますけれども、区のホームページで。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のやりとりの後半のほうで、忘れたら追い返すことはないというお話があったのですけれども、それはどういうことかという質問と、区のほうで調べ直すというお話がありましたけれども、それがどういうことかを伺いたいと思います。つまり、忘れたから追い返すことはないというのがどういう流れなのか、区のほうで調べ直すというのはどういう流れなのか、ご説明いただきたいと思います。","respondent":"仁平情報推進課長","answer":"窓口の対応ですけれども、例えば申請書を書いていただく欄には個人番号欄があった場合に、記憶してはいませんが例えば通知カードを忘れてきてということになりまして、その場合に、我々行政機関の個人番号利用ということは法で定められている利用の場合には。","id":"exchange-026"},{"speaker":"中塚委員","kind":"確認","question":"この申請書にマイナンバーカードの書いてあるものを忘れてしまって、それを窓口で実際は教える。そのときは厳正に本人確認をするということですけれども、つまりはどうやって本人確認をされるのですか。つまり、その方は番号カードを持っていないという前提になるわけですよね。やはりそこになりすましの要素が含まれてくるのではないかと思うのですけれども、その点を改めて伺いたいと思います。","respondent":"仁平情報推進課長","answer":"受付の段階で実際に来られて申請されてきた方がご本人なのかどうかは、公的な身分証明書といいますか、例えば免許証とかパスポート、こちらの写真つきの公的な身分証明書、こちらをお持ちでなければ、例えば健康保険証、健康保険の資格のカードになりますけれども。","id":"exchange-027"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"長時間になって申し訳ないのですけれども、大事なテーマなので、会派からも幾つか疑問点がありまして条例の審査に入る前に少し聞いてこいと言われたことがあるので。先ほど、返送された１,４６０件と伺ったのですけれども、もしわかれば、現在まで何％とか、何件届いているのかということを教えていただきたいことが１つ。その２点、先にお伺いしたいと思います。","respondent":"仁平情報推進課長、立川経理課長","answer":"そういう仕組みの写真機が、今現在、第二庁舎の３階に設置しているところです。ただいまの補足です。先週の１１月２５日に設置をしました。１２月１日からご利用できるです。","id":"exchange-028"},{"speaker":"あくつ副委員長","kind":"質問","question":"先ほど、もう設置をされているということですけれども、１２月１日からということなので、明日からですね、それは料金はどれぐらいかかるのか。例えば郵送で出した方と比べるとどちらが有利とか不利とか、マイナンバーカードをもらえるのが早いとか、そういったことがあるのかどうか、わかる範囲で、１２月１日は明日からですからわからないと困るのですけれども、その辺を教えていただければと思います。","respondent":"立川経理課長、仁平情報推進課長","answer":"ご利用料金ですけれども、８００円からです。８００円から１,０００円でございまして、１,０００円というのは、ちょっときれいに撮れるものです。Wi-Fiで申請を飛ばすということになるのですけれども、詳しいことはわからないのですけれども、当然。配達の完了時期ですけれども、進捗を考えますと、一部の報道では、東京都は１２月８日ぐらいには完了するのではないかというような。","id":"exchange-029"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"この質問はこれで終わりますけれども、これはうちの会派の中でみんなから言われたのですけれども、やっぱり気になっている方がたくさんいらっしゃるということで、本当は当初のとおりにできるだけ１２月中旬ということで配達を終えていただきたいことが１つと、先ほどの写真機のことは、明日からということなのですけれども、広報をしっかりやっていただければというふうに思いますが、何かあれば。","respondent":"中元広報広聴課長、中山企画部長","answer":"既にプレスリリースは１１月２５日付で行っておるところです。広報しながわでは、１２月１１日号に個人番号カード発行に関する記事を載せる予定で準備をしております。その中で今の発行機のことも載せる予定で準備をしています。改めてですけれども、いろいろ配布の関係だとか、基本的には戸籍住民課のほうで配布について区民委員会への報告であるとかをやっているところでありますけれども、今の新しい取組みであるとか広報。","id":"exchange-030"},{"speaker":"あくつ副委員長","kind":"確認","question":"では内容等で少しだけすみません。先ほどのご答弁、ほかの委員とのやりとりの中で、マイナポータルの話が出たのですが、これはカードがないとだめなのでしょうか。例えば就学援助を申請をされた方については、情報照会機関が教育委員会から照会があって、生活福祉課であるとか、税務課から情報を提供しましたというものが全部今後自分で確認できるようになるのか、そこのところを教えてください。","respondent":"仁平情報推進課長","answer":"ただ、課題的には、では、自治体の中で組織的に情報提供した分にはどうなのかというその記録については、今後どういうふうにしていくかということで検討課題にはなっているという話になっております。","id":"exchange-031"},{"speaker":"あくつ副委員長","kind":"質問","question":"みんながみんな見られるという状況は本当におかしなことで、品川区がこんなふうに大きく取り上げられるということは、そういう指針がないのかと心配になってしまうことが１つと、課内において、もしくは係においてなのかわかりませんが、大体どれぐらいを想定されているのか、人数です、もしわかるのであれば教えてください。","respondent":"仁平情報推進課長","answer":"ただ、例えばデータ更新を行う等々、全庁的に必要な部分で情報を検索しているという、住民票台帳関係ですけれども、こういう仕組みの分けがありまして、それは共通検索といいまして、課の中に１台設置されて、必要なときに登録された人間だけが使っているのですけれども。","id":"exchange-032"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"先ほど、人的なところと、品川区独自のセキュリティシステムだと思うのですが、それは本当にありがたいことだと思います。最後は要望ですけれども、品川区独自でそうやってセキュリティを厳しくしているということであるので、本当にセキュリティのことについては、漏出等々ないようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"あべ委員","kind":"質問・要望","question":"それで、まだ全く配達していない割合は、ある程度残っているのでしょうか。ぜひこういった数字も細かく数字を把握していただきたいと思うのですが、先週あたりも、まだうちには配達に来ていなくてどうなっているのだろうと不安に思っているようなお声も聞きましたので、その状況を、配達していない方々の内訳がわかるとありがたいのですが。","respondent":"仁平情報推進課長","answer":"誠に申し訳ございませんが、郵便局の残っている、まだ未着手の通数がどのぐらいあるかまでは確認できておりませんで、申し訳ございません。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問・要望","question":"要は、届いている、届いていないというようなことで、結構区民の皆様、不安になったり、よく話題にもなりますので、それは区として関心を持って、最後の報告を受けるというだけではなくて、関心を持っていただきたいと思いますし、この不安な状態は一番関連の詐欺みたいなものが電話でかかってきたりするような状況もありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"中塚委員","kind":"意見","question":"誤配が２件、あと書類や窓口の煩雑さ、情報漏えいの問題、進めるべきではないと思いますので、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"生活者ネットワークも、こういう個人に番号づけをするようなことにそもそも反対であると同時に、やっぱり今の手続きを伺うと、誤配の問題もありますし、まだまだいろいろなところが詰め切れていない、その状況で進めていくというのは本当に危険だと考えていますので、反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-03","title":"第８６号議案 品川区長等の退職手当に関する条例の一部を改正する条例","agenda":"第８６号議案 品川区長等の退職手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"規定の根拠が変わったということですけれども、この変更で具体的に何がどう変わるか、もう少し説明していただきたいと思います。","respondent":"米田人事課長","answer":"それによりまして、地方公務員等共済組合法の不要な条文については、厚生年金に統一する観点から、もともと共済年金に係る部分の条文についてはなくなったということで、そちらについての条文の変更があったです。","id":"exchange-038"},{"speaker":"須貝委員","kind":"質問","question":"ちょっと聞きたいのですが、ここには載っていないのですが、今、区議会議員に関しては退職金はもちろんありません。区長に関しては退職手当があるということなのですが、実際、どういうときにもらえて、幾らぐらいの額なのか教えてください。","respondent":"米田人事課長","answer":"それぞれの任期の満了のときに、１年当たり、例えば区長ですと１００分の４８０という比率に基づいて、在職年数ごとに、いわゆる任期の更新がありましたら一旦退職ということで、その更新ごとに支給されるものです。","id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"大体、例えば４年を基準とするのですか。そうすると、金額的にはどれぐらいの金額になるのでしょうか。","respondent":"米田人事課長","answer":"この第４条は特例的な取扱いですので、第４条の前に第３条ということで一般的な取扱いということになっています。その一般的な取扱いの場合は、概ね現行の給料で計算いたしますと、約２,２００万円余ということになります。","id":"exchange-040"}]},{"id":"topic-04","title":"第９４号議案（仮称）東五反田四丁目認知症高齢者グループホーム新築工事請負契約","agenda":"第９４号議案（仮称）東五反田四丁目認知症高齢者グループホーム新築工事請負契約","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"今は現地はちょうど解体工事中であったかと思いますけれども、今後の竣工までのスケジュールについて教えていただければと思います。","respondent":"立川経理課長","answer":"解体につきましては今年度中でございまして、今年度、解体中に説明会を実施いたしまして、年度内の着工を予定しております。竣工につきましては、平成２９年２月末でございまして、開設は平成２９年５月を予定しています。","id":"exchange-041"},{"speaker":"あべ委員","kind":"質問・要望","question":"現地は割と周囲に住宅が多くて道路幅も狭くてということで、説明会でも出てくると思いますけれども、近隣に対する建設の騒音や振動あるいは交通や通行の安全といったものを、ぜひ近隣住民の方々のお声に配慮しながら進めていくということを、この落札された業者にもお願いしていただきたいと思います。どこの工事でもそうですけれども、やはり住宅地ですので、その辺をよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"あくつ副委員長","kind":"質問","question":"福祉計画課長からもお話を伺ったのですが、２億４,０００万円であの土地を取得をして、国から買ったということで、あの地域にはグループホームがないということで、利用目的としては大変すばらしいと思います。うまくいっているのか、うまくいっていないとは言われないとは思いますけれども、うまくいくのかどうかという、そこら辺の工夫について教えてください。","respondent":"大串福祉計画課長、立川経理課長","answer":"こちらの運営事業者、指定管理者候補者予定者という形になるのですけれども、こちらは新生寿会という社会福祉法人。既に品川区内で小山倶楽部というグループホーム等を運営している社会福祉法人です。設計と施工につきましては、基本的には分離して発注していますので、地域的に離れていると言いましても、当然、出張等をしてもらって、連絡を密にとっていただいて施工はしていくということで聞いているところです。","id":"exchange-043"}]},{"id":"topic-05","title":"平成２７年請願第２７号 上大崎シルバーセンターに隣接した空家の土地を品川区で取得することに関する請願","agenda":"平成２７年請願第２７号 上大崎シルバーセンターに隣接した空家の土地を品川区で取得することに関する請願","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"例えば、アンケートには答えていらっしゃらないということですが、実は請願者の方とも少しやりとりさせていただいて、少しは交渉してもいいというところまでお気持ちが動いていらっしゃるということは伺ったのですが、例えば品川区としてそういうお申し出があるとか、そういう事実はあるのでしょうか。それがあると、とてもいいなと思うのですが、その辺はどうなのでしょうか。","respondent":"柏原企画調整課長","answer":"先ほど申しましたように、空き家という視点といいますか、空き家の条例をつくりまして、区がそれに今対応ということで動いてありますので、その中でアンケートをしたというところがあります。","id":"exchange-044"},{"speaker":"吉田委員","kind":"質問","question":"そういったときに、本当にこれは質問なのですけれども、もし採択したときに、どういうことになるのでしょうかというか、もちろん請願者の方は、まさか無条件で取得するなどということをおっしゃりたくてこう書かれたのではないということは私もわかりますし、そうだと思うのですけれども、でも、文言が土地を取得するという結論の請願になっているわけです。","respondent":"柏原企画調整課長","answer":"お答えがそのまま１００％お答えになるかどうかちょっとあれなのですけれども、こちらは今ご説明した中で、課題になっているご議論をいただいて、一定程度の結論が出るというところなのだと思います。その結論に基づいて、区としてどう判断をしていくか。","id":"exchange-045"},{"speaker":"吉田委員","kind":"確認","question":"そういう意味であれば、私としては本当にこの趣旨はとても賛成で、もっと早く空き家対策ということであそこはどうにかなっていたらよかったなというふうに思うぐらいなのですけれども、例えば、そういう意味で割と皆さんと一致するのであれば、まさか取得と言ったからといって、いきなり必ず売りなさいみたいな、もし取得としても、もちろん売買が前提になっているでしょうし。","respondent":"原区議会事務局長","answer":"議会としては、その措置結果を求めて、その請願の処理がその後どうなったかというような報告を求めるというような形になっていますから、まさに先ほど企画調整課長が言った形で、それを受けた後、区長がどのように判断するかというのは。","id":"exchange-046"},{"speaker":"本多委員","kind":"質問・要望","question":"この請願につきましても、願意ですので、それをどうするかということは、十分この議会で意思を判断できるものだと考えています。それで聞きたいのは、今のやりとりで、空き家としての情報収集は区はしたのだけれども、区からの申し入れはしていないということなのですけれども、所有者は今こういう請願が出ているとか、動きはご存じなのでしょうか、それが１つ。","respondent":"柏原企画調整課長","answer":"直接的にこの持ち主の方と我々もアプローチとかコンタクトをとっているわけではありませんので、請願そのものがどういう形で出ているかということは、我々のほうで確認をしているというところではございませんので、ほかの方からもお話がありましたけれども、区としては。","id":"exchange-047"},{"speaker":"大沢委員","kind":"確認","question":"防災上の空き家という部分の切り口での情報は持っていらっしゃるけれども、そこの土木とか、権利関係に対する情報は持っていないんですよね、そのことを確認をさせてください。そこのところは、さっき防災上の観点から空き家の部分の情報、また今、後者のほうは別の情報だと思うのですけれども、後者のほうの情報については何か持っていらっしゃるところはあるでしょうか。","respondent":"柏原企画調整課長","answer":"その方から、正式な形での回答なり連絡は、その流れの中ではいただいていないという状況です。","id":"exchange-048"},{"speaker":"あべ委員","kind":"質問・要望","question":"先ほども現地を改めて見せていただきましたけれども、この請願の中で言われるように、手入れが十分でない部分も確かに感じました。こういったご要望があるというのは当然この中に書いてあるわけですけれども、今のシルバーセンターとも絡めながら、最終的にどういう形でというのは、これまたいろいろな選択肢がまだ残され、他の行政需要も考えながら勘案していくべきものだろうと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"須貝委員","kind":"確認","question":"話を聞いていてびっくりしたのですが、あくまでも人様の所有物である不動産を、持ち主の、例えば売却の意思があるとか、売却代金がどうで、売却条件が出ているならわかるのですが、それがないのに、請願で今回どうでしょうかと決めるべき次元のものではないと私は思います。それはそれで、今、地域活動課が進めている交渉と、そういう経緯を見守ってやるべき話ではないかと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"中塚委員","kind":"確認","question":"都市計画法に基づく話だと話が大きく変わってしまうので、要するに、取得とは購入であって、いわゆる民民の任意売却かどうかを１点確認したいことと、もう１つは、平たく言うと、品川区にここの土地を購入していただいて、多世代のものに使ってほしいという中身だということでよろしいのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"今の質問にも関係するのですけれども、一応１点確認したいのですが、所管が違うのですけれども、今回の請願の標題は空き家の土地ということで、品川区も空き家条例をつくって、空き家の利活用ということを所有者に促すということも１つの区としての取り決めになっていて、利活用というのは、取得ということも当然入ってくるのではないかと私自身は思うのですが、このところを区としては。","respondent":"柏原企画調整課長","answer":"その中には、それを借りるだとか、譲渡を受けるだとか、そういう選択肢もその中にはあるというところではありますけれども、それを前提に全部動くということではありませんので、特にこれは民間の方が持っている所有物ですから、そこに関しては意向を聞いて。","id":"exchange-052"},{"speaker":"あくつ副委員長","kind":"質問","question":"今のご答弁は、この解釈の中で、利活用の中に購入を妨げるものではない。ですから、購入ありきとかという話ではもちろんなくて、多分、請願者の方はそれをわかった上で請願をされているということは私は感じました。先ほどの回答になればというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"大沢委員","kind":"質問","question":"先ほどどなたか委員が言ったように、これをやったから行政のほうで我々が私の財産に足を突っ込む、そういう話のものではなくて、あくまでも請願なのですから、地域の方から出た、お伺いを立てたことに対して、我々はそれに対してどうかという、ここはそういう意思を表明する場所だと思います。あくまでもこれは請願ですから、私有財産に行政が足を踏み入れるとか、そういうことではないと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"吉田委員","kind":"確認","question":"おっしゃるとおり、だから結論が、いろいろあって購入になるのは私も全然オーケーなのです。請願者の方がそういうふうに思われるのももちろんそうなのですけれども、ここで採択をしてしまうということが、議会が採択するわけですから、それが結論が取得というのがありきの文言で採択してしまうことが、そこまで入ってしまうのではないかということを懸念して私は解釈とか質問をしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"中塚委員","kind":"質問・要望","question":"我々は執行機関ではないので、この請願がそのとおりと言うか、いやそうではないと言うかであって、そのとおりとなれば、区にそれを進めてくださいと投げかけるわけであって、その結論は結論で、出てきたものに対して、またもちろん議論が進むわけであってということだということと、あと任意売却である以上、あくまで双方の合意ですから、相手がどんな理由であれ断れば進まないし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"須貝委員","kind":"質問","question":"これを請願で人の土地、建物云々に関して、これをここへ出して、議会で決めるべき話ではないし、逆に町会長たちに、こういう出し方はよくないですよということを私らはやっぱりいさめなければいけないし、これは今回、引っ込めてくれと言わなければ、僕らはそういう立場だと思うのです。きちんとした地域活動課の人もいるのだから、いろいろ相談してやるべきではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"大沢委員","kind":"意見","question":"それは、請願というものに対する本質的なものよりも、それは須貝委員の単独的なエゴイスティックな自己見解に満ちたものだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"本多委員","kind":"質問","question":"請願権はやっぱり大切にしたほうがいいと思うのです。請願者の皆さんは地域の課題を、思いを願意に込めてやっていて、それを区議会議長が受理をされて総務委員会に付託をしたわけですから、我々の使命としては、これを真剣に討議する必要があると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"あべ委員","kind":"質問","question":"やはり私もちょっと引っかかりました。町会長も区民ですから請願権はありますし、いさめたり、間違ったりというようなことではないと思います。やはりこういった思いがあって、皆さん、署名をされた方も６００人を超えるというお話でしたので、ある程度、地域の意見をまとめてくださって、ここに出してこられた。それに対して私たちがどう受けとめるかというのが、この場かなというふうには考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"吉田委員","kind":"確認","question":"私も請願権は認めます。それで結局、それは一度継続ということになったのですけれども。だから、請願権はそこの思いなので、どんな請願であっても、あとは区議会の判断であって、もし採択となっても、その先の相手方の基本的人権の侵害にはならないのだというふうにちゃんとここで確認がとれれば、私は採択したいと思いますが、少なくともそのときには、理事者の方がそういうふうに答弁をなさっているのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問・要望","question":"ごめんなさい、相手の所有権に踏み込むことになるというところが、本当に正直よくわからないので、もうちょっと教えていただきたい。何か事例があるのだったら、それはそれで教えていただければ。それは執行機関の話であって、我々が今議論しているのは議会の話であって、この願いに沿って区に進めることを求めるのか、求めないのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"吉田委員","kind":"確認","question":"いや、別に単純に、取得という結論になってしまうので、それを採択するということが、取得は相手方の意思がある前提ですよね。それが「取得」という言葉だけで採択してしまうと、相手方の意思の確認も何もなく、その言葉だけが採択、だから、ちょっとごめんなさい、それは、だから最初に理事者に質問したのですけれども、採択するということが、どの辺まで取得というもの。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"あべ委員","kind":"意見","question":"同様に、この土地をああいうふうに使ってほしいということが出てきたときに、いや、それは行政需要によって、この請願で縛られるわけにはいかないからという理由では、なかなか採択以外の結果を出すことが、今採択してしまうとちょっと難しくなるのかと思うのですが、それについては皆さんどうお考えなのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"あくつ副委員長","kind":"質問","question":"ですから、では、空き家を取得するということが、全てこれからオーケーになるのかというと、そういうことでもないと思いますし、今回の件に関して判断を、ごめんなさいね、正反対な答えで申し訳ないのですけれども、１つ１つのことに対して審議をして結論を出すということが重要だと思いますので、流れを変えるということにはならないのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"あべ委員","kind":"意見","question":"そういう考え方もあるなと受けとめはしますが、出てくる結論は個々であっても、そこに使うロジックというのは一定の同一性があることが議会の信頼につながる。１つのロジックに当てはめて、このケースだったら採択とか、このケースだったら趣旨採択とか、だから、そういう結論が変わってくるのはともかく、ロジックから毎回変えてしまうとちょっと難しい、それも私の意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"本多委員","kind":"意見","question":"請願に関する全ての人たちへ配慮して慎重にというのはすごくよくわかりますが、ただ、我々議会人は、請願に対して態度を表わさなければいけないと思いますので、そこは我々の役割だと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"中塚委員","kind":"意見","question":"確かに、今の土地の所有者の気持ちを思うと、ちょっと不快に思うのではないかというご指摘は聞いてなるほどなとは思いますけれども、一方で、やはりこれについて、これでいく、いかないということを決めるという役割もそうだなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"本多委員","kind":"質問・要望","question":"結論を本日出していただきたいと思います。態度については採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"あくつ副委員長","kind":"意見","question":"公明党は、本日、結論を出す。態度としては、採択。意見を１つだけ。まさにおっしゃるとおり、財産権の侵害、これはもう行わないのは当たり前の話で、これから先、区にこの意思をぶつけたとして、区がどういう判断をするのかというまた１つのハードルと言えばハードルがありますので、この議会の意思としては、地元の意思を反映させたほうがいいと、このように考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"中塚委員","kind":"意見","question":"結論を出すということで、態度についてですけれども、今日、率直な議論が出ていたのは、私も少し学ばされました。ただ、この請願に関して、ここに書かれているとおり、安全・衛生上の問題がある、若い世代の方々も利用できる交流の場が欲しい、そのためにこの土地を取得して活用してほしいと、書かれていることはそのとおりだと思いますので、態度としては採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"あべ委員","kind":"質問・要望","question":"先ほどからも繰り返し申し上げましたけれども、やはり所有者の方の意思をあくまでも尊重していくということと、こういった交渉事は順番というものがとても大切なので、そういったことをぜひ考えていただきたいとともに、もしこれを取得するということになっても、やはり何をつくるかということについては、改めて地域の方やその他の行政需要、あるいはそのときの政策なども勘案しながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"須貝委員","kind":"質問","question":"先ほどお話ししたとおり、個人の財産ということにかかわる問題ですから、私は反対いたします。結論を出すということと、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"吉田委員","kind":"質問","question":"私は、やっぱり継続を主張したいと思います。私もこの趣旨を生かしたいので、ですから、いろいろなその都度の判断ということではありますけれども、これから請願権を認める上でも、あまりいろいろな論理があちこちしないような、こういう形で請願を出せば、きちんとした採択がされるという形であってほしい。きれいにこの趣旨が通るような形にするためには、継続を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"吉田委員","kind":"質問","question":"あくまで継続を主張したいと思いますので、そうすると、席を外す形ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"吉田委員","kind":"質問","question":"そうですか。反対という結論になってしまうのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"吉田委員","kind":"質問","question":"そういうことですか。退室すると、どういうことに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"吉田委員","kind":"質問","question":"そうですか。いや、本当に趣旨はちゃんと通したいので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"}]},{"id":"topic-06","title":"平成２７年請願第２９号 所得税法第５６条廃止の意見書提出を求める請願","agenda":"平成２７年請願第２９号 所得税法第５６条廃止の意見書提出を求める請願","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"ぜひとも家族だから、配偶者だから、息子だから、そういうふうに取り決めが行われるのではないかと、その前提そのものを、やっぱり間違っているのではないかということが１点伺いたいのと、前回このことを伺ったときに、最高裁判所の判例があったとの説明がありましたけれども、それがいつどんな判例だったのか、その中身も伺いたいと思います。","respondent":"黒田税務課長","answer":"家族だから必要経費に参入しないということではございませんで、現行制度でも、先ほどご説明いたしましたが、青色申告をしていただければ、適正な範囲で家族に支払う給与については全額必要経費と認めるという制度になっているものです。","id":"exchange-079"},{"speaker":"中塚委員","kind":"質問・要望","question":"私、特典としてつけるものではなくて、働いたものとして受け取るというのは、家族であっても、息子であっても、人格を持っているわけですから、ですからこの第５６条は間違っていると私は思うのです。特典によって家族の労賃を認めるものではなくて、そもそも働いた分を払うのだと、ここをしっかりと考えを変えていただきたいと思うのですけれども、改めていかがでしょうか。","respondent":"黒田税務課長","answer":"白色申告、青色申告というのは、所得税の申告納税制度でありますので、個人の選択で、青色申告は一定程度の帳簿記載の義務、正規の会計、基本的には複式簿記で会計をつけるということが原則となっていまして。","id":"exchange-080"},{"speaker":"中塚委員","kind":"質問","question":"まとめますけれども、要するに、特典で配偶者や家族の給与を認めるというのがおかしいでしょうと、そもそも家族であっても、また家族ではない従業員であっても、働いた分は必要経費でしょうと、そこを伺っているのです。なので、改めて伺いたいと思います。それを認めずに、特例規定として後から認める、この仕組みそのものが私はおかしいと思いますけれども、改めていかがでしょうか。","respondent":"黒田税務課長","answer":"繰り返しになりますが、申告制度自体は、白色、青色ありまして、家族に給与を支払っている方は青色申告により申告いただければ、その全額が適正の範囲で必要経費として認めるというような税制度になっているものです。","id":"exchange-081"},{"speaker":"須貝委員","kind":"質問・要望","question":"１人、２人で営業をされている、本当に小さな商店、工場もそうなのですが、やはり皆さん、きちんと帳簿をつけて青色申告をされている。その方法もきちんと優しく教えてくれて、それによって家族従業員の自家労賃も経費として参入されて、多くの方がこういう手法によって、きちんと帳簿をつけて、そして当たり前のように経費として参入されるように、やはり日々の営業活動、商売をされているわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"吉田委員","kind":"質問","question":"質問なのですけれども、さっき、最近は白色でも記帳が義務づけられているということで、その辺の義務を果たすという意味では、青も白も段々同じようになっていると聞いているのですが、記帳の方法が簡便であるというようなご説明だったと思うのですが、どの程度、それによって違いというか、どう違うのでしょうか。","respondent":"黒田税務課長","answer":"青色申告ですと、基本的には取り引きごとに記録するということが複式での考え方ですので、それよりはやや簡便な方法ですが、記帳義務があるということにつきましては、平成２６年度から義務づけられているものです。","id":"exchange-083"},{"speaker":"吉田委員","kind":"質問","question":"では簡便というのは、単式出納帳ということなのですか。それとも、複式だけれども、少し簡単なやり方ということなのでしょうか。","respondent":"黒田税務課長","answer":"基本的に白色申告で求められていますのは、完全な複式簿記ではなくて、現金出納帳ですとか、いわゆる取り引きが、１つ１つでなくても、日ごとでわかるようになっていればよろしいかと思いますが、青色申告の場合につきましては、基本的に現金出納帳ですとか、売掛帳ですとか。","id":"exchange-084"},{"speaker":"あべ委員","kind":"質問","question":"今、品川区内の事業者で、青色の事業者と白色の事業者はどのくらいの割合なのか、手元でわかりますでしょうか。品川区としては、これ、税法上は青色に切り替えることを推進しているような構図になっているかと思うのですが、品川区としては、青色申告を積極的に進めていくというか、切り替えていくような何か努力をされているのでしょうか。","respondent":"黒田税務課長","answer":"青色申告者数ですが、平成２７年度の住民税の課税のためにご申告いただいた平成２６年分の所得税の申告書の数ですが、青色申告である納税義務者数は１万９,２４１人、そのうち青色事業専従者を有する納税義務者は２,０００人ということでございまして。","id":"exchange-085"},{"speaker":"本多委員","kind":"質問・要望","question":"本日、結論を出していただきたいと思います。態度につきましては、不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"あくつ副委員長","kind":"意見","question":"本日、結論を出す。意見を述べて態度を示します。ただし、先ほどご答弁の中にありましたけれども、所得税法第５６条の規定は、租税回避防止ということで、これは裁判所の判決上も妥当性、否定はされていないというところと、特例規定で第５７条も活用されているということもありますので、第５６条を廃止すべきだという考え方には、にわかに賛成ができませんので、不採択という立場です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"},{"speaker":"中塚委員","kind":"意見","question":"今日、結論を出すということと、態度としては、採択。一言理由を述べたいと思います。配偶者や家族であっても労賃は、特例の規定ではなくて初めから認めるべきものだと思います。働いた分を必要経費として認めるのは当然であり、それを特例として認めるということ自体がおかしいと、その方の人格を否定するものにつながってくると思いますので、採択ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-088"},{"speaker":"あべ委員","kind":"意見","question":"確かに、今、白色の申告をされている方々にとっては、なぜという思いが出てくるだろうということもありますが、実態として、今、青色申告が事業者の中で主流になってきているということ、むしろこの第５７条の規定がある以上は、ぜひ積極的に家族従業者の方の給与を認めるという形に今の制度の中で持っていっていただくという方向が、法の中でも望まれている流れではないかというふうに考えます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-089"},{"speaker":"吉田委員","kind":"質問","question":"そこで特にすごい負荷があるというふうにも考えていないということなのですが、やはり実態として、家族という理由だけで労働として認められないというようなことは、やっぱり時代の考え方としてもどうなのかというふうに思います。青色申告のほうを推進したいのだという税理士の方も、でも、別にこの第５６条がそういうことであれば、なくてもいいというか、そういうほうにはなってきているということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"}]},{"id":"topic-07","title":"その他の(2)その他を行います。 まず、今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、総務委員会に係る項目","agenda":"その他の(2)その他を行います。 まず、今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、総務委員会に係る項目","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"１点だけ。選挙管理委員会、今回の一般質問で出ていましたが、いろいろ選挙中でも違反と思われるような活動や行動があったときに選挙管理委員会に連絡をすると、それは警察に通報してくださいというような返事を受けたそうです。それだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/332522?Template=document&Id=2032#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":58523,"voices":229}},{"id":"h27-20151130-10","meetingId":"h27-cm11","date":"2015年11月30日","dateIso":"2015-11-30","committee":"議会運営委員会","time":"午後 ０時３０分～午後 ０時３５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","topics":[{"id":"topic-01","title":"平成２７年第４回定例会","agenda":"平成２７年第４回定例会","exchanges":[{"speaker":"須貝委員","kind":"提案","question":"今回、給与改正１０年提案がなされたわけですが、我々、町の中を歩いてみますと、品川区内の産業の中核を成します中小零細企業、商店、工場、それから、非正規雇用が溢れている中で、かなりの区民が大変な時期にあって給料も上がっていない、ボーナスも出ていないという状況を聞きますと、今回の議案に関しましては賛成できない、この辺を明確に態度表明とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/825100?Template=document&Id=5162#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":1407,"voices":11}},{"id":"h27-20151201-6","meetingId":"h27-cm12","date":"2015年12月1日","dateIso":"2015-12-01","committee":"区民委員会","time":"午前１０時００分～午後 １時２５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","topics":[{"id":"topic-01","title":"外国人おもてなし語学ボランティア育成講座","agenda":"外国人おもてなし語学ボランティア育成講座","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"この実施内容の(1)の一番最後の受講修了者等ということなのですけれども、この「等」というのは、ほかにどういう方のことを差しているのかと、それから、参加人数で、８０名応募というふうに言われたのですけれども、その募集の仕方はどういうふうになっているのか、聞き落としてしまったのかわからないのですけれども、教えていただきたいと思います。","respondent":"河内協働・国際担当課長","answer":"これは従前の個人情報の取扱い等も含めまして、新たに同意を得るためでございまして、今後につきましては、チラシなど、広報など、さまざまなものを通じまして、一般公募する場合には募集してまいりたいという考えです。","id":"exchange-001"},{"speaker":"南委員","kind":"意見","question":"こういうオリンピック・パラリンピックに向けてこういう事業を展開することは、それはそれとして受けとめていきたいと思っているし、いろいろな形で外国人の方、あるいは日本人同士、品川区民同士がコミュニケーションをとって、英語を媒介にしてとか、することは、まちづくりにとってもいいことだと思うのですけれども、だから、できるだけそういう事業に協力していただける方が増えれば。","respondent":"河内協働・国際担当課長","answer":"今後につきましては、６０名という定員は都からの講師を活用するという意味で、これは都の修了証をいただくという意味で登録の必要なスキームですので避けては通れないのですが、回数などにつきまして、今後、検討していきたいと考えています。","id":"exchange-002"},{"speaker":"藤原委員","kind":"確認","question":"確認なのですけれども、なぜ外国人おもてなし語学という形でやって英語だったのですか。確認です。東南アジアという意味で考えるならばという思いがあったので、なぜ英語だったのですかということが１点。それと、外国人に対するおもてなしの心を身につけるということですけれども、基本的な質問で、今までも日本人の心、おもてなしの心は、こういう講座をしなければ外国には通用しないのでしょうか。","respondent":"河内協働・国際担当課長","answer":"それから３つ目の国別ですが、もちろん世界各国からたくさんの方、例えばバルセロナオリンピックでありますと、１６９カ国と聞いておりますが、全ての国に対して対応することはなかなか困難です。","id":"exchange-003"},{"speaker":"藤原委員","kind":"質問・要望","question":"確認させていただいて、私もいろいろな考え方があると思うのですけれども、日本人のよさ、外国から見て上位に上がるのが、日本の安全で安心というところがよく出るではないですか。","respondent":"河内協働・国際担当課長、小川オリンピック・パラリンピック準備課長","answer":"ただいまご報告申し上げました外国人おもてなし語学ボランティアの育成講座につきましても、何人、何年度に育成が必要だというあたりも、準備課長とお話し合いの上、連携をして考えたところで、たまたま都との連携事業も参りまして。こちらの外国人おもてなし語学ボランティアなのですけれども、これはそもそも東京都が先行して昨年度より実施している事業でございまして、そちらにつきまして、ある程度の英語のスキルを満たした人たちに。","id":"exchange-004"},{"speaker":"松永委員","kind":"質問","question":"私は、都との連携で、品川区はどのくらいの予算を使われる予定なのかお伺いしたいと思います。講師派遣等というのも、都から派遣されるようですけれども、授業内容というか、例えば学校、スクール形式の講師が１人で６０人バッとやるのか、その内容を詳しくご回答を。","respondent":"河内協働・国際担当課長","answer":"そういった講座を行いまして、おもてなしのボランティアにつきまして育成を図るという内容です。","id":"exchange-005"},{"speaker":"松永委員","kind":"質問","question":"ホームページを見たら、もう講座の募集をやっていないみたいなのですけれども、受けないとだめだというのか、例えば、ある程度の英語力があれば誰でも受けられるように今後なっていくのか、その辺を伺いたいと思います。","respondent":"河内協働・国際担当課長","answer":"この都の主催の講座につきましては、２つのコースに分かれております。は英語力が基本的にある方につきましては、おもてなし講習、今回、私ども区が連携するものになります。","id":"exchange-006"},{"speaker":"たけうち委員","kind":"質問","question":"先ほど、修了した後に修了証を発行とのことなのですけれども、これ、修了された後の受講された方たちの活用と言ったら失礼なのですが、修了証をもらうだけなのか、何か登録とかをされて、例えば、オリンピック・パラリンピックが近くなったときに何かお声かけがあって、「ボランティア、どうですか」とかというふうにやるのか、その枠組みというのですか、取組みがあるのかどうかということが１つ。","respondent":"河内協働・国際担当課長","answer":"それから２点目、今後の区の取組みです。区といたしましては、今、都と連携ですが、同様な育成の取組みにつきまして、今後、取り組んでいきたいというような考えでおるところです。","id":"exchange-007"},{"speaker":"渡部副委員長","kind":"質問","question":"今、たけうち委員が伺ったようなところで聞きたかったところがあって、都との連携事業ということは、この事業自体が品川区だけで行われているものではないと認識するのですけれども、実際その辺はどうなのか。そうしますと、それなりの人数が出てきて、修了証も出て、その後、登録をされてということであれば、その２０２０年に向けて何らかのいわゆる資格ではないにせよ、そういうものを個人の方が持たれる。","respondent":"河内協働・国際担当課長","answer":"今後の予定ですが、当然ですが、お若い方、４年後、５年後になると思いますが、そのようなときに脂の乗った時期ではないのですが、同じ年齢層について手助けできるようにということで、そういった方にもお声かけさせていただいて。","id":"exchange-008"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"冒頭に南委員からの質問で、品川区国際友好協会云々かんぬん、修了者等という話がありましたけれども、幅広くやっていただきたい。門は開いておいてあげてほしいなと。３万５,０００人養成される。ということは、それで参加したいという方がなるべく、ある程度の定員等も必要かもしれませんけれども、何か門戸を開いてできるような仕組みを区としてつくっていただければと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"道案内等の手助けをするボランティアの育成講座ということで、福祉的な手助けに対しての講座も開かれているのでしょうか。障害を持った外国の方に対しての対応とかもこの中にも含まれているのかということを質問させてください。","respondent":"河内協働・国際担当課長","answer":"助けられないところは人を呼んでくるなりする。そのところで日本人の親切なところをあらわすというような趣旨でございまして、福祉的な専門的なところではないかもしれませんけれども、そういった側面が出てきたら、当然ながらやっていくような形を想定している講座です。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"そういった場合のロールプレイングもなさっているということでよろしいですか。","respondent":"河内協働・国際担当課長","answer":"ロールプレイングの内容につきましては、詳細についてまだ完全に把握しきっている状況ではありませんので、そのロールプレイングで出てくるかどうかは、申し訳ございません、まだ正確に把握はしておりませんが、趣旨的にはそのようなところを。","id":"exchange-011"}]},{"id":"topic-02","title":"「マスコット防犯ＰＲ活動事業」協定書調印式","agenda":"「マスコット防犯ＰＲ活動事業」協定書調印式","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"それとも協定される方が違うので、毎年やられるのかどうかということと、あと、ある意味で、品川区の安全安心をＰＲしていくということがねらいかもしれないのですが、そうすると、ここの協定書の調印のところに、いわゆるマスコミとかもお声をかけてどんどん来て取り上げてもらおうということが１つ大事なところかと思うのですが、ただ、区長とマスコットだけでこれをやっていてもあれなので。","respondent":"濱田生活安全担当課長","answer":"マスコミ等にもそのとき広報しております。今回行うのはマスコット。昨年、日程等が折り合いがつかずに今年になったということになります。この日は、マスコミ等に広報広聴課を通じて声をかけしています。そういう予定です。","id":"exchange-012"},{"speaker":"たけうち委員","kind":"意見","question":"わかりました。今、去年の７事業者を聞いたら、それぞれ個別にいろいろなホームページ等で出ていたものが記憶にあったので、非常にすごい取組みだなと思います。そうすると、今年については、事業者ではなくて、マスコットのみという形で考えているということですね。では、ぜひ期待していますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"済みません。では、質問を変えて、ちょっとストレートな質問になってしまうかもしれないのですけれども、課長が警察手帳も置いて、品川区のために私は来たのですと決意をこの間いただきましたけれども、前職は渋谷警察署の生活安全の課長をしていたとご紹介いただきましたけれども、前職のキャリアも含めて、このマスコット、こういう形でやることが、効果があるというふうに思っていますか。","respondent":"濱田生活安全担当課長","answer":"まち、いわゆる商店とか町会等、ここでコラボすることによって、商店と町会等の活性化等にもつながると私は考えております。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"課長がそこまで自信を持って言う施策ならば、私もやってよかったなと思いますけれども、これが地域との連携、地域の活性化と商店街の活性化にもつながるのだということは、まさに三位一体でやっていくということだと思うのですけれども、そこに出たので、地活の課長、商店街担当の課長、これをどういうふうに、いい意味で活用していくかということをお伺いしたいのと、もう１つは、私はこのキャラ。","respondent":"堀越地域振興部長、濱田生活安全担当課長","answer":"一般家庭に逃げ込んでおいでというふうな事業がありますけれども、それのマスコット表示にはしなぼうを使ったりとか、かなり児童、それから親御さんをはじめ浸透してきているという部分もありますので、こういった啓発を図って。それと、やはり今回のように防犯のマスコットをいわゆるコラボしていろいろ活用することによって、いろいろな各防犯活動等にも効果を発揮されておりますので、戻った際には、こういった施策はいい施策だということで。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"最後に、お二人の答弁を伺って、まさに夢から防犯みたいな形で、美しい施策と思ったのですけれども、ちょっと現実になってお金のことなのですけれども、このマスコットにお金的な契約という部分はどうなっているのでしょうか。いわゆる契約ですから、これはボランティアなのか、それとも１マスコットに幾らお支払いするのか、その辺の予算を教えてください。","respondent":"濱田生活安全担当課長","answer":"現在、相互扶助の関係ということで、予算等はここには何もつけてございません。","id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"このマスコットが、今回は１１あるということなのですが、そのほかにもいろいろあると思うのです。そういった今後の予定について、また来年もまだ登録というか、認定されていないマスコットについても、また随時こうやって、こういうものをやりますというような案内で増やしていく予定はあるのかお伺いしたいと思います。","respondent":"濱田生活安全担当課長","answer":"今回、１１団体が所有する１４のマスコットということで、実は、私の課のほうで調べまして、今回、品川区管内で活動するマスコット全部に声をかけさせていただきました。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"目的のところに書かれている「体感治安」という表現は、私は初めてだったので、どういうことなのかを教えていただきたいのと、あと、先ほどのご答弁の中で、昨年度は７事業者と２６とおっしゃった、その２６が何だったのかを改めて確認したいのですけれども。","respondent":"濱田生活安全担当課長","answer":"そういったことです。都民が感じる犯罪に遭う可能性とか、そういったものと理解していただければと思います。それと、２６の数字は、平成２６年度です。平成２６年度は７事業者ということです。","id":"exchange-018"}]},{"id":"topic-03","title":"マイナンバー「通知カード」の送付等","agenda":"マイナンバー「通知カード」の送付等","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それと、今、時期が時期で、１２月になりましたから、年内に引越ししようとか、転入しようとか、今までの通常時期よりもそういう通常の業務がさらに増える、あるいは、これから来年に行けば、年度末で学校に行くだとか、いろいろなことで住民票の異動とかもあると思うので、そういう業務量に耐えられるような体制をとっていただかないといけないと思うので、その辺についてどうなのかを伺いたいと思います。","respondent":"井浦戸籍住民課長","answer":"各課につきましても、１月以降、申請書に順次個人番号を書いていただくという形で始まってまいりますので、全庁の窓口におきましても、マイナンバー法に基づきまして、しっかりと取り扱う職員を登録いたしまして。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"交付予定が７％だったということなのですけれども、私の記憶違いだったということですけれども、これは今の状況を見ると、来年以降についてはまだ始まったばかりですからあれですけれども、どんなふうに予想されるのか、多くなると予想されるならそれなりの体制も必要だと思いますし、その辺、どういうふうに考えておられるかを１点知りたいと思いました。","respondent":"井浦戸籍住民課長","answer":"交付の体制としては、１日３００件を交付するという体制を構築していますので、一方で予約の仕組みを用意いたしますので、１日３００件という対応のキャパシティの範囲内で交付を行っていくというふうに考えてありますので。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"くれぐれも区民の方々に十分な理解も得られないまま進めてきたという、そういうところがあって、その状況をつくる品川区の職員の皆さんは本当に大変なのだろうというふうに思うので、そもそもの国のそういう強引なやり方に、私は冗談ではないと思うわけですけれども、走ってしまったわけですから、くれぐれも遺漏のないようにしていただきたいということを改めて言っておきたいのと、職員の実情についても。","respondent":"井浦戸籍住民課長","answer":"通知カードの対応につきましても、１２月１日から委託での窓口対応ということも導入しまして、順次、来客状況も見ながら、委託を活用しながら、職員のしっかりとした対応体制、窓口体制をつくっていくというふうに考えてあります。","id":"exchange-021"},{"speaker":"南委員","kind":"確認","question":"委託ということは、当然正規の職員ではないわけですね。そうすると、この窓口での仕事の中身そのものがどこまで個人情報に触れるかは全然見えないのであれなのですけれども、だからこそ質問するのですけれども、個人番号がわかるような、そういう仕事内容になっているのですか。安心感というところも含めて、やはり区のしっかりした、何のための取扱者登録なのかと思うので、その点について確認したいです。","respondent":"井浦戸籍住民課長","answer":"民間事業者による委託の部分につきましても、法律で規定されておりまして、職員と同様の守秘義務のもとに適正に取り扱っているところです。","id":"exchange-022"},{"speaker":"南委員","kind":"意見","question":"職員と同様ということは、だから、マイナンバーに触れるわけで、私はこれは個人情報セキュリティを守るというふうに言いながら、そうではないのではないかというふうにすごく実感してけしからぬことだと思います。その点だけ言って終わりにします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"たけうち委員","kind":"確認","question":"今、南委員とかぶるところからお聞きしますと、受取拒否への対応で、では、これ、特別、待ちという形で、来たときに必要に応じて、カードの番号がないと申請等できないわけだから、そのときに渡す、ここで説得して再交付する。いわゆる区なり国の関係者が出向いていって説得するとか、そういうことはないということが１つ確認です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"たけうち委員","kind":"質問","question":"６００円。そういうところで言うと、さっき、南委員とのやりとりで、今回、７％の予算措置だと。それで、来年度以降はまだ見えてこないわけですけれども、１００％をやるには、日本全国ですから、国としてもかなの予算がかかる中で、結構な時間がかかってしまうと思うのです。この３点。","respondent":"井浦戸籍住民課長","answer":"２点目の証明撮影機です。現在、本日からマイナンバー申請用の写真機を設置しています。既存の一般証明写真用の撮影機との２００円の差ですが、１点は、お見込みのとおりです。マイナンバー申請機能ということで付加価値がついている部分があります。","id":"exchange-025"},{"speaker":"たけうち委員","kind":"質問","question":"最後のところで、気になるのが、今、課長がおっしゃった現在無料とおっしゃったのだけれども、これ、区の予算措置ではないので、先々国がどこまで予算、今は無料ですけれども、先々もしかして何年後かには有料とかということも可能性としてはあるというふうに含んでおいたほうがいいのか、それはあまり我々も立場上、無責任なことは区民に聞かれたときに言えないのですけれども、そういうことがあると、では。","respondent":"井浦戸籍住民課長","answer":"委員がご指摘のとおり、国の予算措置の中ですので、国からは、将来的なものについては示されてございませんが、国が説明で標準的にＱ＆Ａで申し上げているところにつきましては、現在、無料ですので、どうぞ申請なさってくださいというスタンスです。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"３点ほど。誤配達で、いずれも未開封だったそうですが、もしこれが開封されてしまっていた場合はどうなるのかということと、あと、ＤＶ被害者に対しての対応、現状などを教えていただきたいことと、あと、民間事業委託業者に窓口で対応してもらうとのことなのですが、このときもＤＶ被害加害者の情報はどう対応していくのでしょうか。","respondent":"井浦戸籍住民課長","answer":"誤配達で万一開封された場合ですが、他区で例がありますが、番号の変更の申請をご案内いたしまして、番号変更という形で対応するということで考えてあります。","id":"exchange-027"},{"speaker":"田中委員","kind":"確認","question":"確認なのですけれども、委託業者の方は、ＤＶ被害者、加害者の方がみえられた場合とか、そういう関係の場合には対応しないということですか。ＤＶ担当の方が担当する。","respondent":"井浦戸籍住民課長","answer":"法律的には、民間委託の方でも対応は事務的にできますが、品川区としましては、ＤＶの専属班がお聞きする、橋渡しをしていただくということで考えてあります。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"数字的には、１,２１９件あて所なしで戻ってきて、イコール１,２１９件の方は全員が引越しされているということで間違いなのでしょうか。","respondent":"井浦戸籍住民課長","answer":"そのとおりです。１,２１９件すべてについて、新しい住所地について国に住所情報を送付しまして、改めて国から通知カードが送られることになってあります。","id":"exchange-029"},{"speaker":"松永委員","kind":"質問・要望","question":"確認をさせていただきたいのですけれども、第二庁舎の臨時交付窓口という開設で、これはいつまでやられるのか。終わった後、これは戸籍住民課の窓口へ戻るのかということと、あと、時間です、何時から何時までやられて、休日等もやっていくのかどうかということを教えてください。確認だけさせてください。","respondent":"井浦戸籍住民課長","answer":"臨時交付窓口ですが、平成２８年１月から３月末まで開設いたしまして、４月以降につきましては、現在、開設する方向で予算当局に提案しています。開設時間につきましては、区の営業時間と同じでございまして、８時半から１７時１５分、日曜日も開設する予定です。","id":"exchange-030"}]},{"id":"topic-04","title":"都市型観光プランの策定","agenda":"都市型観光プランの策定","exchanges":[{"speaker":"田中委員","kind":"質問","question":"３枚目の２－３、今後のしながわ観光の課題に書かれている区民による“もてなし力”の向上のおもてなし力について具体的に教えてください。","respondent":"間部文化観光課長","answer":"したがいまして、会話を上手にやってご案内をするというのもおもてなしですし、例えばストレスなく観光ができるように、両替所があったりだとか、免税の一括カウンターも含めてですけれども、外国人の方であれば、そういうような環境が整っているようなことを認識しています。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問","question":"今の一括のものだとものではないですか。ここに書かれているのは区民による“もてなし力”の向上なので、区民がやるもてなし力とは一体何なのかということを教えてください。","respondent":"間部文化観光課長","answer":"例えば、家の近くに、品川神社のそばに住んでいれば、品川神社のご紹介をするのも、ここでは６月にお祭りがありますよというご案内とともに、この裏側には板垣退助のお墓がありますとか、例えば、ここに関連して、立会川のほうにまで行かれれば、龍馬の砲台がありますよとか。","id":"exchange-032"},{"speaker":"たけうち委員","kind":"質問","question":"例えば、最初はもしかしたら、スカイツリーだとか、雷門だという名所を当然、我々も外国へ行くとなると、そういうところに行くわけですけれども、ただ、何回か行っているうちに、その国の文化に触れるというのは、もちろんそういう代表的なスポットもそうなのだけれども、やはりそこで生きていらっしゃる方の、おもてなしにもつながるかもしれないですけれども、息づかいだとか。","respondent":"間部文化観光課長","answer":"外国人の目線での検討ということだと思いますけれども、今、専門部会、検討委員会を含めて、例えばＪＴＢの外国旅行に携わっている方ですとか、例えば東京モノレールとか京浜急行、これもインバウンド関係に携わっている方が入っていただいております。","id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。今後の要望ですけれども、この間、山北町へ行ったときにも、山北町の担当者がおっしゃっていたと思うのです。外国の方をあれして山北町を見てもらっているとたしか言っていたと思うので、非常にいい取組みだなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"なかなか観光は難しいとずっと思いながら資料を読ませていただいたのですけれども、先ほどの説明の中で、事務局的には品川区の部署と観光協会とプランニングネットワークというここの三者が持ち寄ってしている、具体的にプランニングされているということなのですけれども、先ほど、品川区としては情報を発信するというか、そういうことがメーンの仕事になるのではないかというふうにお話しされていて。","respondent":"間部文化観光課長","answer":"パンフレットにつきましては、今いろいろなパンフレット、日、英、中、韓、４カ国語でつくっていますけれども、先日、補正でも認めていただきましたけれども、タイ語についてつくり始めたということがありますので、今後も観光客の動向を見ながら。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問・要望","question":"京都でも地元の方、住んでいる方がメーンなのですみたいなことがすごく印象的にあって、そういう意味で質問させていただきたいのですけれども、課長のさっきの説明の中で、私もそのとおりだと思うのですけれども、品川区はまず商店街です。と出ていたのですけれども、この都市観光と人口増加、住んでいる方の増加をどういうふうに考えているか、まず教えていただけますか。","respondent":"間部文化観光課長","answer":"都市型観光と人口の件ですけれども、やはり品川区に魅力があるから人口が増えている、これは１つあると思います。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問・要望","question":"人口が増加して、私もうれしいです。所管ではそう。言葉はきれいにレガシーと言うではないですかか。ただ、レガシーという言葉だけで、そこも心配なのですけれども、担当の課長として、確かにオリンピック・パラリンピックは大切ですけれども、それ以降の都市型観光も含めて、このプラン策定には入れていただきたいと思う、その後を、さっきおっしゃっていたけれども、その辺についてお伺いさせてください。","respondent":"間部文化観光課長","answer":"ですから、建物だけのレガシーではなくて、人的な部分だとか、気持ちだとか、そういった部分も含めて観光という観点ではレガシーと捉えて活用していきたい、このように考えてあります。","id":"exchange-037"},{"speaker":"渡辺委員","kind":"提案","question":"すばらしい。ですから、その辺はもちろん謙虚で、区民が主役、地域の方が主役ということはありながらも、やはり縁の下の力持ちであり、責任を負うという点で、行政のリーダーシップ、そういう捉え方ができるかと思いますので、その辺の考え方、責任だとか、リーダーシップのところでの見解も大前提として地域の方が主役であるという点から確認をさせていただきたいと思います。ここは決意でいいと思います。","respondent":"間部文化観光課長","answer":"こういう何かをやるときに、今回もそうですけれども、水辺があったり、歴史的な部分があったり、商店街があったときに、優先順位をつけたりだとか、いろいろなところでやっていかなければいけないわけで、そういった意味では、当然、地域の方が主体ですけれども。","id":"exchange-038"},{"speaker":"渡辺委員","kind":"質問","question":"今、行政の役割と理念のところを伺いました。策定委員会も含めて。品川区にとってメリットがあるとすれば、広域連携を活用して、ある部分は譲るし、あるものは得るものが大きいような気がしているので、ちょっと抽象的になってしまいますが、この辺のご決意だけ最後に、行政がリーダーシップかなという思いがあったので伺わせてください。","respondent":"間部文化観光課長","answer":"いろいろな形で広域連携を図っていくことが活発化の機運を高める上でも重要だと思っていますので、できる限りの連携はしていきたいと思います。","id":"exchange-039"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"これについては、各委員、今、ご質疑がありまして、委員長とも相談はしていたのですが、この第３回検討会に向けまして、早急に私たち区民委員会のメンバーにも素案を提出いただけますでしょうかという要望と、あと、スケジュールをこの先を見ますと、パブリックコメントも１月１１日からやりますので、閉会中の審査の前にパブリックコメントが出ると思いますので、先に目を通したいという要望がありますので。","respondent":"間部文化観光課長","answer":"今、委員からお話がありました閉会中の対応につきましては、正副と協議して決めていきたいと思います。","id":"exchange-040"}]},{"id":"topic-05","title":"しながわみやげコンペティション","agenda":"しながわみやげコンペティション","exchanges":[{"speaker":"南委員","kind":"意見","question":"全区的にエントリーされたのだろうと思うのですけれども、たまたま選ばれたのがこういうところなのかとも思っているのですけれども、その辺、どういうふうに見たらいいのか、あったらお話しください。","respondent":"間部文化観光課長","answer":"一部、武蔵小山のパルムの刻印のものとかもあるのですけれども、どうしても自薦、他薦ということで、自らというよりは、ガイドの推薦などがかなり今回は多かったということで、ちょっと偏りがあったのかなと思います。","id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"あるいは、そのために新たな開発をして出されたのか、そのあたりのこととか、独自に開発するとなったら、それぞれのお店の事業所の経費でいろいろな食材を入手してやるのだろうと思うのですけれども、ごめんなさい、私もあまりコンペティションについての認識がなかったので、大変恐縮なのですけれども、初歩的なところを教えていただきたいのですが。","respondent":"間部文化観光課長","answer":"今回、多くの審査員、１４人ほど審査員がいたのですが、全てで１位ということで、私も試食をさせていただいたのですが、非常に味もよく、かなりいいなという形でありました。ぜひ委員の皆さんも試食をしていただければいいと思います。今後についても、地区別のこういうまち歩きマップがあるのですが、例えばこういうところにマップが出ているのですけれども、ここに来たらこんなおみやげかあるというような取り上げ方を私たちもしていこうと思っていますので。","id":"exchange-042"},{"speaker":"たけうち委員","kind":"質問","question":"例えば、最優秀ですとか、また、最優秀ではないけれども、入賞されたような方たちが、自分の商品に、品川区のおみやげの認定品の最優秀ですとか、そういうふうにして販売することについてはオーケーかどうかということと、それから、裏面のほうで、その他の(2)番で、次年度以降、新たな認定制度を設け引き続き発掘を行っていくとあるのですけれども、その新たな認定制度というのは、今のところもしあれば。","respondent":"間部文化観光課長","answer":"そうすると、毎年毎年減っていってしまいますので、ある程度、また来年度以降の、今考えている方法は、また自薦、他薦で観光協会のほうにお申し出をいただいて、一定の審査をもって掲載していくような形を考えているところです。","id":"exchange-043"},{"speaker":"たけうち委員","kind":"確認","question":"もう既に似たような感じで言えば、商品ではないのですけれども、マイスターというものもやっていて、本来であれば、行政とかはなかなか個々のお店にランク付けみたいになってしまうものというのはらないということが大原則であると思うのですけれども、区だけではなくて、ほかのところも絡んでやっているということと、また、自薦、他薦ということもあるので、非常にそれはいいことだと思うのですけれども。","respondent":"間部文化観光課長","answer":"やはり行政として各個店を応援するというのはなかなか難しいということで、観光協会を通じて、審査員の方も据えて、適正な手続をもって応援しているということでやっているところです。","id":"exchange-044"},{"speaker":"渡辺委員","kind":"質問","question":"もう質問にならないかもしれないですけれども、こういう取組みはすばらしいと思っています。マイスターにしろ、このコンペティションにしろ、波及効果がすごいと思うのです。観光などは特に。その辺は大胆にチャレンジ精神をもってされるべきと思いますので、決意だけ伺えればと思います。","respondent":"間部文化観光課長","answer":"このおみやげも含めて観光行政、やる気のある事業者を支援していくのはとても大事だと思いますので、そういう視点で今後とも一生懸命やっていきたいと思います。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/719578?Template=document&Id=2740#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":47615,"voices":126}},{"id":"h27-20151201-7","meetingId":"h27-cm12","date":"2015年12月1日","dateIso":"2015-12-01","committee":"厚生委員会","time":"午前１０時００分～午後 ０時１６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","topics":[{"id":"topic-01","title":"の(1)、（仮称）品川区立障害児者総合支援施設の建設","agenda":"の(1)、（仮称）品川区立障害児者総合支援施設の建設","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"この図面から、何点かお伺いしたいことがあるのですけれども、まず１点目が、最初の説明にありました、このレジュメの１の(2)、構造のところで、経費節減のため、ＲＣ造から鉄骨造にするということだったのですが、多分、資材が高騰しているとか、工期の問題があると思うのですが、ここだけなのですか。よく上に芝を植えたりするのですけれども、そういうことはないのか。","respondent":"中山障害者福祉課長","answer":"実際に設備の機械を集中させて、少しスペースができれば、そういうようなことも考えていきたいと思っていますが、途中階にバルコニーもありますので、そうしたところを、出られるようなスペースとして活用してまいりたいと思っています。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"太陽光や屋上を緑地化するなどは、時代の流れの中で、もちろん施設としては、用途としては障害児者の支援施設ではあるのですけれども、やはり地域の都市景観に合ったような建物になるように、しっかりやっていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"新妻委員","kind":"質問・要望","question":"前回から少しこの設計が変わったということで、この間、利用者、また各種団体の方への説明などもあったと思いますが、各種団体の方へのご説明がどのようにされてきたのかという流れと、今後、これがどのような形で利用者に説明がされていくのかということを、確認をさせていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"その後、ここに精神科のクリニックが入るということで、８月５日には品川区医師会のほうに、ご挨拶とあわせて、こういった施設ができますという説明をしております。それから、９月７日、地元の町会を対象とした説明会を行いました。","id":"exchange-003"},{"speaker":"新妻委員","kind":"質問・要望","question":"でき上がってくると、イメージも見えてきて、設計はこうだったけれども、実際はこういうふうにしたほうがいいという変化も出てくると思いますが、利用者にとって一番いい形でオープンさせていただきたいと思いますので、その都度やはり、この各種団体を含め、利用される障害のある方、またその保護者への説明を丁寧に行っていただきたいと思いますが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"１０月２８日に行いました説明会の中でも、もう少し設計が固まったら説明してほしいとか、運営上、どういう工夫をしていただけるのか、説明をしてほしいという声はございましたので、本日、こういう形で議会に報告させていただき、もう少し図面が確定し。","id":"exchange-004"},{"speaker":"のだて委員","kind":"提案","question":"前回の説明ですと、提案者も、４階に医療スペースをもってきて、障害者への目配りができるようにとか、いろいろ考えてやっていらっしゃったと思うのですけれども、その辺の考えなどがどういうふうに変わったのかということを、教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"この提案の中身を、もう一度、区のほうでも再整理させていただき、どうしてもボリューム的に増やしてもらわないといけないところがありました。例えば児童発達支援センターが、もう少しボリュームが必要だろうということになります。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"いろいろな議論の中で変わってきたということです。図面について、詳しくお聞きしたいのですけれども、以前、地階に防災備蓄倉庫があったのですが、今回の設計では見当たらないのですけれども、その辺がどうなったのか。それから、在宅介護支援センターというのは、お年寄り対象ということなのでしょうか。障害者も対象になっているのか、そこが疑問だったので、お聞かせいただければと思います。","respondent":"中山障害者福祉課長","answer":"障害者も、今後、６５歳以上になると、介護保険に移られる方もいらっしゃいますし、障害者の高齢化は一つ大きな課題となっております。同じスペースに入ることで、双方の連携が進んでいけばと考えているところです。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"３階で、個室とグループ部屋があるのですけれども、この階には、個室は何部屋あるのかの確認です。それから、グループ部屋というのは、いわゆる多床室ということになるのかの確認です。４階のスペースについても、居室と居室の間のスペースが空白になっているのですが、こういったところがどういったスペースになっているのか。設備とか、機械のスペースなのかもしれませんが、確認です。","respondent":"中山障害者福祉課長","answer":"倉庫であったり、いろいろな事務室であったりということで、こちらは主なところだけを載せさせていただいているので、抜けているところがあるということになりますけれども、全体的に、４階は行動障害の方の生活介護ということになりますので、ある程度集団で訓練をする場。","id":"exchange-007"},{"speaker":"のだて委員","kind":"確認","question":"主なところだけ書いてあるということですけれども、そうすると、個室と書いてある数だけ個室があると考えてよろしいのかという確認です。それから、６階に全体の管理事務所が置かれているのですけれども、全体を管理するうえで６階に持ってきたというところを、少しお聞かせいただければと思います。","respondent":"中山障害者福祉課長","answer":"どうしても建物の構造上、上にいくほど床面積が狭くなるということがありますので、そういった全体の調整の中で、６階に職員のリビングルームを移させていただいたところです。","id":"exchange-008"},{"speaker":"のだて委員","kind":"意見","question":"スケジュールですけれども、設計に時間がかかるということで、開設が平成３１年４月まで延びたということですけれども、当初の設計期間よりも、やはり障害者の綿密な設計をするために時間が延びたのか、もう少し詳しくお聞かせいただければと思います。","respondent":"中山障害者福祉課長","answer":"当初の予定では、今年度中に実施設計までできるのではないかと、こちらとしては考えていたところではあります。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"利用される方も、これだけ総合的に利用できるところが、地域の拠点としてできるということは、大変に喜んでいることだと思いますので、これ以上延びることがないように、できるだけ早く開設できるようにやっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"提案","question":"提案者と、施設の中身について十何回もいろいろ話をして、それが今の中身だと思うのですが、心配をすごくしているのは、あるところで、先日、約５０億円くらいのところがありました。それはなぜかというと、設計会社も同じようなことを思っていた。そうすると、行政側としては、提案者の方々と一生懸命話をされて、もちろん行政の越権行為になる可能性もあるわけですよ、設計事務所とやるのが。","respondent":"中山障害者福祉課長","answer":"先行きのことで、なかなか読み切れないところではあるのですが、そこは技術部門である施設整備課とも十分に相談させていただいて、とにかく平成３１年４月オープンがずれることがないように、精いっぱい努力していきたいと考えています。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問","question":"何点かお聞きします。マイナスな意味ではなくて、保護者がそういう心配をされているということなので、構造的にどうなっているのか、考え方だけお聞きしたいと思います。７団体も含めてさまざまな団体に入られていない方も、当然利用される。もう一つ、ここは海抜があまり高くないところですよね、２ｍないくらいですか。〔「２ｍはある」と呼ぶ者あり〕ありますか。","respondent":"中山障害者福祉課長","answer":"こちらの施設は、区立の障害者施設ということになりますので、いざ災害が起こったときには、こちらは福祉避難所や二次避難所的な対応をとることになると思います。こちらは上の層もあるので、場合によっては近所の方がそこに避難ということもあるかと思います。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"今回の法人、グローはアウトリーチ型の訪問が本当に最大の特徴で、今までは品川区になかった。２点目のお互いの理解については、今回、品川の水族館でアールブリュット展を、本当にご尽力いただいて、オリンピック・パラリンピック特別委員会でも見させていただきましたし、私たちは会派として全員で伺って、二度、見させていただきまして、説明も伺いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"の(2)、大崎高齢者多世代交流支援施設の運営事業者の公募","agenda":"の(2)、大崎高齢者多世代交流支援施設の運営事業者の公募","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"公募の対象になる事業者は、どういうものになるのか、お聞きしたいのですけれども、社会福祉法人のみなのか、あるいは、株式会社でもいいのかということです。それから、この間、こういった指定管理者の公募は、基本的に設計とかかわって決めてきたと思いますけれども、この施設については、そういった設計とのかかわり方はないのかという確認です。","respondent":"松山高齢者地域支援課長","answer":"２点目の、建設型、例えば指定管理者によるですが、こちちは、指定管理ではなくて、もう建設は進んでおりまして、一部のソフトの運営の業務内容につきまして運営事業者の公募を行いまして、そちらの公募で選定された事業者に委託をするものです。","id":"exchange-014"},{"speaker":"のだて委員","kind":"意見","question":"やはり公共施設で、株式会社がやっていくということになると、採算が取れなくなるとやめてしまうということになりますので、継続的なサービスを行っていくという意味では、株式会社にするというのはよくないと考えています。公募ですので、どこが応募してくるかわかりませんけれども、しっかりとサービスが継続できるように、株式会社は好ましくないという意見だけ言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"横山委員","kind":"提案","question":"１点だけ、お伺いします。運営事業者の業務内容のところですけれども、現在のシルバーセンターの業務以外の、高齢者を含む多世代交流に関する業務という部分ですけれども、区として、どのようなところに注目していかれるのか。具体的な提案は事業者からということがあると思いますけれども、区として、こういう形でやっていただきたいというところを、現時点で、どのようにお考えなのか、お聞かせください。","respondent":"松山高齢者地域支援課長","answer":"業務内容の、高齢者を含む多世代交流に関する業務ですけれども、区といたしましては、継続的に交流を行うようなイベントや講座を、例えば何回以上実施するというような形を委託してまいりたいと考えております。","id":"exchange-016"},{"speaker":"横山委員","kind":"意見","question":"区としての具体的なそういったサービスの回数ですとか、こういった形で、というお答えを、今、いただきました。区の考え方といいますか、多世代交流といっても幅が広い形があるかと思いますけれども、区の方針といいますか、こういった方向性というような、何か区の考え方、その辺の意味だったのですけれども、申しわけありません、もう一度お願いいたします。","respondent":"松山高齢者地域支援課長","answer":"平塚橋、大崎なり、地域の特性というものもありますので、それに合った多世代交流の仕方というものは、それぞれがつくっていくものだと考えております。","id":"exchange-017"},{"speaker":"横山委員","kind":"質問","question":"今、平塚橋の多世代交流支援施設のお話もございました。地域の特性に合わせてということで、平塚橋のほうは、子どもと高齢者が集えるようなオープンスペースなどのお話を、以前いただいたと思います。大崎に関しては、地域特性を、どのように捉えていらっしゃるのでしょうか。","respondent":"松山高齢者地域支援課長","answer":"大崎も、平塚橋と同様に、地域交流スペースは、当然設けております。平塚橋も大崎もそうですけれども、地域のご利用される団体の皆様のご意見をいただきながら、今後、つくっていくという形にしていきたいと考えています。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"提案","question":"そういうところも活用する。例えば健康センターにしても、何にしても、こういうスクールをやって、こういう人たちを集めて、親子で何かをするとか、いろいろなことをやっているけれども、ここでも、多世代でそういうイベントをやっていくとなると、参加費はこのくらいで、こういうことをやりたいと、プロポーザルでそういう提案まで求めているのか、どうなのかということを教えていただきたい。","respondent":"松山高齢者地域支援課長","answer":"こちらのほうとしては、参加費の具体的なところまでは、区としては求めてはおりませんが、基本的な条件や料金設定は区が考えるべきであるとして、委託なので、許可や利用条件は区のほうで考えていきたいと考えています。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"提案","question":"今までの歴史もあるから、近隣の学校のこともよくご存じでしょうから、行政があまり考えを持っていると、新たな交流のあり方、子どもだけではなくて、ご両親とか、そういう方々と高齢者とどういうふうにするのか、そういうことも、多分いろいろな提案があると思うので、ぜひやはり、そういうことも含めてやるくらいの感覚を持っていただくといいかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"}]},{"id":"topic-03","title":"本日は、地域包括ケアシステムのうち、医療と介護の連携","agenda":"本日は、地域包括ケアシステムのうち、医療と介護の連携","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"初歩的なところで、何点か確認をします。それから、品川区が今、認知症対策を進めている中で、患者が救急車で運ばれた際、病院のほうから高齢者福祉課に問い合わせをすると、ご本人の身元の確認できるというお話があったのですが、ここをもう少し詳しく教えていただければと思います。どういうシステムになっていて、情報がわかるのかという確認をさせていただきたいと思います、お願いいたします。","respondent":"川島健康課長、永尾高齢者福祉課長","answer":"患者情報の共有につきましては、今のところマイナンバーとは切り離して検討を進めております。品川区の特色である在宅介護支援システムということで、在宅介護支援センターのほうの相談内容と区のワーカーのほうの相談内容が全部つながっているというところから、迅速にその方の情報を把握することができるということで。","id":"exchange-021"},{"speaker":"横山委員","kind":"質問","question":"何点かお伺いします。先ほど、大田区と品川区の連携というお話があったのですけれども、例えば目黒区や、他区の病院に通われていらっしゃる方もいらっしゃいます。他区の連携の状況、現在、どうなっているのかお聞かせください。そちらからお願いします。","respondent":"川島健康課長","answer":"今は、目黒区や、例えば港区との連携は、まだなかなか進んでいないところですので、先ほど申しました救急医療の関係の連絡会、検討会の中では、そちらの病院をお呼びして、いろいろとご意見をお伺いしたという経過はあるのですが。","id":"exchange-022"},{"speaker":"横山委員","kind":"質問","question":"現在の状況をお知らせいただきまして、ありがとうございました。近隣区へのシステムの拡大というところは、これから検討されているということでお伺いいたしました。モデル実施の部分に関しましては、まずは品川区内でスタートされるということで、順次他区にも持ちかけていくということなのでしょうか。例えば東京都の動きとか、東京都からの近隣区の医療連携の支援とか、そういったところは何かありますか。","respondent":"川島健康課長","answer":"東京都のほうの指導というか、働きかけで、近隣区との連携が進むようなものが何かないかということですけれども、今のところ、具体的な固まりというか、くっつきが、大田区との関係でいろいろな会議体が集められたり、一堂に会していろいろな説明会などはあるのですが、現状は。","id":"exchange-023"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらは、要望だけします。次の質問に移らせていただきます。東京大学の辻教授が、千葉県柏市で多職種連携研修をやられているという記事を拝見いたしました。先ほど、説明の中にも、今、行われている会議体は少し大所帯過ぎるので、細かいところはワーキンググループで行っていきたいというご要望なども出ているというお話でしたけれども、その辺について、今後、どのようにお考えでしょうか。","respondent":"川島健康課長","answer":"ワーキンググループの必要性は、医師会の医者から出されていたものでして、さまざまな検討課題、既に独自にいろいろな機関のほうでも検討を始めていると聞いておりますので、まずは、医療系の情報をどうやって集めて、どうやって共有するかというところを、この検討部会の中。","id":"exchange-024"},{"speaker":"横山委員","kind":"質問・要望","question":"今、医師会のほうから、そういったご意見が出ているということでした。やはり医師の本業のほうの仕事になるべく集中していただきながら、情報は区のほうでなるべく事務局中心に、さまざまな多職種の方に見える化といいますか、情報提供していくというリーダーシップを発揮していただけたらと考えています。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、いろいろご説明いただきまして、少し出ていた部分もあると思いますけれども、現場の声や課題、もう少し詳しく語れるところあれば、教えていただきたいと思います。それとあわせて、区の考えている課題となっている部分、これも教えていただければと思います。","respondent":"川島健康課長","answer":"先ほども言いましたけれども、訪問診療をする医者からすれば、「訪問介護ステーションで２４時間対応をしているところ、それから薬局で２４時間対応をしているところはどこか知りたい」という話です。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろな課題が寄せられているということで、この会議体等でも、どうまとめていくかという話をされていると思いますけれども、しっかりと連携を取ってやっていっていただきたいと思います。患者情報共有システムの導入で、待ち時間が減るというお話があったのですけれども、これはどういう形で減っていくことになるのか、イメージができなかったので、ご説明いただければと思います。","respondent":"川島健康課長","answer":"例えば、ご自身も病院、診療所にかかられたとき、初診のときに、いろいろ聞き取りに時間がかかったりとか、待ち時間が多かったりすると思いますが、例えばご自身の情報を持って病院などにかかられたら、初診の時間が迅速に済むといった意味合いです。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"この間、医師会の方との懇談を行って、地域医療のシステムについて資料をいただきまして、その中で、急性期を脱した患者全てが在宅医療を行うことが最善策かということが書いてあるのですが、そういったところで、この会議体の中でどういったお話がされたかということ。それから、区が在宅医療全てを行っていくことがいいのかという、区の考えをお聞きしたいと思います。","respondent":"川島健康課長","answer":"在宅診療ありきというのが区の姿勢ということではなくて、現状、増えてきている中で、どう対処するかという課題の検討を、今、しているという認識です。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"また、その後に行く場所も、払える金額に合わせて、どういうところに行けるか決まってくるわけですけれども、それによっては、区内では無理で、遠い県外に行かざるを得ないという状況だというところが、相談の中には多いのです。現場の会議の中でも、そういう意見は出ているのかどうか、聞かせいただきたい。そこら辺のところについては、どう考えているのか。","respondent":"川島健康課長","answer":"お金のない方の行き場所の話になるのかと思いますけれども、その辺の診療報酬のあり方や介護報酬のあり方につきましては、社会保障全体の中でどうしていくのかということになると思うので、区でどのような形で支援できるか、どうしていくかということは。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そしてその後に、そこの急性期を脱して、次に行く病院にしても、二十数万円という支払いが当たり前という状況になっているので、それが払えなければ、本当に老々介護でやっているにもかかわらず、茨城県や栃木県に入らざるを得ないという状況になっていることは、この包括ケアシステムで掲げた理念と反すると思いますので、そういうところが一番の現実の問題になっているというのが実感なので。","respondent":"川島健康課長","answer":"具体的に、どのように、どこに働きかけるかといった部分につきましては、お約束はできないですが、課題を抽出しまして、それをしっかり検討して、よりよい地域医療ができるような形を実現させていきたいと考えております。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういう情報も載せていく。例えば品川区も非常に人数が多いわけですから、介護認定の会議は週１回くらいやっているのでしょうか、毎日ですか、毎日やるとなると、それくらい人がいるということではないですか。そういう方をどういうふうにしていくのかというと、何かの会議をやると、おのずとその方をフォローすると、会議体の数もどこで情報を取るかといったら、そういう数も出てくるわけではないですか。","respondent":"川島健康課長","answer":"例えば柏市のほうが、もう既に患者情報の共有システムは入れていまして、これも全部の診療所と病院ということではないのですが、それから小さな町でやっている取り組みですとか、そういった先進自治体の取り組みもいろいろと勉強して。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"在宅に戻ってきても、では介護保険があるのか、治療に当たる療養費というのもあるけれども、在宅で介護保険を使って療養費も使うという方もいらっしゃる。こちらは施設に入っているけれども、終の棲家の施設もあれば、老人保健センター等で戻ってくる情報をどういうふうに取るかということもある。施設から施設へということもある。そういうパターン分けのようなものは、もうできているのでしょうか。","respondent":"川島健康課長","answer":"やはり人が１００人いれば、１００通りのシステムができる、地域包括ケアシステムだというようなお考えのお話もお聞きしますので、分類して種分けするのはなかなか難しいような課題かと考えています。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問","question":"そうすると、その方々に携わった方々のマンパワーが非常に大切になるのかなと思います。行政が全部把握できないとなると、そういうものをお願いしてやってもらうことになるわけではないですか。そこら辺の強化については、これは区からも強く言っていいような気がしますけれども、そこら辺はどうお考えなのでしょうか。","respondent":"川島健康課長","answer":"それぞれの主体において、それぞれの職員や医者自身のレベルアップの取り組みは、当然、されていることはあるはずですけれども、区としても、足りない部分を、例えば研修を開催したり、勉強会を開催したり。","id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"質問","question":"もう１点、災害医療の部分は、もちろん防災課でやっていらっしゃるのなら、それでいいのですが、医者自身からトリアージとか、夜この時間なら、こうなったらきてほしいと言われているけれども、現実、トリアージなどは怖くてできないという話も、大分聞きます。そういうお話も聞く。そして、伺うと、開業医であっても、全体を含めると、８割くらいは品川区にいないと。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"いながわ委員","kind":"質問・要望","question":"これは積極的にどんどん進めていただきたいのですが、このシステムに関して、この地域包括ケアシステムの医療と介護の連携のみの単独のシステムなのか、それとも、品川区が土木課などでよくやっているＧＩＳ、地理情報システムの運用の中で、例えばそこに病院とか、いろいろな部分を落としていくものなのか、システム的なことを教えてください。","respondent":"川島健康課長","answer":"ですので、どこまでパスワードを提供するかという話で、情報の範囲は限られるのですけれども、インターネット接続できる環境があれば使えるというものになります。","id":"exchange-035"},{"speaker":"いながわ委員","kind":"意見","question":"そういうのを見落としてはいけないので、先ほど拡張性という言葉がありましたけれども、多様性というのか、いろいろな地図を品川区も持っていますので、それと互換性があるようなつくりにしたほうが、今後、いいのではないかと思うのですが、まだこれからなのでわからないと思うのですけれども、何かあればお願いします。","respondent":"川島健康課長","answer":"今のご質問の中でありました、単純なものですけれども、診療所がどこにあると、地図情報に打ち出しはできるような形で、参照はできます。それを考えていて、医師会のほうでも、どの地図を使えばいいかということを、今、検討しているように聞いております。","id":"exchange-036"},{"speaker":"若林委員","kind":"質問・要望","question":"今後の構築について、今は医療がリーダーシップを取ってやられているわけですけれども、先ほども、認知症のところで新妻委員のご質問にも、既に介護と区の情報共有は、もうしっかりされているということもあったので、介護のほうから見た医療のシステムというのは、どういうふうに思われているのか、また期待されているのか、お聞きしたいと思います。","respondent":"川島健康課長、永尾高齢者福祉課長","answer":"先ほど、私の説明が少し足りなかったかもしれないのですけれども、今の医療資源検索システムのもとになる医療連携関係機関名簿というものがありましたが、これはケアマネージャーが。ただやはり一番問題になっているのは、最初に申し上げた、どの項目のどの情報が必要なのかというところの話し合いが、多職種連携の今一番課題ですので、その連携の会議等の中で、その辺をきちんと共有していくことを、今。","id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今の話で１点だけ。区民の方々にとって、何がいいか、せっかく医療、介護連携するならば、特区でもいいけれども、最終的には特区しかないけれども、よくご存じのように、２４時間訪問介護事業者でやるとなると、看護師を雇用しなければならないではないですか。例えば一人でやるとしたら、２人は採用しなければいけない。これは、今はできないわけですけれども、そういう特区的なことだって考えられる。","respondent":"永尾高齢者福祉課長","answer":"区独自で報酬体系を変えるところまではできることではないので、国の包括ケアシステムの構築での検討の推移なども見ながら、また実際に品川区内の事業所にもそういう話を聞きながら、国からおりてきたら、どういうふうにやっていこうかということは。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/866699?Template=document&Id=3434#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":40480,"voices":96}},{"id":"h27-20151201-8","meetingId":"h27-cm12","date":"2015年12月1日","dateIso":"2015-12-01","committee":"建設委員会","time":"午前１０時００分～午後 ２時４３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を71件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"地球温暖化防止の対策は、世界中で今、大事な重要事項になっているわけですけれども、目的というところで、「品川区内の環境に関する取り組みを広くＰＲし」とありますけれども、特に品川区として一番ＰＲしたい点というのはどんな点なのか、もう少し詳しく伺えればと思います。","respondent":"三ツ橋環境課長","answer":"今回、先ほどパネル展示を３テーマと申し上げましたけれども、こちらのパネル展示におきまして、ＰＲしたい点と考えております。こちらは、しながわエコリンクまたＥＣＯフェスティバル、そしてエコ・クッキング選手権の３テーマを中心に展示しております。以上です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと、この「みどり東京・温暖化防止プロジェクト」の一環として出展ということで、そのプロジェクトの目的と関わって、もう少しパネル展示３テーマというところで、テーマの中で、特にこういったところを品川区で取り組んでいるということをＰＲしたいというようなところがありましたら、もう少し教えていただければと思います。","respondent":"三ツ橋環境課長","answer":"今回、３テーマにつきましては、しながわエコリンクが、今年度から品川区として実施いたしました環境マネジメントシステムについてのご紹介です。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"進め方の問題で、ちょっと関連してお伺いしますけれども、今回の計画、工事計画について、調整相手になるような主な関係団体は、例えば野球の方とかいらっしゃるかもしれないのですけれども、そちらはどういう団体を考えているのか。説明会をやるということでしたけれども、そこへの周知方法や説明会の対象に、そういった関係団体の方がなっているのか、伺います。","respondent":"多並公園課長","answer":"ゲートボールをやられている方、さまざま西大井広場については、ご利用いただいている団体の方々がいらっしゃいますので、まずは今のこの工事の、この件についての、今後に説明会を開く上で、これから具体的なお話は、事前にお話ししながら、説明会後には。","id":"exchange-003"},{"speaker":"安藤委員","kind":"確認","question":"わかりました。これに関して、問題ないのかどうかというのは、問題ないと思うのですけれども、それをちょっと改めて確認させてください。","respondent":"多並公園課長","answer":"団体の方々が説明会の対象か、もちろん対象ですけれども、団体の、実際にご利用いただいている方については、もちろん説明会の対象ですけれども、また別な形で、個別で、工事のやり方については、お話しに行くこととなります。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"具体的な計画の内容というか、説明をお伺いしたいのですけれども、この西大井広場公園なのですが、災害時の給水場としての位置付けもあると記憶しているのですけれども、震災対策井戸があると思うので、それは残されるのか。それと、あと応急給水槽の設置などについては、何かお考えがあるのかお伺いします。そういった要望をしたいのですが、計画はあるのでしょうか。","respondent":"多並公園課長","answer":"３メートルの高さがある築山がこの東側にあるのですけれども、そこの中に埋まっている形になりますので、今設計の中で、それをなるべくフラットにする構造ができないかというのを検討しておりまして、より皆様がご利用いただけるようにフラット化について鋭意検討して。","id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"それとちょっと幾つか確認なのですが、トイレの話なのですけれども、災害時にも使えるようなトイレというのは、今、現状ではないと伺っているので、そういったことも、きちんと給水所になるわけですから、大事かという気がする。フラット化しつつも水槽は残していくみたいな、そういう話で、今捉えたのですが、それでいいのでしょうかということをお伺いします。","respondent":"多並公園課長","answer":"井戸の件ですけれども、今、災害用の井戸がまずあるのですけれども、それと、横に給水、それを貯めておくための給水のための給水槽というものが横にありまして、それが、先ほど言ったフラット化をすると出っ張る形で、最後、山の中にありますので。","id":"exchange-006"},{"speaker":"西本委員","kind":"確認","question":"幾つか確認を含めてお願いいたします。１７区画で４区画から鉛が出ましたと。水はけのいいものにかえられるのでしょうかということ。それから、裏面のほうで見ると、この改修するというのは、どの辺まで言っているのでしょうか。保育園のほうですけれども、園庭も含めての予定地になってくるのか、建物だけでこのエリアなのかということを、まずお聞きしたいと思います。","respondent":"多並公園課長","answer":"今の駐輪場の部分につきましての委員のお申し出も含めて理解しておりますので、その設計の中で最終的には検討していきたいと思っているところです。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"全体的に西大井広場という中では、２９年度、３０年度という形で随時やっていくという、ご努力はわかりました。では、園庭という考え方としては、広場を子供たちは使うのかというふうに思うのですけれども、そうすると、一般のご利用の方との住み分けとかというのは、もっとできるようになっているのでしょうか。","respondent":"多並公園課長","answer":"今の委員のお話と、今保育課で予定しているのがあって、西大井広場公園という大もとのほうを、屋外遊技場として設定、指定したいということで聞いております。","id":"exchange-008"},{"speaker":"西本委員","kind":"意見","question":"なので、事前に説明会が始まると思う、１２月１４日でやると思うのですけれども、まだ具体的に皆さま、そこまで気が回らないかもしれませんけれども、だけに、おいおい建築が進む中で、そういうのに際して、子供たちがどういうふうに遊ぶのとか、ずっとその公園を一般の方が使っているわけではないので、住み分けはある程度できると思うのですけれども。","respondent":"多並公園課長","answer":"まさに、今の委員のご指摘のところが、我々公園管理者としても課題というか、調整しなければいけないポイントだと考えていますので、そこにつきましては、保育部門とよく連携しながら、今後利用者の方が、保育園もそうですけれども。","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問・要望","question":"お子さまも使われることですし、あと水にも影響が出ないように、この鉛の除去の工事は、しっかりと進めていただきたいと考えています。東品川公園も、前は教習所で使っていたということで、水銀とか検出されたと思うのですけれども、この西大井広場公園は、もともと何に使われていたのでしょうか。","respondent":"多並公園課長","answer":"そちらが、買われまして。その後、会社の名前が変更していって、現在の名前で言うと三菱重工が、ずっと昭和４７年までお持ちで、工場がもともとありました。今の、その工場では、戦車とか農機具だとか農機械だとか、そういうのをつくられていたということを聞いております。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"こうして鉛とかが検出されるということは、最近の法令で厳しくなったので、それでしっかり調査したらこういう鉛とかが出てきたと、わかったということだと思うのですけれども、今、急にお答えするのは難しいかもしれませんけれども、潜在的には、全体、品川区には、そういった場所、どのぐらいあるのでしょうか。特に工場の跡地だったと思いますが。","respondent":"三ツ橋環境課長","answer":"なかなか、品川区内に、どのような分布というのは、環境部門としても難しい部分がありますけれども、例えば、土地の入替えなどのときには、３,０００平米以上ですと、法令に決まって、条例にも決まっておりますので、そのようなことで把握していくというぐらいしか。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明どうもありがとうございました。これは、土壌改良工場がまず先決になる前に、この築山を、３メートルの築山を壊して、土壌改良工事。先ほどご説明あったとおり、鉛が深さ４メートルまで達しているということで、これは掘削に関して言うと、深さ４メートル、それ以上掘削しなければいけない。ましては３メートルの築山があるとなると、この掘削の土が大量に出ると思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"現状使っている団体に、保育園をつくることは決まっている、これは当然のことをしている。公園を使ってということになると、やはり、現在の利用状況を、少なくとも減ってしまうような形になるので、そこを最小限に抑えられるような、公園課としてのそれに対しての要望を必ず入れておいていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"つる委員","kind":"確認","question":"１７区画というのは、今回の、この図面の薄緑色の所でくくったところの分母が１７区画だと思うのですけれども、そうすると、今、先ほど若干議論がありましたが、特に今回ここが保育園ということもさることながら、これからも３０年以上、私も小さいとき、ここで遊んだ経験があるのだけれども、そういう、ほかの部分のところの、いわゆる影響とかというところは。","respondent":"多並公園課長","answer":"今の利用につきましては、委員のお話のとおり、この広場につきましてはダスト舗装であったり、園道だったらインターロッキングとかアスファルトとか、おのおの舗装をしていますので、お使いの方々またはお子様が直接触れるようなことがないということで。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと設備の内容についてお伺いしたいのですけれども。ちょっと、犬の立ち入りなども、愛犬家の方々とかって、なかなか公園に立ち入れないみたいなルールがあって、犬も好き嫌いがあるので、難しいところなのですが、そういったルールはどうなるのかとか、あとは、ボール使用などのルールなどは、どういうふうなお考えなのかというのをお伺いいたします。","respondent":"多並公園課長","answer":"先ほども説明しましたが、複合遊具につきましても、そこに柱のような形で遊具を設置しておりまして、災害時はそこに幕を張るとテントとなるというような、そういう形で、この公園につきましては、平常時は平常時の利用をしていただきながら。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"説明会の実施状況、今回も説明会をやりますけれども、この以前にも説明会というのをやっていたのかというのを、そこら辺の実施状況があれば、もし、いつぐらいにやっていたのか、どんな意見が挙がったとかいうのがあれば、ちょっと紹介していただきたいのと、それと、今度また工事説明会が１７日にあるということなのですけれども、その対象者と周知方法についてもお伺いします。","respondent":"多並公園課長","answer":"これについては、いろいろな歴史とか、今までの、その地域での考え方とか流れがありますので、その地域での、その状況に応じた対応というのが、一番、この件に関しては重要かというのが、私としては考えているところになります。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"犬の問題については、地域に応じたというのは基本だと思いますが、ペットに対しての位置付けというのも大分変わってきましたので、高齢者の方々にとっては、非常にかけがいのないパートナーだったりというような局面も出てきていますので、おっしゃるように、非常にデリケートな問題であることは承知しているのですが、できる限りペットが入れるように、その入った際に。","respondent":"多並公園課長、鈴木（誠）防災課長、曽田災害対策担当部長兼危機管理担当部長","answer":"保育所の件ですけれども、もちろん特区の制度で、広場の３０％までという規定がありますけれども、この、今の私たちの考えとしては。ヘリが来ることの要請ですけれども、ヘリ自体を要請するというよりは、自衛隊に関しては、区から都知事に要請を出して、その総合的な判断の中で。運用のやり方、運用のイメージというふうに言われましたけれども、発災当初につきましては、やはり連絡幹部、いわゆるＬＯですけれども。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"この公園、拡張整備したいという趣旨は、当然、公園ですから、普段は公園としての利用も考えておられると思うのですけれども、私も防災上必要と思いますので、ヘリポート機能を、どちらかというと重視した公園でいいのかという、この理解でよろしいのかということ。","respondent":"多並公園課長","answer":"そういう考え方であります。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問","question":"基本的には１カ所、抜ける道は。下はこれ、一番下の道路は、道路として往来できるということですか。","respondent":"多並公園課長","answer":"もうちょっとつけ加えて、今、南側の部分につきましては、東側が中小企業センターがありますので、公園としてはつながっていないところなのですけれども、これについても連携して進めていまして、少なくとも区役所までは、この３メートルの。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"そういった場合に、ここを中核にして、そういった近隣区の、自治体の方々との共同という形で、お互いさまではないですけれども、そういうのをやっていく必要もあるのかと、品川区だけがいいわけではなくて、積極的にやって、病院の搬送などもいろいろできる中では、多分すごく中心的な大切な公園になるのではないかと、そういう関係づくりもしていいのではないかと思うのですが、いかがでしょうか。","respondent":"多並公園課長、鈴木（誠）防災課長","answer":"段差の件なのですけれども、ここは今の委員のご指摘のとおり、上の段と下のが約２.６メートルほどの段差があるのですけれども、これについては、整備の説明会のときにも、住民の方にいろいろご説明したのですけれども。このヘリポートを品川区だけではなくて、近隣区も含めたエリアの拠点ということについてのお尋ねですが、既に東京都と自衛隊と２３区の防災課長会で、協議する会議体が設置されております。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"せっかく住民がやりたいというような話になったときには、「区はやりません」と言うのではなくて、ちょっと柔軟に応じてほしいと、そこまで士気が高く上がらなければ、それはする必要はないと思っているのですけれども、それは、どれだけ皆さまの要望があるのかというところの熱意の問題だと思うのですけれども、ただ熱意が上がってきたときに、ちょっと聞く耳を持ってほしいというのがあるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この場所、ＪＴの土地から購入したときから防災ということで進んでいただいて、近所の方もご理解をいただいた上で、これを進めている。いい形でつくっていただきたいと思います。その辺の意識しておいてもらいたいと思います。せっかく緑をやったのに、ちょっと違う方向に行ってしまうと、その辺の考え方として、もう１回ちょっと聞きたいと思ったので。","respondent":"多並公園課長","answer":"ただ、委員が今、ご懸念されたことについて、我々も十分承知した上の、今後の管理のあり方はもちろんしっかり検討していきたいと思っているところです。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ、その辺、周りの方を調整した上で、いい公園にしていただきたいと、それと同時に、先ほどシロツメグサとありましたけれども、その辺の管理も、はっきり言って相当費用がかかるのではないかと思うのですけれども、その辺の管理もしっかりやってもらいたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"つる委員","kind":"確認","question":"細かいところで、ちょっと事前に確認できなかったので、先ほど質疑の中であった地下倉庫の位置が、ちょうどこの中央の四角破線のこのあたりでいいのかということを１つ教えてください。","respondent":"多並公園課長","answer":"その前の、三角形の印が２つ書いてありますけれども、こういう形、ここから、園路からすぐ取り出せるというような、そういう位置、配置になっているところです。","id":"exchange-024"},{"speaker":"つる委員","kind":"質問・要望","question":"そうすると、少し注意的なことで言うと、逆にスロープ状というか、段差みたいになっているのですか。それはそれで後で教えていただきたいのと、地上部分と地下の部分のところで。当然、形状のあれがあると思うのですけれども、もしそういうのがあるのだったら、それをちょっと教えてください。","respondent":"多並公園課長","answer":"ヘリコプターが下りてくる方向をいろいろ検討した結果、中小企業センターが右にあって、角のほうまでこうあるわけなので、そこから左ですと建物があって、今の学校ですが、そこの間が離発着できる、想定できる範囲があるのですけれども、そこが、ちょうど真ん中を見ると。","id":"exchange-025"},{"speaker":"つる委員","kind":"質問","question":"それと、もしかしたらいろいろなところですり合わせたのかもしれませんけれども、災害、防災協定の話も、今課長からおっしゃられたのですが、実際、関連施設というところで、まさにこうしたヘリコプターの離発着の訓練ですが、今後は、これまでもあったかどうか、ちょっと自分の中で記憶がないのですが、あと過去に自分で聞いた記憶もちょっとあるのですけれども、改めて。","respondent":"鈴木（誠）防災課長","answer":"現在は、ちょっと本部の訓練内容を、少し本部運営のほうにシフトした内容で強化しているところですので、ヘリ離発着を含んだ訓練というのはやっておりませんが、今後はご指摘ありましたように、重要な災害時の対応の１つの手法になりますので、ほかにも区内４カ所は。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問・要望","question":"関連した話ですので大変恐縮ですが、先ほど近隣住民とのいろいろなご協力とかご要望とかある中で、やはり頻回してやると、なかなか騒音だとか何だとかいう課題もあると思うので、ただ実際に、そういうふうになったときにはどういうふうになるのかということを知っていただくという意味も含めて、あとは実際の災害のそういった近隣自治体との連携の輸送体制だとか、そういうのも全部含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-02","title":"の平成２７年度区内一斉防災訓練（避難所・災害対策本部）の実施","agenda":"の平成２７年度区内一斉防災訓練（避難所・災害対策本部）の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"概括的なことからお伺いしますけれども、今回一斉防災訓練が何回目になるのかということと、あと開催を積み重ねていって改善や工夫してきた点、そして今回の訓練で一番強化したい重要ポイントとなるというのは、どこと考えていらっしゃるのかを、まずお伺いします。","respondent":"黒崎防災安全担当課長","answer":"そのようなことを想定しまして、今回は無線機を使った各避難所と地域センター、地域センターがその情報を集約して、区の災害対策本部にその情報を集めてみると、このような通信訓練を今年度の訓練の目玉、強化した部分として企画してまいりました。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"実際に、震災時を想定したリアルな、実際的な訓練に、少しずつ発展させていくということが大事だと思いますし、その方向で今、努力されているとは思うのですけれども、具体的にお伺いしたいのは、無線でとかありましたけれども、配布している防災タブレットで本部との通信などを行うということですけれども、３.１１のとき、品川でも携帯はもちろん、特につながらなかったですし、Ｅメールというのですか。","respondent":"鈴木（誠）防災課長、黒崎防災安全担当課長","answer":"それ以外の通信機器も、いわゆる区で独自の放送局を設置している防災無線それからここに書いてある移動通信、それとタブレット、それからあと区のグループウェアというものですが、内部の。必要な支援につきましては、各避難所を運営する場合、それぞれ避難所運営会議というのを町会の方がお持ちですので、そこへ訓練を企画する上でのアドバイスあとはお手伝い、訓練当日には、参集職員による実際に。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"幾つかあるのですが、まず今の３２カ所になりますけれども、徐々にというお話ですが、徐々にでいいのですかというところがあります。今回参加されないところは、参加されない町内会は何件あるのでしょうか。それは、今回参加されないところは、その運営会議もやっていないということの理解でよろしいでしょうかというのが１つ目です。","respondent":"鈴木（誠）防災課長、黒崎防災安全担当課長","answer":"そこに、先ほど申し上げた地区担当と、それから避難所ごとに約１０名程度指定をしております職員が、平常時の会議にも参加をしまして、顔の見える関係、それから実際の避難所の資機材や部屋の様子、そういうのも日ごろから見て。ですので、区内で２０７町会がありますので、７０程度の町会がございました。こちら、参考ですけれども、一昨年の平成２５年に実施したときは、８６町会が参加いただいているので、約５０ぐらいの町会が増えたというような状況です。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"あくまでも、自主的なというところがあるのかもしれませんけれども、ただ品川区としては、避難所の体制というのは、住民たちが中心にやってほしいのだということなのですから、そこの自覚を持ってもらわないとなかなか参加されない町会たちに、なかなかこの先も、本当に参加するようになるのかという考え方が、ちょっとずれて、あまりにもずれが激しくあるような気がしているので。","respondent":"鈴木（誠）防災課長","answer":"３点、今後の促進と各避難所ごとでの統一性とか、区の目指すところ、それから啓発部分ということで関連しますので、ちょっと全体を総合してお答えをします。委員ご指摘のとおり全町会が避難所訓練を実施するという状況ではありません。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"最後に、この経験を、多分いろいろな反省点、今回もいっぱい出てくると思うのですが、それを各町会であれ、地域センターでもいいのですけれども、フィードバックというのは、今後どう考えられるのですか。そういうときに、こういう課題がありましたというのは、共通の課題という形で、全体的に広げていかなければいけないと思うのですが、それについてのお考えをお聞きしておきたいと思います。","respondent":"黒崎防災安全担当課長","answer":"訓練を企画する際、その地区ごとの情報が、区で実施した結果の情報が、各地域センターに集まってありますので、その内容を共有しながらやっているということで、フィードバックはするような形で、少しずつ訓練の中のブラッシュアップといいますか。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"フィードバックですが、時期的に次年度もやります、次年度をやるときに、昨年度の課題ではなくて、すぐです。そうしないと、忘れてしまいます。なので、終わった後にすぐ振り返りというのは必要だと思うのですが、それはいかがですか。","respondent":"黒崎防災安全担当課長","answer":"実は訓練が終わった後、これはもうすぐの機会に行うのですけれども、避難所運営協議会というような、会長が集まって行われる連絡会がありまして、そこで反省点を出し合って、来年はというような話を持つ会議体は、それぞれ設置してやっております。","id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"提案","question":"確か自民党から、１０年ぐらい前に、「これ、一斉にやりましょうよ」という話を提案させていただいて、当初なかなか職員の方から、「一斉に出るから大変だ」というお話があった中で、今回４回目。去年はできなかったけれども、４回目ということでいい形が進んできていると考えています。","respondent":"鈴木（誠）防災課長","answer":"それと、この参加の一覧に載っていない町会の活動については、今回のこれには一斉訓練についての部分の情報ですので、ちょっと出てこないのですが、地域での活動状況等も区のほうでは必ず訓練実施の後に報告書をいただいておりますので、その辺はしっかりとまとめて。","id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"意見","question":"この表を見ると、一覧で出たときに何もやっていないように見えることは、せっかくやっているところに対して、ちょっとかわいそうかという気がしました。今後、なるべくなら全体でできるように、先ほど言った職員の方も、そうやって訓練に出るのは大変でしょうけれども、ぜひいい形で進めてもらいたいと思っています。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"安藤委員","kind":"確認","question":"目視調査ということで１,６７４戸、空き家が確認されたということですけれども、資料の１番のところで、その内訳などの評価結果として書いていますが、その隣に貸す意向ありということで２７件とありますけれども、これは１,６７４戸について登記簿調査の上、所有者がわかったところのうち、意向があるところだと思うのですけれども、この登記簿調査の上、所有者がわかったケースというのは。","respondent":"矢木住宅担当課長","answer":"認定のタイミングですが、４番の下の対応、こちらの対応のほうを各所管でした後に、それでも所有者の方等が、管理不全状態を改善していただけないとこういった場合に、この審議会に諮りまして、認定を受けて、２番左下の措置のところに移行するものです。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"措置の前に、この認定をする。特定空家として審議会に諮問をして、認定をされたのに関して、措置の対応をするということでよろしいのかというのが１点と、あと、実際に今、この審議会で特定空家と認定されている件数は何件なのか、お伺いします。","respondent":"矢木住宅担当課長","answer":"委員ご指摘のとおり、できる限り所管課での対応をした上での認定という形になるということと、あと、認定、既に済んでおりますものは、特定空家については１件あります。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。実際に産学官と地域によるアイデアというのもありますが、どんなアイデアや検討が出されているのか、現状をお伺いいたします。それと、区による活用も難しいというお話がありましたけれども、どういったところが課題になっているのか、もう少し伺わせてください。","respondent":"矢木住宅担当課長","answer":"産学官におけるどんなアイデアが検討されているかですが、こちらまず、具体的には、清泉女子大学が幾つかの町会に入ってフィールドワークをする中で、どのような地域のニーズがあるかというようなことを聞き取り調査している段階でございまして、具体的には。","id":"exchange-038"},{"speaker":"安藤委員","kind":"提案","question":"それとあとは、例えば、他会派からも一般質問のときにありましたけれども、子ども食堂というようなところか、空き家の振興対策としての子ども食堂というのが、今、あちこちで出ていますけれども、地域の方からも伺ったのですけれども、ぜひ、そういった事業がやれるのであれば協力したいという方、具体的に私にも、ちょっと相談もありまして。","respondent":"矢木住宅担当課長","answer":"町会会館につきましては、空き家の活用ということで、具体的に既に２つや３の検討はしております。ただし、地域のニーズをよくよくお聞きしていくという中で、なかなかちょっと利権がとか、所有者との賃料とかの交渉の中で、ちょっとなかなか難しいところがあります。","id":"exchange-039"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ごみ屋敷についてお伺いしますけれども、旗の台４丁目そして西中延３丁目に、いわゆるごみ屋敷があるのですけれども、旗の台４丁目の物件に関しましては、地域の皆さまからは、いろいろなご相談を、私も承っております。進行具合を教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。ご覧のとおりビラとかも掲示してある状態で、それをまた所有者というか、地上権を持っている方が剥がしているのでしょうけれども、剥がすと同時にまた、本当の地域の強い要望なので、なるべく早目に対応をとっていただきたくて、防犯上、防災上にも、非常にこれ、かかってくると思いますので、早急に条例にのっとって措置をしていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"西本委員","kind":"確認","question":"ちょっと確認させてください。そこの中でも、行政に貸す意向があると言ってくれているのが２７件。それで、要対応が９９件というのが、どの辺に密集しているのかと、ある程度、密集しているのか、それともばらばらになっているのかというそのイメージがちょっとわからなかったので、どんなふうになっているのでしょうか。おわかりでしたらちょっと教えてほしいのですけれども。","respondent":"矢木住宅担当課長","answer":"こちらの利活用、修繕利用と答えのあった１,５００件を超えるほとんどのところですが、こちらにつきましては、客観的に見て使えそうだという物件。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"そうするとこの評価結果というのは、ここにも書いてある外観目視によるということなので、この後、結局その持ち主の意向を聞いていくという段階のものなのでしょうか。ただ実際に困るのは、ごみ屋敷ではないかと思うのですが、今の例もありましたように。","respondent":"矢木住宅担当課長","answer":"例えば、相談窓口の設置でありますとかを検討いたしますとともに、啓発のパンフレットを送付するといったことで対策を考えていきたいです。ごみ屋敷にどこまで手を差し伸べられるのかという問題は、なかなか難しいところがあります。","id":"exchange-043"},{"speaker":"西本委員","kind":"提案","question":"ただ一番、住民たちが困るのは、やはりごみ屋敷。いつそこから何が起きるかわからないという、それが不安材料ということだと思うのですが、ここで何をせいということは、なかなか提案できないのですけれども、やはりここに絞っていくという状況ならば、ほかの委員会とのさらなる議論というのを進めていく必要もあるのかというふうに感じました。ここだけではちょっと解決つかない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"質問","question":"本人が費用を払えない状況の中で、今みたいな現状になっていると思うので、今後どういうふうに考えていったらいいのかと、区として費用負担、個人の資産に対して、どこまで手を出していいのか、そこら辺の考え方というのはどういうふうに捉えたらいいのでしょうか。","respondent":"藤田都市環境部長","answer":"とりあえずは、危険回避のために通常の道路の脇にある建物で、何か崩れそうだというときも、やむを得ないケースの中では、区のほうが手出しをするようなケースもありますので、その辺の兼ね合いをよく考えながら、しっかりやっていきたいと、いずれにしても。","id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"自分、この説明の中でちょっとよくわかっていなかったのが、資料の２番の措置のところで、先ほども質問があったのですけれども、これが、空き家とかごみ屋敷の認定は、１１条の公表のところでというお話があったと、自分はちょっと理解したのですけれども、この６条からずっと始まる中で助言、勧告をする８条、９条あたりの段階でも、認定はしていないけれども認識した上で進めているという状態なのかどうか。","respondent":"矢木住宅担当課長","answer":"私の説明が不十分で申しわけございませんでした。認定ですが、こちら、もろもろの手続きを進めていく大前提になりますので、実態調査や立入調査をする前に、認定調査をするものです。","id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"意見","question":"そうすると逆に、３番で産学官協働活用モデルの場合にも、先ほど食育ですとか、話のありました町会会館も、こういうときの避難という感覚でいくと、やはり難しくなってしまうのではないかという気がするのですけれども、そこら辺はどういうように考えたらいいのかと。","respondent":"矢木住宅担当課長、藤田都市環境部長","answer":"やはりこれというのは、条件のすり合わせだと思われるのですが、この程度古くても１階建ての利用しやすいところが、１階建ては少ないですけれども、区内がいいですとか、そういったもろもろの条件で合致するものであれば。そんなような物件も結構ありますので、区の活用モデルの中では難しいケースと、産学官で活用していけるケース、その辺が、少し振り分けがされるです。","id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。確かに、区であまり、区で一致した条件と、少し緩やかな部分にできる。活用してもらいたいという前提での話なので、産学官、それと同時に地域の声も生かしながら、ぜひ進めていってもらいたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"つる委員","kind":"確認","question":"ちょっと順を追って、確認も含めて教えてください。","respondent":"矢木住宅担当課長","answer":"申しわけございません。先ほどの答弁を訂正させていただきたいと思います。アンケートの送付数といたしましては、１,６７９件が正しいものでございました。これにつきましては、おそらく複数の所有者でありますとか、権利者関係で、多少プラスがあったものと考えられます。","id":"exchange-049"},{"speaker":"つる委員","kind":"質問","question":"そうすると、先ほどの鈴木委員とか西本委員からもありましたけれども、３番の区によるというところに関連すると、なかなか難しいという課題が挙げられるのは、その２７件お返事があったということのものが分母になるということでいいのでしょうか。","respondent":"矢木住宅担当課長","answer":"今年度につきましては、モデル事業ということで、２７件を主な対象として進めているところでございまして、その中で、なかなか活用が難しいという現時点での状況です。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"今年度が、それを１つの分母としてやっていただいているという中で、今後しっかりと条令をつくって動いていただいているという中で、１,６７４という１つの分母がある中で、今後、年間、具体的な対応だとか、生かしていく意味での部分の予算であるとか、いろいろな調査だとかということで、所管として、どのぐらいの件数を今後、対応していく計画とかというのは、現在の案を教えてください。","respondent":"矢木住宅担当課長","answer":"立正大学と東京工業大学でいらっしゃいますが、こちらも来年度には活動するということで、少しずつ話を進めておりますので、これについても実現に取り組んでいきたいと考えています。","id":"exchange-051"},{"speaker":"つる委員","kind":"質問","question":"それで、具体的な、それを目標として達成するための手段というところで、産学官のことが適用されているわけですけれども、その中で活用と、今おっしゃった特定空家にならないような支援という１つの、区として今、現状の、まさにそれをモデルで模索されながらなので、まだまだ方向性などというのは安定していないとは思うのですが、区としては、今、ざっくり大きくこれだけの分母がある中で。","respondent":"藤田都市環境部長","answer":"でも、それでも難しいとか、いろいろなご事情があるようなケースに、区のほうが手をお貸しするというような形で進めるのがいいのかと。","id":"exchange-052"},{"speaker":"つる委員","kind":"質問・要望","question":"今、全体的なことをお聞きした上で、具体的な３番のところなのですけれども、先ほど来、私、一般質問で言った子ども食堂なんかも、今、質疑の中で出てきて、検討の余地があるのかなんていう答弁も、あるというのは方向性として。なので、これは要望です。","respondent":"藤田都市環境部長","answer":"私ども、少なくとも空き家対策は、空き家対策の場面だけを捉えて対応していこうと思っているわけではございません。通常、今行われています地域の力支援チーム、こちらのほうも地活のほう、それから都市のほうも含めたいろいろな形で対応してきているところです。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問","question":"行革委員会のほうで、例の民泊の問題が出てはいるのですけれども、それではなく、海側というか、東海道地域では、ゲストハウス、品川地区で旅館業法上の簡易宿泊所というのがあるのですけれども、かなり利用されていまして、１つの旧東海道地域の売りというか、貴重な資源になっているような面もあると思いますが、例えば、そういった事業をやりたいという方々が、そういう事業をしやすくするために。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"筒井委員","kind":"意見","question":"エステサロンとかを経営されている女性の方、お話はいろいろ聞くのですけれども、そういうエステサロン、例えばなのですけれども、最初の開業するに当たり、どうしても家賃とかコストがかかると、それはエステサロンに限ったことではないと思うのですけれども、例えば起業したいという方がいて、事務所を借りたりすると、当初の賃貸料でランニングコストとかがかかってしまうので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"何点か質問させていただいたこと自体が、要望に近いというふうな感じを持っています。それがなぜか、急にばたばたっとうまくいって、きれいになった所もあるのですけれども。ただ、現状ですぐ使えるかどうかというのも難しい。これは一つ、当然、地域活動課、地域センターとの絡み、その辺も含めて、区内の中で、区行政の中の連携というのを、もう１回改めてお願いしたいということが要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"木村副委員長","kind":"意見","question":"いろいろと皆さまのお話を聞いていて、なるほどと思う点がたくさんありました。空き家をどうすればいいのかということも、住むか、または人に、いろいろな福祉にしても、いろいろなことに関して使うことということがいろいろあるのですけれども。そういう意味では、もちろん安全でないのは困りますけれども、そういう点もクリアできるのであれば、そういうのも１つの手ではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"先ほどのＮＰＯの方々とか、あと福祉の方たち、民泊というのもありました。２０万、３０万します、それなりのうちだったら。多少修繕すれば、それなりに稼いで、お金も集められるわけですから。税金を使うとかいうことばかりではなくて、お互いのことを知ったことによって、活用できるような市場が、もしかしたらできるかもしれないというふうに思いましたが、これ、できるのではないですか、品川区に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"}]},{"id":"topic-03","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"東急も区内に、設置の動静については、追加的にホームドアを推進していくということですが、やはり現状は池上線だけが、センサー付き固定式ホームという柵になってしまうと、やはり不十分な状況になってしまいますので、昨日もちょっと質問したのですけれども、ぜひ池上線にもホームドアの設置が必要だと思いますし、品川区からも東急のほうに要請していただきたいと考えているところですが。","respondent":"中村都市計画課長","answer":"しかしながら、今、この固定式ホーム柵も通常の使い方をすれば、相当の安全性の効果が見込まれるというふうには考えますけれども、しかしながら、やはり車両が到着あるいは発着するときに、その出入り口の所にドアがあれば、さらに安全性は増すというところは否めないところです。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問・要望","question":"質問としては、具体的には、こちらの池上線のほうにも、ホームドアを設置してくださいという要請を区からしているのか、していなければぜひしていただきたいと思うのですけれども、いかがでしょうかということと、それと、費用の関係で順次整備していくのは仕方ないというお話でしたけれども、こちら６４駅という紹介がありましたけれども、それが終わった後。","respondent":"中村都市計画課長","answer":"無理にホームドアを設置をしても、逆に効果が見込まれない、ドアに挟まれたりですとか、いろいろありますので、状況に応じて設置をしていただくように鉄道事業者のほうに求めているところです。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり、ホームドアがないというのは、柵がないというか、ドアがないというのは、特に、よく考えると、かなり安全面から言って、異常なことなのですという、最近、私は痛感しているのですけれども、今ないから、ないのが当たり前というふうになってしまっているのですけれども、やはりこれ、あるというのが当たり前だという、国もそういう方向になっていると思いますけれども、そういった、ぜひ、認識を。","respondent":"中村都市計画課長","answer":"大変失礼いたしました。結論から申しますと、東急のほうでは、具体的に池上線が、大井町線が終わった後に工事をやるというふうには明言はしておりません。区のほうで、粘り強くまたお願いしていくという形になると思います。","id":"exchange-061"},{"speaker":"安藤委員","kind":"確認","question":"資料とかもらっているのか。換気口変電施設が、なおかつその立坑ですが、そこからトンネルを掘り始めるというところで、今、仮囲いというのですか、解体するのでしょうか、そういった準備が進んでいるように見えるのですが、こちらの説明会というのは、もう既に終わっているのか、どんな感じで近隣の方にお知らせがあり、そしてまた、どんな不安が寄せられているのか、確認させてください。","respondent":"中村都市計画課長","answer":"今後、上屋の工事がまた始まるに当たりましては、区のほうに届け出がある予定ですけれども、まだ具体的な計画についての相談等もないです。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"やはり、区内の影響ということでは、１つ大きいのが、その換気設備の工事だと思うのですけれども、上屋工事というのが、まだ連絡ないということですが、もしある場合というのは、もちろん近隣の方に対して説明会があるという認識でよろしいかということと、それと、品川駅、今回の工事説明会の資料をもらっていないということなのですけれども、ＪＲ東海の姿勢の問題だと思うのですけれども。","respondent":"中村都市計画課長","answer":"ＪＲ東海からの情報につきましては、今回のこの１件の事業者の公表ですとか、あるいはどういった構造物をつくるかについて、前回の工事の説明会に当たりましては、工事請負業者が現場においての安全性ですとか、あるいはこの構築物について。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"資料について、この整備、裏面の整備断面図という茶色のところなのですけれども、そちらは、今、どんな工事なのかというのは、ちょっと説明がなかったので、わかれば教えていただきたいのと、それと、今後この計画に基づいて川づくりを進めるということであるのですけれども、区の立会川整備の施策への関連性といいますか、この計画ができたことで区としてどんな動きにつながっていくのかというか。","respondent":"和田河川下水道課長","answer":"裏面の整備断面図の前出護岸につきましては、これは現在、下水道局等が整備しております立会川雨水放流管工事などで、できますと、この立会川は先ほども申しましたように毎秒１５立方メートルの水しか流れないようになります。","id":"exchange-064"},{"speaker":"鈴木（真）委員","kind":"意見","question":"１点だけ、東京都の考え方から、ちょっとどうなのか、期限的には、どのぐらいのめどでやっているのか。暗渠区間が６.６６キロメートル、これは今やっていますが、それの完成に合わせてこの対応になってくるのか、今、立会川自体、下水が流れていますが、だから今のやっている工事で、下水が流れなくなるのでしたっけ、そこら辺、ちょっと含めて。","respondent":"和田河川下水道課長、松代防災まちづくり部長","answer":"ただ、委員ご指摘のとおり、今やっている、下水道局が行っている工事が完了しましたら、先ほども申しましたように、今は大量の汚水混じりの雨水が、立会川に出てしまって、環境汚染の原因にはなっているのですけれども。そのときの対応が、さらに更新をされたというふうに、まずご説明をするのですけれども、これにつきまして、立会川は、基本的に東京都、二級河川で東京都の管理ということになっています。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問・要望","question":"都からの報告という例が多かったと思うのですけれども。済みません、ちょっと杭打ちの改ざん、データの改ざん問題がいろいろなところに広がっていると思うのですけれども、改ざんをしたというところの企業のお名前を教えていただきたいと考えています。もしあれば、その内容について、どんな内容なのかというのを差し支えなければ教えていただきたいというふうに思います。","respondent":"鈴木（和）建築課長","answer":"杭の改ざんが、公表していますが、旭化成建材、それからジャパンパイル、それから、ちょっとお待ちください。失礼しました、杭の団体のほうで、一律公表しておりますが、済みません。","id":"exchange-066"},{"speaker":"安藤委員","kind":"確認","question":"相談の件に関しては、やはり新宿区のように相談窓口を規模の大小はあれ、設置していく必要があるのではないかと思うのですけれども、いかがでしょうかということと、それとあと一般質問でご答弁あったところで、区内の再開発に伴う建物の、今回の杭についてということで、杭データ流用の報告は受けていないということで、ただ、一部外構工事でデータの出ていないのが１件あったということでしたけれども。","respondent":"鈴木（和）建築課長、藤田都市環境部長","answer":"ちょっと先ほど説明が非常にわかりにくくて申しわけなかったのですけれども２件、東京都から報告を受けているわけですが、１件については、流用ではなくてデータ、紙ベースで打ち出すときに。ちょっと先ほど建築課長のほうが申し上げた企業名、いっぱいありましたけれども、それについては、コンクリートの杭基礎の、杭基礎のメーカーが調査を行っているところのお話でございまして、一応。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、改ざん、企業がやはり広がっていくと、広がっているというような状況で構造的な問題があるのではないかという指摘もされているのですけれども、今の企業、そして３企業という話もありましたけれども、こちら公表されたというか、調査で明らかになった、改ざんした企業が実際に区内の再開発で杭打ち事業を、杭打ちを行ったという事実はあるのかどうかというのはわかるのでしょうかというか。","respondent":"溝口都市開発課長","answer":"先ほども建築課長が申しているように、全体的なお話、杭打ち業界全体の話になっておりますので、そういった中で、国と特定行政庁、そういったところの中で今後どのような調査またはその受けた形での、今後どういう対応をしていくかというのは。","id":"exchange-068"},{"speaker":"鈴木（真）委員","kind":"確認","question":"確認です。最後の質問で、先ほど言った名前、全部がやっているということではなくて、調査をしているということで、部長の答弁ですが、今、安藤委員の説明でいくと、全部がやったような話になってしまう。そこだけもう１回確認、きちっとしておいてもらいたいと思っています。","respondent":"鈴木（和）建築課長","answer":"それからあと、国のほうでコンクリートパイルの団体に調査を自主的にするようにというところを受けて、コンクリートパイルのほうで自主的に流用があったというところを調査結果をまとめた、中間ですけれども、公表しているのが、先ほどお話させていただいた７社。","id":"exchange-069"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほど言ったのは、全部が流用があったということですか、そこの判断がちょっとごっちゃになってしまっているから。","respondent":"藤田都市環境部長","answer":"調査を行っているものが、全体の数でございまして、その中で、不適切な流用があったというのが、旭化成建材とジャパンパイルと三谷セキサンの３社です。","id":"exchange-070"},{"speaker":"鈴木（真）委員","kind":"質問","question":"済みません。先ほど名前を言っていた残りの会社は、そこに入っていないということで、調査をしているということでいいわけですか。","respondent":"藤田都市環境部長、鈴木（和）建築課長","answer":"ちょっと微妙な表現でございまして、今、国のほうに、その協会のほうが調査の状況の報告をしているのが、調査をしているところまでしか報告をしていないという状況、済みません。ちょっといろいろ説明が不足しまして申しわけございません。","id":"exchange-071"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/967161?Template=document&Id=4158#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":71929,"voices":208}},{"id":"h27-20151201-9","meetingId":"h27-cm12","date":"2015年12月1日","dateIso":"2015-12-01","committee":"文教委員会","time":"午前１０時００分～午後 ３時５３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を79件抜き出しています。","topics":[{"id":"topic-01","title":"品川区立義務教育学校通学区域の取扱い","agenda":"品川区立義務教育学校通学区域の取扱い","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"通学区域は今までと変わりがないということなのですけれども、２枚目をよく見せていただいたら、前期課程の区域と後期の、小学校と中学校の区域が一致しないというか、含まれていない地域があるのですが、この辺はどういうふうに決められていて、不都合はないのかどうか、ちょっとそこをお伺いいたします。","respondent":"野呂瀬学務課長","answer":"前期課程というのは今までの、いわゆる小学校区域、今現在で言うと小学校に入学する方はここの通学区域の方が入れるということで、中学校につきましては、それを包括した通学区域なのですけれども、一部含まれていないところは、逆に言えば。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど行った教育総合支援センターで、中学校と小学校の学区域のすごくわかりやすい地図が置いてあったのですけれども、あの地図というのは、学区域を把握する上でとてもいい地図だなと思ったのですが、あれをいただきたいなと思っているのですが、どうでしょうか。","respondent":"野呂瀬学務課長","answer":"検討します。多分予備があると思います。","id":"exchange-002"},{"speaker":"浅野委員","kind":"質問","question":"通学区域の取扱いということで、このような形で表を出していただいたのですが、それとは関係ないかもしれないのですが、学区域の中で一番遠くから来る児童・生徒というのはどのぐらいの時間がかかっているのか、ちょっと気になったので、そのようなデータというのでしょうか、通学にかかる、歩いて来る子もいると思うのですけれども、時間というのは平均どのぐらいで、一番遠い人はどのぐらいか。","respondent":"野呂瀬学務課長","answer":"ただし、学校案内のところに、できるだけ小学校についてはお近くのところ、通学区域からというようなことを、防災上だとか、防犯上だとか、いろいろな面から提唱していますけれども、例えば、八潮にお住まいの方で大井第一小学校に学校選択でというのは。","id":"exchange-003"},{"speaker":"浅野委員","kind":"質問","question":"統計はないということですけれども、やはり通学路とか、そういう形で規定されているというのでしょうか、そちらのほうをとりながら、一応安全を確保して通学をされているということに多分変わりはないと思いますが、遠いより近いに越したことはないといえども、皆さんが希望される部分もあるかと思いますので、そういう意味では、通学時の安全ということも踏まえながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"めくった２枚目の日野学園の米印のついているところは何なのか。フリーゾーン地域というのは、どういう意味なのか伺いたいと思います。","respondent":"野呂瀬学務課長","answer":"フリーゾーン地域なのですけれども、ここは具体的には大崎駅前のアートヴィレッジ大崎という集合住宅のあるところなのですが、学区域自体は芳水小学校の学区域に含まれているのですけれども、日野学園まで一本で行けるということ、あとＪＲ大崎駅。","id":"exchange-005"}]},{"id":"topic-02","title":"平成２８年度入学希望申請の状況","agenda":"平成２８年度入学希望申請の状況","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"住民基本台帳のところの数なのですが、このところ、地域によってはマンションとかが建設されて増えているようなところがあると思うのですが、基本的に地域的に増えているところはどの辺なのかなということと、希望申請のところの増減というのは、ぱっと見たところは、そんなに去年とかおととしとかと変わらないかなと思っているのですが、その辺の増減のところの要因とか何かがありましたら教えてください。","respondent":"野呂瀬学務課長","answer":"それと、希望の申請ですけれども、これはいつもどおり大体３割で、それ以上、例えば４割というのはここ１０年なくて、学校選択を希望されるのは３割ぐらいの方ということで、今回も２７％から３０％の間ぐらいということで、大体例年どおりの増減だと考えています。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"抽選のところが何校かあるのですけれども、受入枠の決め方をもう一回教えてほしい。住民基本台帳はもともとそこの地域なので、そこの台帳の予定数ぐらいはそこの学校で受け入れてほしいなと思うのですが、そうなっていないところが幾つかある。その辺の理由も含めて、この受入枠、もともとのところが入り切れなくて抽選になってしまうところはどうしてかと思うので、そこを教えてください。","respondent":"野呂瀬学務課長","answer":"ご案内のとおり学校選択というのは、そこの学区域の子が希望すれば、それは１００％抽選でなく入れるということで、実際学区域に対してのいわゆる就学率というのは、住民基本台帳の人口が増えれば増えるほど、やはりそこの学校、自分のところを希望すれば。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"芳水小学校はこれからで、城南小学校もそうなのですけれども、例えば御殿山小学校なんかは、これからも多分増えると思うのですけれども、改築しても結局は学区のほうは飲み込めないというふうになってしまうのですか。これというのは、結局最終的な精査をしていくと何とかなるのですか。","respondent":"野呂瀬学務課長","answer":"学務課のほうとしましても、例えば今年生まれた０歳児は６年後に入学するだろう、来年生まれた子はそのまた６年後と、ずっと毎年シミュレーションをしております。シミュレーションをしているのですけれども、シミュレーションどおりにはなかなかならない。","id":"exchange-008"},{"speaker":"鈴木（博）委員","kind":"質問","question":"抽選のことなのですけれども、これを見てみると、御殿山小学校が９０人の受入枠で１４７人とか、第二延山小学校は９０人に対して１２８人というのは抽選なのだろうなというふうにこちらで見ていてもわかるのですけれども、例えば芳水小学校だとか第三日野小学校というのは、芳水小学校なんかは９０人に対して１０２人、その上の日野学園は９０人に対して９３人、この辺というのは。","respondent":"野呂瀬学務課長","answer":"入学率にしますと、５０％を切っているようなところもありますので、中学校の場合は、受入枠に対して実際の人数はすごくいるのですけれども、大体平均すると中学校の場合は私立へ３０％ぐらいは抜けていくというのがありますので、当然日野学園は去年も抽選をしている。","id":"exchange-009"},{"speaker":"鈴木（博）委員","kind":"質問","question":"どこの学校がどうだこうだとすごくよく知っている。下のほうはがらがらですよね。だから、この辺といのうは、品川区の中の学校の地域格差みたいなものに関して、教育委員会としてはどのように捉えて、長期的にはどういう観点で考えているのでしょうか。さっきお話が出たみたいに、例えば清水台小学校のところはがらがらですよね、中延小学校なんかも。それは、そのままでいいのでしょうか。","respondent":"野呂瀬学務課長","answer":"この通学区域というのは、いわゆるどういうふうにやったら一番適正なのかというのは難しいところがありますし、また学校選択をやっている上で、やはり３割ぐらいの方は必ず学校選択を希望されているというところがあります。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問","question":"中学校のほうは、先ほど３割近くが私立ということだったのですが、小学校のほうの平成２７年度の住民基本台帳の予定数２,６７１人、それで入学者数が２,４９３人、そうすると、それ以外の人は私立に行ったということでいいのでしょうか。","respondent":"野呂瀬学務課長","answer":"ご説明が漏れてしまったかもしれません。委員ご指摘のとおりです。平成２７年度の合計欄ですけれども、２,６７１人の住基人数に対して、実際に公立の小学校に入ったのは２,４９３人ということで、９３％、逆に言えば７％の方が私立に行かれた。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問・要望","question":"そういうものについてちょっと教えていただきたい。中学校のほうで、やはり中学校を見ると、必ず目につくのがこの荏原平塚学園なのですけれども、こちらのほうも学区域の関係とかいろいろあるとは聞いておりますけれども、特に是正する必要はあえてないとは思いますが、この傾向は本当にこのままでいいのかなというのは気になっているところなのですけれども、この２点についてお伺いします。","respondent":"野呂瀬学務課長","answer":"１点目の傾向なのですけれども、やはり平準化しているのは、全体的にはそうかもしれませんけれども、当初、私が冒頭でご説明しましたとおり、やはり何校かにつきましては、例えば１クラスだったのが２クラスになれば、それが絶対というものではないかもしれませんけれども。","id":"exchange-012"},{"speaker":"浅野委員","kind":"意見","question":"それぞれ学校の取組みですとか、そういうことで随分変わってくる可能性も秘めているという、その可能性をぜひともこれからも追求していっていただければと思います。やはり、先ほども申しましたけれども、通学に関して通学路の安全ということについては、これは小学校も中学校も同じですので、やはりしっかりと安全に心がけられるように、そのような取組みをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"やっぱり私たちが思うのは、それをどういうふうに活かしていくのかなと。今さまざまな意見が出たように、特定の学校は住民基本台帳から大きくかけ離れているところもあるし、増えているところはさまざまな理由があるのでしょうからいいのだけれども、やっぱり心配なのは、具体的な手をどう打っているのかというのはなかなか見えてこないのですよ。そのことについて、もしお答えがあれば教えていただきたい。","respondent":"野呂瀬学務課長","answer":"それで、例えば源氏前小学校につきましては、それまで単学級だったのが２学級になったという効果も出ておりますし、今後ＩＣＴとか、そういうところは逆に小規模校ならではの取組みみたいなものもやっておりますので。","id":"exchange-014"},{"speaker":"伊藤副委員長","kind":"質問","question":"選択制を導入するときも相当反対がありましたよね。それで、今おっしゃるとおり一定の効果は出てきたと思う。そうすると、結果的に私立との競争になってくるわけです。それに対して、では現場の校長や、それからさまざまな人たちがどれだけＰＲしているのですかということを、ずっと私は見続けてきたわけです。やっぱり、教育委員会としては、そういう制度になってしまったのだから。","respondent":"野呂瀬学務課長","answer":"その努力というのは、昨日もご説明したように、これからやっぱり地域とともにある学校づくりというところを今までも目指しておりましたけれども、これからはさらにそれを目指さないといけないということで、学校と、学校だと校長先生だけではなく、校長、副校長。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"小規模校支援についてなのですが、先ほども副委員長のほうからいろいろと話を聞いて、まさに学校の取組み、ＩＣＴが進んでいく中で年々増えている学校もあるし、支援があるけれども、そもそも住民基本台帳による数が少ないと、そういったところでなかなか増えていかないというところで、もう一回進んできて、小規模校支援が進んできた効果をどう捉えて、今後支援の一定効果が出ているところと。","respondent":"渋谷指導課長","answer":"具体的に地域との連携を先生たちが進めているときに、何でもかんでも先生たちだけでやるのではなくて、学校を支援する組織をつくるために、学校支援地域本部などというものも考えているところであります。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今何となく小規模だとなくなってしまうみたいな、何かどんどん少なくなっていくという雰囲気があるのですけれども、やはり小規模校のよさも前面に出していただけたらなと思うのと、何とか１クラスの学級を少人数学級にこぎつけていただけると、各学年が複数クラスになるのでいいのではないかなと思うので、その辺をぜひ進めていただきたいなと思うのですが、いかがでしょうか。","respondent":"野呂瀬学務課長","answer":"先ほど言いましたやはりクラス数がというのが入学前のお母さんの心境なのですけれども、実際に入った後にアンケートをとりますと、９０％以上の方がこの学校でよかったというアンケートも出ておりますので、やっぱり入ってみれば。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問","question":"選択制自体、ただいま議論があったので、学校の評価ということをお尋ねしたいのですけれども、最終的にこういう数字が出てきたときに、希望する、多いとか逆に少ないとかというのは、一つの物差しに過ぎないと思っておりまして、いろいろな尺度があって、保護者の意見だとか地域の意見とか、そういう考え方があるのですが、何をもって学校が、何がいいか悪いかと、またそれは議論になるのですけれども。","respondent":"渋谷指導課長","answer":"一つは、やっぱり保護者だったり、子どもたちの学校に対する満足度であったり、子どもの学力の状況だったり、そのほか人間性の育成だったりとかという各種調査、そういったもので総合的に判断するべきものだというふうに考えております。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですから、いろいろな評価があるのだということを、評価という言葉自体がちょっとおかしいかもしれないのですけれども、それを今お話ししていただいたようなことをもうちょっと広く周知していただけると学校に入っている方や携わっている教職員の方も含め、地域のいろいろな考え方がまとまっていくのではないかと思うので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-03","title":"区立保育園の今後の運営","agenda":"区立保育園の今後の運営","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"今読んで、課長の説明をお聞きすると、区立の保育園というのは経費が年間大体８９億円かかって、人件費が５４億円で大体６０％だということなのですけれども、その後に公立園には運営費が、国および都からの補助金が支給されず、運営経費は保護者からの保育料を除き、全て区が一般財源で負担しているということで、これは要するに区立の保育園に関しては。","respondent":"竹田保育課長","answer":"区立保育園の運営経費の件ですが、利用者の方のご負担をいただいているのは、平成２６年度ですと１５.４％ということでございまして、それ以外の経費は基本的には区の財源ですが、一部、都支出金が公立園ですと０.３％、私立ですと都支出金が１１.０％。","id":"exchange-020"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうしますと、結構人件費５０億円というのはかなり負担が大きいということで、これは例えば目的の(2)で、財政負担の低減（運営経費・人件費等）と書いてあるのですけれども、例えば今現在の公立公営というのですか、区立の保育園が民設民営、要するに区立から外れると国および都から負担金というのは支給されるのでしょうか。","respondent":"竹田保育課長","answer":"すみません、もう一度申し上げますが、国および都からの補助金は出まして、おおむね運営費の国が２分の１、都が４分の１です。","id":"exchange-021"},{"speaker":"鈴木（博）委員","kind":"意見","question":"そうすると、例えばここに書いてある公設民営の場合はどうなるのか。","respondent":"竹田保育課長","answer":"公設民営の場合は、まだ公立の種類に属しますので、国および都からは出ないという状況です。","id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、結局今非常に重い負担に関しては、それを軽減するという方向で検討するということは、おおむね必要なことだというふうに理解するのですけれども、あるいはそのときに、今の公設公営を公設民営あるいは民設民営にした場合に、何かデメリットというか、これで注意しなければいけないこととか、こういう点は注意しなければいけないので、こういうことを配慮しながら進めるとか。","respondent":"竹田保育課長","answer":"民営化で当面課題となっていく点ですが、公立から私立に運営の中心が移るということで、今までの保育環境あるいは保育の質が維持されるかどうかというのがポイントとなってきますので、行政としてしっかりチェックして責任を果たしていきたいと考えております。","id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、例えば民設民営を考えるとしても、早急に全部を移行するというのではなくて、全体のバランスを考えながら少しずつ、要するに可能なところに関してはこういうことも検討するということで、スケジュールとしては平成３１年以降ということは、今平成２７年ですから、だからあと４年ぐらい。今いる園児が卒業したぐらいを目安に考えているということなのですか。","respondent":"竹田保育課長","answer":"こちらにお示ししましたのは、最短のスケジュールを想定して書いたものですので、それぞれの施設の状況等によりまして、こちらのスケジュールのほうは変わっていくものです。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"平成２７年度当初予算で８９億円、うち人件費が５４億円ということなのですけれども、民営化、それぞれ手法があるということですけれども、これは文章から、削減されていくということだと思うのですけれども、どれぐらい削減されると見込んでいるのか伺いたいと思います。","respondent":"竹田保育課長","answer":"先ほど申し上げたとおり民設民営になった場合は、国および都からの補助金が出ますので、その部分が削減されるというふうに考えております。区の持ち出しが不要になると考えております。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問","question":"今現在８９億円で、人件費が５４億円、それで区の一般財源で負担しているということなのですけれども、もろもろほかにも一般財源で負担しているものがあると思うのですが、この区立保育園にかかる一般財源は、割合として全体のどれぐらいに当たるのでしょうか。","respondent":"竹田保育課長","answer":"平成２７年度予算で申し上げますと、区立保育園、私立幼稚園の合計の運営費は１３２億７,０００万円余となっております。そのうち、区立保育園の占める割合が８９億８０３万円余となっている状況です。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問","question":"区の一般財源から、全体の、区の全体から〔「全部の予算の中でどれぐらいかかるのか」と呼ぶ者あり〕そうです。すみません。全部の予算の中で、区立の保育園運営費はどれぐらいを占めているのでしょうかということです。","respondent":"竹田保育課長","answer":"区の一般財源に占める区立保育園の運営費ですが、おおむねですが、８.２％となっております。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問","question":"その分がとにかく丸々浮いてくるということだと思うのですけれども、その目的のところに財政負担の低減とあるのですけれども、これだけ軽減させていかなければいけない原因というのは何なのかをちょっと具体的に伺いたいと思います。","respondent":"竹田保育課長","answer":"保育の現状の課題としまして、待機児童の解消あるいは老朽化した保育園の施設等、課題はたくさんあります。こちらで低減できた経費については、待機児童対策等に回していきたいと考えております。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、民間活力の活用をしないと、そういったことが果たせない、改善はできないというふうに考えられているということですか。","respondent":"竹田保育課長","answer":"そういった中で、安定して質の高い保育事業に応えていくためには、一定の民間活力の活用あるいは財政負担の低減が必要だというふうに考えております。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"民間活力で質が維持されるかどうか、先ほど課長もそこがポイントなのだとおっしゃっていましたけれども、維持されるかどうか、この間、維持されてきたわけですけれども、それが民間になることでどうなっていくかわからないというところでは、すごく賭けというか、チャレンジというか、そういった感じがするのですけれども、基本方針の(2)のところに。","respondent":"竹田保育課長","answer":"現在の基本方針としては、１年当たり１園、５園程度を当面の目標としていくわけですけれども、将来的に乳児人口が変動してまいりますので、そういった乳児人口も見極めながら区立保育園の数についてはその時代に合った数にしていきたいと考えております。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問","question":"ちょっと今よくわからなかったのですけれども、要は区立のままとする保育園を相当数残していくわけですよね。これはどれぐらいですか。","respondent":"金子子ども未来事業部長","answer":"先ほど課長が申し上げたとおり、これの経費負担というのは、平成２７年度は、ご案内のとおり子ども・子育て支援新制度が入っていますので、まだちょっと細かい計算はできておりませんけれども。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"すみません。対象園というのは、これから、平成２７年度ということですけれども、行動していくということですけれども、一定のめどはついているのでしょうか。","respondent":"竹田保育課長","answer":"こちらに対象園を選ぶ基準を記載しておりますが、建物の状況、築年数が何年たっているのか、併設施設があるのか、設備の規模等、あるいは運営状況等を総合的に判断して今検討している最中です。","id":"exchange-032"},{"speaker":"浅野委員","kind":"質問・要望","question":"コストダウンにつながるという大きな目標があるということで進められるということですけれども、前例というのでしょうか、過去に公設だったものを民営化するということは、品川区では多分やっていないと思うのですが、やっていたら教えていただきたい。それとあと、ほかの地域でそういうような前例というのは今までにあったのか、もし調査をされているようでしたら教えていただきたいと思います。","respondent":"竹田保育課長","answer":"世田谷区におきましては、民設民営化を５園行ったというところと、あと目黒区につきましても今後４園を民設民営化するという予定と聞いております。","id":"exchange-033"},{"speaker":"浅野委員","kind":"質問","question":"そういう意味では、近くの近隣区でもこういうような形でやっていて、多分目的としてはコストダウンでしょうかね、こちらのほうがメインになっているのだろうなと想像するのですけれども、それが目的となってやっているかというのを一つ教えていただければと思います。","respondent":"竹田保育課長","answer":"今後の乳幼児人口の動向推計ですが、５年ぐらい先にピークが来るという推計が出ておりますので、またその状況に合わせまして、そこから先の計画というのは立てていきたいと考えております。","id":"exchange-034"},{"speaker":"浅野委員","kind":"質問","question":"５年先ぐらいがピークということで、５年間と時期がちょうど合っているなとは思っているのですけれども、民営化基本方針策定が平成２７年度ということは、そんなに期間としては３か月、４か月ぐらいしかない中で、どのようなものが策定をされるのかなというのがちょっと気になったので、具体的な内容というわけにはいかないと思いますけれども。","respondent":"竹田保育課長","answer":"今お示しさせていただいている基本方針が骨子ですので、こちらに肉づけしていくような形で作成していきたいと考えています。区民の方がご覧になってわかりやすいようなものにしていきたいと考えております。","id":"exchange-035"},{"speaker":"浅野委員","kind":"質問","question":"いずれ出てくるかと思いますので、そのときにまた機会があったら教えていただければと思います。なぜ今さら民営化するのかとか、そういう意見も出てくるだろうし、中にはやはり民営化すべきだという方も多分おられると思います。そのようなご意見をしっかりと受けとめて、区民の方にわかりやすい説明、区の意図が通じるような説明をしっかりと行っていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その思いだけを先にお伝えして質問をしたいと思いますけれども、まず改めてなぜ民営化なのか。財政の負担低減のところは、先ほど伺ったのでわかりました。民営化をするということ自体、一体何を期待して民営化するのか改めて伺うのと、保育園はこのことによって、よくなるのでしょうか。その点をお伺いしたいと思います。","respondent":"竹田保育課長","answer":"区民ニーズに対応した多様な保育サービスを将来にわたって安定的に提供していくことが必要だと思います。そのためには、一定のコスト軽減というのも必要です。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"今から先を見通して、今の状況を続けていかないと安定しないと、民営化をしないと困難になっていくということなのか、ちょっとそこが１点と、あと良好な保育環境と課長がおっしゃいましたので、民営化をしていくと、今よりも保育の環境がよくなるということで、きちんと受けとめてよろしいのでしょうか。","respondent":"竹田保育課長","answer":"そういったものに対応していくためには、一定の経費削減も必要だと考えております。それから先ほど私が申し上げたのは、利用者にとって快適で安全な保育環境を整備していくことが必要だというふうに申し上げておりますので、そういったことを実現していきたいと考えております。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"それが民営化につながるというのはとても理解できないので、そこも１回聞きしたいのと、あと財政負担の低減のところなのですが、国からも都からも公設公営、区営だとお金が入らないということなのですけれども、財調のところで、人員的にお金が入っていると思うのですが、財調人員というのはどうなっているのか、ちょっと私もよくそこがわからないのですが。","respondent":"金子子ども未来事業部長","answer":"先ほど来課長が説明しておりますのは、改めて一度おさらいしますと、委員もご承知だとは思いますが、民設民営であるといわゆる公定価格というのが新しい制度で定められましたので、これについての国の負担、都の負担というのが出てくる。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"そういう解釈ですよ。やっぱりその辺でちゃんときちんと、だったら財調で保育園が何園で、財調人員は何人来ていて、どのくらい、お金に色はついていないですよ。ついてはいないけれども、財調人員の中にはそうやって保育園、当たり前の保育園のところの財調のところが含まれているという受けとめ方も、ちゃんとしていかないとまずいのではないですか。","respondent":"金子子ども未来事業部長","answer":"だから、そういう意味で、先ほども申し上げたとおり、公設公営の園と民設民営の園では、１園当たり、大ざっぱに言って５,０００万円ほど違うというふうになりますと、これは公設公営の園を５０園持っているところと民設民営の園を５０園持っているところでは。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"意見","question":"今のところはわかりました。でも、全くお金が入っていないという言い方は、明らかに違うなと思うので、そこは私は押えていきたいと思います。経費削減のところはわかりました。でも、保育園というのはお金の問題で比較、もちろん比較はあるのかもしれませんけれども、もっともっと大事なところがあるなというところで、ちょっと聞きたいことがいっぱいあるのでどんどん聞いていきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いつからどこで検討を進めているのかというところを一つお伺いしたいのと、あとよりよい自治体は審議会などでメンバーにいろいろな方を、学識経験者、教職員、地元の方、あと保護者の方とかを加えて審議会を立ち上げて何年もかかって議論を深めている上で答申を出しているというところがあるので、私はぜひ民営化基本方針、よもや行政のメンバーだけではないと思いたいのですが。","respondent":"金子子ども未来事業部長、竹田保育課長","answer":"そういう意味では、当然のことながら、品川区としても一定の検証をするために公設民営、民設民営という作業をしますけれども、その中で移行の手順というものを品川区としてもきちっと確立をしていこう。基本方針のお尋ねですが、こちらにお示しした資料全てがある意味では基本方針ですので、こういった考え方に沿って今後検討してまいりたいと思います。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味では、保育課とか子ども未来部のほうだけで検討するのではなく、ぜひ外部の方も入れて、保護者の方の意見を聞く場を設けたりといった形で意見を聞いていくという姿勢をぜひ持っていただきたいのですが、この点はいかがでしょうか。","respondent":"金子子ども未来事業部長","answer":"そういう意味では、私どもとしましては、所管の中できちっと課題を抽出し、問題の解決というのは探っていくつもりですけれども、必要に応じて外部の方を含めた検討というのも必要だと思います。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"財政負担の低減をたびたび説明いただいたのですが、公設公営の公立保育園の役割というのをどう捉えていらっしゃるのか、公立保育園の役割についてどう考えているのかをちょっとお聞きしたいのと、やはりコストも大事かもしれないけれども、コストで失われてしまう大事なものがあるので、私は保育園というのは人を育てる場であり、命を守る場であるので、命を守る、育むために何が必要なのか。","respondent":"竹田保育課長","answer":"今後の民営化後のお話ですけれども、保護者の方、事業者の方と十分協議しながら新たに出てきた問題や課題については対応していきたいと考えております。それから、公立の役割ですが、今までも質の高い保育というのを品川区では追求してまいりました。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、相当数残すとはあるのですけれども、私は心配です。介護だって、今見てください。そういった面では、保育園のところは絶対握って離さないでほしいので、その辺とても心配なので、ちょっと公設公営、区立の保育園の役割、しっかり握っていただきたいのですけれども、最後にお願いいたします。","respondent":"金子子ども未来事業部長","answer":"そういう意味では、介護のほうでも、ちょっと認識が違うかもしれませんけれども、最初から公設公営で公務員がやるというのは、それほど多くはなかったのではないかなというふうに思います。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今部長からご答弁いただいて民設民営でも保育の質は保てるとあったので、ちょっと保育の質の問題は、先ほどからコストの問題が出ていましたけれども、民営化で財政効率を軽減できるという大もとは人件費なのですよね。人件費なのですよ。保育の質を守ることはとても重要なので、コストのところと天秤にはかけないでいただきたいなということを言って終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"大倉委員","kind":"質問・要望","question":"１園５,０００万円ぐらい経費を、大ざっぱに言うとそうなって、安定的な保育の質の確保とか良好な環境に資するように今後取り組んでいくのだということで、他区を見ても千代田区以外はそういった導入があって、課題出しあっての検証がされて、今後は移行の課題があるので、その中でしっかりとそれを気にしながらやっていくというところで、１点だけ教えていただきたいのですが。","respondent":"伊崎子ども育成課長","answer":"一つには子ども・子育て支援法の関係ですけれども、こちらでは各自治体が保育の関係で申し上げますと、それぞれの保育のさまざまな需要を見込みまして、その需要を満たすために区でどういった施策を打っていくかという計画を数で立てていったものです。","id":"exchange-047"},{"speaker":"大倉委員","kind":"質問・要望","question":"そもそも求めるものが違うので、そういったところでの話はなかったということだと思いますけれども、最後に方針について決めていくというところでは、こういった平成２２年から研究しだしたというか、方向性としては民営化というところを考えられるという中においては、そういったところで意見を聞くというのはできなかったのかなというところはどうでしょうか。","respondent":"伊崎子ども育成課長","answer":"今後検討してまいりたいと思います。","id":"exchange-048"},{"speaker":"高橋（し）委員","kind":"質問","question":"それからもう一つ、子ども・子育て会議のほうで、今審議事項ではないというお話だったのですが、公募区民の方もいらっしゃいますし、大学の先生もいらっしゃいますし、保育園、幼稚園関係の方もいらっしゃるので、これは会長の判断だと思うのですが、今ほかの委員からもありましたけれども、話し合いの決定事項ではないので意見を伺うという形になるのかもしれませんけれども。","respondent":"竹田保育課長、伊崎子ども育成課長","answer":"人件費については、ちょっと今手元に資料がないので、わからないところです。それから、０歳児園かどうか、在園児に対する影響ですが、今後それも含めて検討しています。子ども・子育て会議の一定の議論につきましては、いただいたご意見を踏まえまして会長、副会長とご相談してまいります。","id":"exchange-049"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほど私が勝手に０歳児がいないところという話をしたのですが、「平成２８年度～」の「～」というのが、平成２８年度に説明会をするのか、平成２９年度なのかちょっと微妙な表現なのでちょっとあれなのですが、仮に平成２８年度から説明会をすると、平成２８年度に在籍されているお子さんは在籍中の最後の段階で民営化される可能性があるので、そこも含めて、つまり今年募集は始まるわけですから。","respondent":"竹田保育課長","answer":"こちらの運営業務委託も平成３１年度以降というふうに記載させていただいておりまして、これは平成３１年度に実施するということではございませんので、ちょっと実施時期も踏まえながら、在園児の影響も考えながら今検討しています。","id":"exchange-050"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今お話があった影響等をよく考えていただいて、説明や手続などは丁寧にしっかりと行って、円滑に制度の変更ができるように注意を払っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"だから、そういうことをしっかり議会として見つめていきたいと思うので、保育園の今後の運営についてもそういう今までやってきた経過を踏まえた上で何度も繰り返すけれども、サービス低下はさせない、だけれども、コストは削減していく、そういう方向でやっていかなければいけないと思うのだけれども、改めて品川区のお考えをお聞かせいただきたいのと、私たちはずっと言っているのだけれども。","respondent":"竹田保育課長","answer":"保育を実施していく中で、公立でも私立であっても適切な保育環境や職員の能力等の保育の質を確保していくということは、公立でも私立でも大変大事なことだと考えています。","id":"exchange-052"},{"speaker":"伊藤副委員長","kind":"意見","question":"必ずやるわけではない。聖域なき構造改革というテーマを昔小泉元総理が語っていましたよね。あのとき、相当大きな支持があったことは記憶に新しいですよ。品川区だって同じことが言えるわけで、私たちも含めて、もちろん議会もそうなのだけれども、さまざまな部署で行革、コスト削減、それからサービス低下がないような対応をぜひとっていただきますようにお願いしておきます。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"}]},{"id":"topic-04","title":"認証保育所の新規開設について","agenda":"認証保育所の新規開設について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"この設置者の長谷川キッズライフ株式会社というのは、品川区で初めてですかね。そう思っているのですが、どのような会社なのか教えてください。","respondent":"今井待機児童対策担当課長","answer":"長谷川キッズライフ株式会社につきましては、会社が名称変更いたしまして、今年の４月１日に南品川で認可保育園、太陽の子南品川を開設したところと同じ事業者です。","id":"exchange-054"}]},{"id":"topic-05","title":"都市公園内における認可保育園の開設について","agenda":"都市公園内における認可保育園の開設について","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"２点だけお願いします。一つは、開設から１０年間と書いてあるのですが、なぜ１０年間と区切られるのでしょうか。それとあと、公園の中に含むということで、一番保育園をつくるときの障害になっている地域住民からの反対の声というのはあまりないと思うのですけれども、実際にこれをつくったときに、例えば駐輪場だとか、それはこの計画地の中につくるのですか。","respondent":"今井待機児童対策担当課長","answer":"初めに、都市公園法の緩和によりまして、今回特区として占用期間として、開設ではなくて、占用期間として認められる期間は１０年間、更新を妨げないとなっております。","id":"exchange-055"},{"speaker":"鈴木（博）委員","kind":"質問","question":"この地図を見ると、ニコンと公園の間に細い道があるのですが、自転車だとかバギーで送迎する場合、まさか公園の中を通るというわけにはいきませんのでここのところを通ることになるのですか。","respondent":"今井待機児童対策担当課長","answer":"これは公園課と今後協議するところですけれども、地域住民の方の要望で、計画地と道路のところに少しスペースがあいているのですが、ここが３ｍほどある予定です。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"開設から１０年間、今お話を聞いたら延長も可能であるということなのですけれども、期限つきということもあって、私立というところをぜひ私立でなく、お願いしたいなと思っているのですけれども。これは公設ではないですよね。ここの箇所というのは別に有害な何かが出たとかではなくて、土壌改良というのはどういう立場でしたのか、ちょっと教えてください。","respondent":"今井待機児童対策担当課長","answer":"裏面のこの地図の中に、公園課の資料の抜粋ですが、土壌改良というふうに入っておりますが、今日の建設委員会で所管事項として報告したと聞いておりますが、一定量の計画に伴って鉛が検出されたと聞いておりまして。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問","question":"私立の認可保育所ということなのですけれども、これというのは東京都が土地を貸すということになるのですか。ちょっとごめんなさい、そこがわからないので教えてください。","respondent":"今井待機児童対策担当課長","answer":"西大井広場公園は区立の西大井広場公園ですので、区が占用許可を出す立場にあります。","id":"exchange-058"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"先ほどのご答弁の中で、子ども・子育て会議で１０年というのが聞き取れなかったので、すみません、そこのところと、このプロポーザル、今条件を二つ挙げていらっしゃったのですが、そのほかに求める条件があれば教えていただきたい。三つ目は鉛の話で、建設委員会の話になるかもわかりませんが、東京都のルールで使用していいよというのが出たのでこの話になったという理解でよろしいでしょうか。","respondent":"今井待機児童対策担当課長","answer":"ただし、この公園につきましては、開設から１０年間は運営を担保することで運営事業者、そして区民の皆様にも周知していただくために、最低１０年間は事業をやりますということでご説明しています。","id":"exchange-059"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"ちょっと１点だけお伺いしたい。Ａ４判１枚の２３区の保育サービスのところなのですけれども、品川区とその直前に出ている江東区の比較なのですが、江東区のほうが就学前児童人数も保育サービスを利用している児童数も多いが、その３番目の人口比率はほとんど同じぐらいなのですけれども、何で品川区のほうが待機児童数が多いのか。","respondent":"今井待機児童対策担当課長","answer":"ご案内のとおり、例えばその下の近隣の目黒区は品川区より１０％ポイントが低くても、そんなに倍にはならないわけですよね。これはやはり、その自治体ごとの就労を希望する女性の割合ですとか、そういうことが影響すると思います。","id":"exchange-060"},{"speaker":"鈴木（博）委員","kind":"質問","question":"あまり待機児童数の数だけを絶対値にして評価しても、それほど重みはないということでよろしいのでしょうか。","respondent":"今井待機児童対策担当課長","answer":"ご案内のとおりいろいろな保育の、その辺を分析した雑誌が出ておりますけれども、委員ご指摘のとおりやはりどのくらいの希望者の方がこのように人口比率で利用されているかという、いわゆる整備率ですね、これも大きな指標になるというふうに認識しております。","id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問","question":"全体的な表にして出していただいたのですけれども、これを進めていったというところでの区としての評価と課題は何かを伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"それの一つの解決策が今回の国家戦略特区の公園の活用などというふうな方策だと思います。南品川のくりのき保育園でありました国有地の活用、このようなさまざまな手法をとりながら開設を進めていかないとなかなか課題の解決には至らないという認識でおります。","id":"exchange-062"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほども言ったように女性の就労率、女性というか、子育て世代の就労率や保育需要が高まっている中で、新規開設もどんどんしている状況だと思うのですけれども、以前から品川区が皆さんからの質問などでも答えていただいているように、子どもはやがて少子化によって少なくなっていくので、保育園はどんどん建てても財政負担になっていくというようなお話も多々あったのですけれども。","respondent":"今井待機児童対策担当課長","answer":"その考えに変わりはございません。","id":"exchange-063"},{"speaker":"石田（ち）委員","kind":"意見","question":"こういった増設等々で経費がかさんでいくということですけれども、やっぱり子育て支援、そしてこうやって働く子育て世帯が多い中で、もっともっと保育需要は高まっていくというふうにおっしゃっている中で、やっぱりそこにしっかりと税金を使っていく、経費がかさむというところではなくて、十分に使っていく、そして子育て応援と将来を担う子どもたちを育てていくというところだと思うのですけれども。","respondent":"今井待機児童対策担当課長","answer":"先ほど申しましたとおり総合的待機児童対策で進めていく考えで、認可保育園だけではなく、認証、小規模を含めて開設していくという考えに変わりはございません。","id":"exchange-064"},{"speaker":"浅野委員","kind":"提案","question":"一覧表を見ますと、数字と文字が多くて理解するのが非常に大変かなと思っているのですけれども、その中で何点かお伺いしたいのですが、特に私立の保育施設についてなのですけれども、民間のほうで建設もあれば、いろいろな、小規模保育、家庭的保育があるということなのですけれども、このような話というのは。","respondent":"今井待機児童対策担当課長","answer":"ただ、もう一つは、基本的には品川区のほうは企画提案型という形で進めておりますので、これは逆に言うと随時事業者のほうにホームページ等で情報提供いたしまして、品川区が今後何園開設するかという情報提供をもとに提案していただきまして。","id":"exchange-065"},{"speaker":"浅野委員","kind":"質問","question":"認証保育所、東京都の認証ということですけれども、こちらの場合も似たようなというのでしょうか、そういうようなやり方をやられているのか、あえて認証で保育所としてとかないのか、そのような動きというのは同じようにやっているのでしょうか。その場合、都との関係とか、そういうものはどうなるのか教えてください。","respondent":"今井待機児童対策担当課長","answer":"認証保育所に関しましては、先ほどもご報告のとおり認可と違いまして東京都のほうに事前に資料をご説明して、場所等も含めましてご相談するという一定の協議がありますけれども、ほぼ認可保育園と開設のスキームといいますか、それは同じです。企画提案型で進めております。","id":"exchange-066"},{"speaker":"浅野委員","kind":"質問","question":"保育園を建設する上で、地元説明会とかをされる中で、反対もあったというような話も伺っておりますけれども、これは最近の傾向なのか、もっと前からそういうような反対とかそういうものがあってできなくなったケースとかがあるかと思うのですけれども、その経過を踏まえながら最近はどのような状況なのかというのを教えていただければと思います。","respondent":"今井待機児童対策担当課長","answer":"この声が高まってきたのは、公立、私立を含めて平成２５年度頃から、待機児童解消加速化プランですとか、子ども・子育て支援制度の中で、やっぱり認可保育園や認証保育所などをどんどんつくっていこうということが報道される中で、子どもの声がうるさいですとか。","id":"exchange-067"},{"speaker":"浅野委員","kind":"質問","question":"最近になりまして、武蔵小山ですとか西小山ですとかぽつぽつと増えてきて、喜ばしいことかなと思いまして、よく相談を受ける場合にも増えているよみたいな話はするのですけれども、そういう意味では、地域ごとというのは、どこまでが地域かと分けるほうも難しいと思うのですけれども、現状の中で、やはり入りやすいとか、入りにくいとか、そういう差があるかと思うのですけれども。","respondent":"今井待機児童対策担当課長","answer":"ただ、今ご指摘のとおり荏原地区につきましては、確かに待機児童の、認可保育園の開設が今まで、今回認可が一つと小規模が二つあきますけれども、少なかったこともありますけれども、いまだに逆に言うと大崎、五反田地区もまだ多い状況になっておりますので。","id":"exchange-068"},{"speaker":"浅野委員","kind":"意見","question":"そういう意味では、特に建設できるかとか、設置ができるかということについては非常に難しいところがありますけれども、チャンスが来たならば、ご両親の希望に応えられるようにしていただければと思います。これも建ててみないとわからない部分もあるかと思いますけれども、１件でも多くそういう声を、事業者の声を聞きながら適切な場所を選んで建設をしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問","question":"わかりやすい資料をつくっていただいてありがとうあります。とても全体がよく見えていい資料だと思います。小規模保育所が本当にたくさんできているのですが、その辺、前にも伺ったりしたのですが、３歳以降の受け皿、５年以内に何とかするということなのですが、この辺は目処がたつのかどうかというのが１点。","respondent":"今井待機児童対策担当課長","answer":"それから２点目ですけれども、小規模保育の３歳児以降の受入れですが、こちらにつきましては、小規模は法的に５年以内にということで求められておりますので、やはりどのような形で、今は調整加点で小規模の方はプラスしていますけれども。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"認証の問題もかなり前にも閉園とかで保護者の皆さんがその後の対策、区のほうもそうですけれども、苦労したという話を聞いたので、ぜひしっかりつかんでいただいて、あわせてやっていただければと思います。だから、そういった意味で、ぜひ公設の区立の認可保育園をこの中に位置づけていっていただきたいなというお願いなのですけれども、いかがでしょうか。","respondent":"今井待機児童対策担当課長","answer":"今後も公設公営だけにこだわらず、公設民営、民設民営、幅広い視点から認可保育園については開設を進めるものです。","id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問・要望","question":"公設公営にこだわらずという意味なので、この中にきちんと位置づけていただきたい。よろしくお願いします。委員長にお伺いしたいのですが、待機児対策というのはまだこのほかにも、これでおしまいですか。そういった意味では、この数字の違いなんかもあらわれているのかなとも思うのですが、こういうところもぜひ掘り下げてやっていただきたいなと思うのですが、１回で終わりなのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"飯沼委員","kind":"質問","question":"でも、旺盛に所管事務調査が行われていることはとても重要だと思うので、またどこかで質問したときに、事前に委員長にお断りして、その他のところとかで若干取り上げするというのは構いませんか。","respondent":"塚本委員長","answer":"そのときの状況によってなので、その折に検討させていただきたいと思います。","id":"exchange-073"},{"speaker":"大倉委員","kind":"質問・要望","question":"先ほど、今後も新規を含め、しっかりと待機児童対策を行っていくという中で、特区の活用でも都市公園の利用というところがあったのですが、例えばそもそも保育園を設置するときの規制とかさまざまな要件とかというのがあると思うのですが、そういったところで特区の活用というのもあるのではないかなと思うのですが、その辺は区としてはどのように捉えていて、どのような考え方をしているのか、しているか。","respondent":"今井待機児童対策担当課長","answer":"そのほか、また弾力的に運用できるものにつきましては、また私どももそこは十分研究検討しながら２３区合同で検討していかないと、あくまでも認可保育園というのは東京都が認可するものですので、なかなか国の通知ですとか。","id":"exchange-074"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひいろいろなところでそういった多くの施設がつくれるように、またクリアできるようにしていっていただきたいのですが、東京都でやらなければいけないということで、２３区の中でどういった連携がとられていて、どういったお話になっているのかわかれば教えてください。","respondent":"今井待機児童対策担当課長","answer":"これは規制緩和だけのお話ではありませんけれども、例えば財政負担ですとか、補助金ですとかは区長会の事務局を通して東京都に上げる、または国に上げるというのがありますし、議長会からも財政負担ですとか、そういうことに関しまして。","id":"exchange-075"},{"speaker":"高橋（し）委員","kind":"確認","question":"小さいほうの資料で、待機児童数についての数の確認ですが、これは区によって算定の基準が違うということでよろしいのでしょうか。これが一つ。これは意見です。","respondent":"今井待機児童対策担当課長","answer":"民間活力の導入につきましては、ご意見として頂戴いたしましたので、今後も家賃補助など区の単独の補助等がありますので、そういうものをもう一回再検討しながら、他区の事例を見ながら、また民間保育施設の誘致に進めていきたいと考えています。","id":"exchange-076"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"２点目の幼保連携認定こども園、城南小学校のところはわかりました。やはり、子ども・子育て制度の中で待機児童も一緒に考えていっていただいて、もちろん待機児童対策で大変言われているのは重々承知していますが、新たな仕組みをできるだけ、少しずつでもいいので取り入れていただきたいという要望があります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"塚本委員長","kind":"質問・要望","question":"現在、認可保育園を新たにつくって、新規開設でこれから対応していこうということが一つの話としてある中で、なかなかやっぱり難しいなと見送ってしまうという事態が意外と品川区内でもあるものなのか、事例として何件か、具体的にあればちょっと、計画になって潰れるとかというのではなくて、検討段階でやっぱりちょっと見送ってしまうというようなことというのはどれぐらい起こっているのか。","respondent":"今井待機児童対策担当課長","answer":"逆に、その近隣の整備用地ですとか、マンションですとか、例えば事務所用地の一緒に入居されている皆様の状況ですとか、あとは近隣がどのくらいその土地に密接して建てているかという中で。","id":"exchange-078"}]},{"id":"topic-07","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この定時制高校廃止に反対をという質問だったのですけれども、定時制高校存続という考えが区にあるのかどうかということをお聞きしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"そのため、都立の小山台高等学校定時制の存続等につきましては、現在生徒の進路指導の際の進路先の選択肢の一つとありますので、この辺につきましては、情報収集に努めてまいりたいというふうに考えているところです。","id":"exchange-079"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/111718?Template=document&Id=4872#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":59112,"voices":210}}]);
